import{_ as t,C as r,o as p,c,am as n,j as a,a as i,E as s,w as o}from"./chunks/framework._FJXuPhs.js";const P=JSON.parse('{"title":"Java面试速刷_第三版","description":"","frontmatter":{"title":"Java面试速刷_第三版","excerpt":"摘要","date":"2026-11-05 21:28:16","updated":"2026-11-05 21:28:16"},"headers":[],"relativePath":"面试准备/面试煎熬成蛋/面试煎熬成蛋_面试速刷版_第二版/Java面试速刷_第三版.md","filePath":"面试准备/面试煎熬成蛋/面试煎熬成蛋_面试速刷版_第二版/Java面试速刷_第三版.md","lastUpdated":null}'),d={name:"面试准备/面试煎熬成蛋/面试煎熬成蛋_面试速刷版_第二版/Java面试速刷_第三版.md"},u={tabindex:"0"};function h(g,l,b,m,q,k){const e=r("font");return p(),c("div",null,[l[24]||(l[24]=n(`<h3 id="项目方面-最近一个项目" tabindex="-1">项目方面 - 最近一个项目 <a class="header-anchor" href="#项目方面-最近一个项目" aria-label="Permalink to &quot;项目方面 - 最近一个项目&quot;">​</a></h3><p>项目概述：本平台面向公司内部业务人员及外部供应商，致力于将线下营销活动流程全面线上化。核心涵盖活动管理（AOC 活动、MRS 店铺活动、趋势跟卖活动等）、规则维护、价格体系、供应商报名及店铺运营等模块。实现从商品中台下发的商品拆分、活动下发、自营/供应商报名到预算分配的全链路闭环，大幅降低人工干预与运营成本。</p><p>技术栈：Spring Boot + MySQL + Redis + Elasticsearch + Kafka + XXL-Job + SpringEvent 等。</p><p>职责：</p><ol><li>活动异动流程优化：针对高频活动异动场景，重构处理流程，采用分批消费、小步快跑的异步控制策略，有效平抑系统流量峰值，提升系统吞吐量与稳定性，处理耗时从42小时缩短到 8 小时；</li><li>活动体系架构重构： 25 年活动体系改造，运用策略模式、模板方法模式对活动核心链路进行抽象。沉淀统一标准模板以支撑 AOC 活动、MRS 店铺活动及趋势跟卖等不同策略的实现，极大提升了代码复用性与后续迭代效率，新活动类型同流程接入从15 天缩短到平均 6天。</li><li>SKC 商品公共属性抽离与 ES 查询优化：抽离商品 SKC 公共属性（店铺 ID、商品层次、标签等），构建独立 SKC 表。将公共属性及变更监听统一汇入 ES 大索引集合，针对不同活动 ID 和类型，采用 ES 子集合字段（嵌套文档）精准控制查询范围。同时，实现同一套监听机制下的精准字段级增量更新，大幅降低 ES 写入压力并提升查询性能。</li><li>扣款单生成判定链路接入：负责订单接入后的扣款判定链路，按「解析订单报文 → 提取订单号 → 查询 SKC 商品信息 → 取出库时间 → 判定是否命中自营店铺活动 → 输出扣款结论」处理 AOC 等多类活动，覆盖订单缺失 SKC、出库时间跨活动周期、活动已下线等异常分支。</li><li>营销工作台：选品圈品与补贴测算：把选品、圈品、规则配置到下发报名全流程线上化，支持多规则叠加圈选与下发前模拟预演（先算不落库），并按目标利润反推采购价降幅、测算补贴额，结果写入 SR 表供数仓加工。</li><li>活动复盘模块：按业务视角（部门 / 店铺 / 活动类型）聚合活动结束后的销量、UV、点击量等指标，负责指标口径与数仓的对齐和校验后落地。</li><li>大商品列表性能优化：针对大体量商品列表查询场景，引入线程池 + CompletableFuture 进行并发查询与数据聚合，显著缩短接口响应时间（RT）。</li></ol><hr><p>每个问题按这 6 行准备：</p><ul><li><strong>背景</strong>：为什么做</li><li><strong>方案</strong>：核心设计</li><li><strong>细节</strong>：关键表/消息/ES DSL/线程池参数</li><li><strong>异常</strong>：重复、失败、延迟、乱序、补偿</li><li><strong>指标</strong>：QPS、RT、积压、写入量、失败率、人工减少</li><li><strong>权衡</strong>：为什么不用另一个方案，如果重做怎么改</li></ul><p>优先准备 <strong>P0：项目整体链路、活动异动、活动体系重构、SKC+ES、扣款幂等/事务、大列表线程池</strong> 这 6 块。</p><h4 id="这个平台解决的核心业务痛点是什么-线上化前后流程差异在哪" tabindex="-1">这个平台解决的核心业务痛点是什么？线上化前后流程差异在哪？ <a class="header-anchor" href="#这个平台解决的核心业务痛点是什么-线上化前后流程差异在哪" aria-label="Permalink to &quot;这个平台解决的核心业务痛点是什么？线上化前后流程差异在哪？&quot;">​</a></h4><p>电商的商品，其实在新建款的时候，会绑定对应的供应商ID和店铺ID，这个项目其实是针对专门的自营店铺的款，进行单独管理和处理。提供供应商报名入口，他的盈利模式，是通过供应商进行报名，会提供采购价和编辑采购价降幅；</p><p>报名入口的上游的商品中台，可以理解是商品的前端界面入口，不过这个是另外是另外一个系统的业务边界，我们业务内部是称为供货价。我们这一套玩法，其实就是基于采购价、成本价和供货价，之间的差额做一些业务上的动作。</p><p>而只要产生实际订单，我们会判断是否真的参加过我们系统的活动，如果判断已经参加且生效，则会进行定时任务扣款发起操作，生成扣款单和扣款明细。</p><p>我们针对活动业务，其实有比如 白名单活动下发、规则下发、活动报名、智能测算、报名平台等操作。</p><p>线上化流程在于就是提供了一个是系统级别的入口，方便和其他系统联动，能做的业务其实还挺多的，不过业务边界还是限定在自营店铺商品这个圈品池内。</p><h4 id="内部业务人员和外部供应商分别怎么使用-权限和入口怎么隔离" tabindex="-1">内部业务人员和外部供应商分别怎么使用？权限和入口怎么隔离？ <a class="header-anchor" href="#内部业务人员和外部供应商分别怎么使用-权限和入口怎么隔离" aria-label="Permalink to &quot;内部业务人员和外部供应商分别怎么使用？权限和入口怎么隔离？&quot;">​</a></h4><p>我们区分了两个入口，内部使用工号，外部使用供应商ID。在方法层面上，能操作的动作其实就不一样。</p><h4 id="系统日均活动量、商品量、供应商数、qps、峰值流量大概多少" tabindex="-1">系统日均活动量、商品量、供应商数、QPS、峰值流量大概多少？ <a class="header-anchor" href="#系统日均活动量、商品量、供应商数、qps、峰值流量大概多少" aria-label="Permalink to &quot;系统日均活动量、商品量、供应商数、QPS、峰值流量大概多少？&quot;">​</a></h4><p>我们一般单个活动有 100 - 200左右的商品数量，每一天都活动大概是 1 - 5 个左右。不过有时候也是有一些小活动，可能只有几万的商品这种。</p><p>供应商数量不一定，看实际对应的店铺下的供应商ID数量。</p><p>QPS，外部访问接口，我们有提供外部库存接口和查询活动等接口，这种外部接口的访问频率是最高的，不过也大概在100 QPS 范围内。峰值就是100.</p><h4 id="你负责的模块在链路中的位置-上下游系统有哪些" tabindex="-1">你负责的模块在链路中的位置？上下游系统有哪些？ <a class="header-anchor" href="#你负责的模块在链路中的位置-上下游系统有哪些" aria-label="Permalink to &quot;你负责的模块在链路中的位置？上下游系统有哪些？&quot;">​</a></h4><p>我主要负责 活动异动、活动报名 的流程，上游的系统主要有数仓、商品中台、价格PCC等系统，下游主要有MRS、WMS、MES等。</p><h4 id="项目最大的技术难点是什么-你个人最大的贡献是什么" tabindex="-1">项目最大的技术难点是什么？你个人最大的贡献是什么？ <a class="header-anchor" href="#项目最大的技术难点是什么-你个人最大的贡献是什么" aria-label="Permalink to &quot;项目最大的技术难点是什么？你个人最大的贡献是什么？&quot;">​</a></h4><p>最大的技术难点，目前是活动异动流程的优化，我们一般最开始为了快速搭建这个项目，采用了挺多串行链路，最开始也使用了部分MQ进行异步操作，不过维度粒度比较大，是直接到单个活动维度，一个活动从下发到真正落表的流程可能要一天多。</p><p>接手后，最开始做的方式还是先定位耗时步骤，先记录日志，将每一步的耗时打印，收集一周左右的日志耗时后，开始写方案动手。</p><p>第一版方案是 将商品的数量通过MQ拆分，比如一个平台商品200W拆分10000一批，使用 redis 写计数器，只有计数器 到 0 的时候，判断这一步算最后阶段，才进入下一个步骤。</p><p>这里其实还是有衡量，是MQ 的并行度设置和 分批数量，并行度高会导致MySQL 的CPU飙升，折中还是取了2，分批数量使用 apollo 数量控制，最后慢慢发现设置到 1000 反而是一个很好的数量，这个也是慢慢的通过监控耗时日志获取的。</p><p>后面随着 skills 的流行，公司架构组也有通用的 skills，不过一般是线上的 skills ，我做类似的工作也是先封装好自己的 skills，然后再调用查询日志或者数据库的数据，出一个大概报告，这个工作减轻了我很多的工作量。</p><p>类似的一个思路吧，通过这种方式慢慢优化，将耗时最后控制到了 8 小时左右，符合业务预期，效果提升也比较明显。</p><p>第二个技术难点，就是将活动报名的流程通过策略的方式接耦，我们当时其实已经有多个活动在跑了。整体思路是想定时这一套活动流程，后续活动流程都能接入。</p><hr><h3 id="项目方面-第二个项目" tabindex="-1">项目方面 - 第二个项目 <a class="header-anchor" href="#项目方面-第二个项目" aria-label="Permalink to &quot;项目方面 - 第二个项目&quot;">​</a></h3><h3 id="基础" tabindex="-1">基础 <a class="header-anchor" href="#基础" aria-label="Permalink to &quot;基础&quot;">​</a></h3><h4 id="讲一下-jdk-jre-jvm-的区别。" tabindex="-1">讲一下 JDK / JRE / JVM 的区别。 <a class="header-anchor" href="#讲一下-jdk-jre-jvm-的区别。" aria-label="Permalink to &quot;讲一下 JDK / JRE / JVM 的区别。&quot;">​</a></h4><ul><li>JDK 是标准开发包，提供编译、运行Java的工具和资源。编译是JDK 做的，可以将 java 文件编译为 .class 文件。</li><li>JRE：Java 运行环境，JDK 包含 JRE，有了 JRE，就可以运行 Java 的编译后的程序。比如 JAR 包，不过他不负责开发过程中的编译，只负责运行。JRE 实际包含了 JVM 和一些核心类库。</li><li>JVM：Java 虚拟机，相当于处理内核，职责单一，负责运行字节码文件。不同系统可以有不同的虚拟机，能够识别 .class 字节码文件，然后运行。</li></ul><p>注意一下版本区分，<strong>JDK 11 及以后：主流发行版停止单独提供 JRE</strong>。</p><p>在现代 Java 开发中，标准做法是使用 JDK 自带的 <strong><code>jlink</code></strong> 工具，根据应用实际需要的模块，<strong>生成一个自定义的、轻量级的运行时镜像</strong>。这个镜像在功能上就扮演了昔日 JRE 的角色，但体积更小、攻击面也更小，非常适合容器化部署</p><h4 id="hashcode-与-equals-的关系" tabindex="-1">hashCode 与 equals 的关系 <a class="header-anchor" href="#hashcode-与-equals-的关系" aria-label="Permalink to &quot;hashCode 与 equals 的关系&quot;">​</a></h4><ul><li>hashCode() <ul><li>返回对象的哈希码，供 <code>HashMap</code>、<code>HashSet</code> 等散列集合快速定位</li></ul></li><li>equals() <ul><li>Object 定义的方法，判断两个对象是否相等</li></ul></li></ul><p>实际编程情况下，我个人使用 <code>Objects.equals(a, b)</code> 的频率挺高的，而不是直接使用 <code>equals</code>。</p><p>可以看下面这个解释</p><p><code>Objects.equals(a, b)</code> 的本质是 null 安全的 <code>equals</code> , 它解决的是“<strong>两个值怎么比</strong>”</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>public static boolean equals(Object a, Object b) {</span></span>
<span class="line"><span>    return (a == b) || (a != null &amp;&amp; a.equals(b));</span></span>
<span class="line"><span>}</span></span></code></pre></div>`,44)),a("p",null,[l[1]||(l[1]=i("同时如果是对象中的字段使用了 HashSet 或者 HashMap，",-1)),s(e,{color:"#4bacc6"},{default:o(()=>[...l[0]||(l[0]=[i("重写了 equals 方法，hashCode 方法也必须重写",-1)])]),_:1}),l[2]||(l[2]=i("。要不然他会直接比较对象去了，一般我们需要比较对象的字段是否相等。",-1))]),l[25]||(l[25]=n(`<p>put 或者 add 里面的方法会使用到 Map 里面的 Put 方法，put 方法中，使用了先哈希判断，再 == 引用判断，再 equals 判断的逻辑。</p><p>有一个逻辑基本上是：<code>hashCode</code> 不同 → <code>equals</code> 一定不等</p><p>可以使用 hashCode 快速分桶，然后再使用 equals 比较（equals 方法比较中，哈希方法比较的是哈希值，而哈希值是一个固化的整数，不同环境可能不一样，不过部分<strong>有规范保证的类，跨环境固定</strong>，<code>String</code>、<code>Integer</code>、<code>Long</code> 等包装类的 <code>hashCode()</code> 在 Java 规范里写死了算法。</p><h4 id="双等号与-equals-的区别" tabindex="-1">双等号与 equals 的区别 <a class="header-anchor" href="#双等号与-equals-的区别" aria-label="Permalink to &quot;双等号与 equals 的区别&quot;">​</a></h4><ul><li>== ： 基本类型比值；引用类型比<strong>引用地址</strong></li><li>equals：默认比引用地址，重写后比<strong>逻辑内容</strong>。 （Objects 定义的方法）</li></ul><h4 id="双层循环中的作用-continue、break、return-的区别" tabindex="-1">双层循环中的作用 continue、break、return 的区别 <a class="header-anchor" href="#双层循环中的作用-continue、break、return-的区别" aria-label="Permalink to &quot;双层循环中的作用 continue、break、return 的区别&quot;">​</a></h4><ul><li><strong><code>continue</code></strong>：只会影响当前所在的内层循环，继续内层循环的下一次迭代</li><li><strong><code>break</code></strong>：只会影响当前所在的内层循环，跳出内层循环。</li><li><strong><code>return</code></strong>：终止整个方法的执行，直接返回到方法调用点。</li></ul><p>示例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>for (int i = 0; i &lt; 5; i++) {</span></span>
<span class="line"><span>    for (int j = 0; j &lt; 5; j++) {</span></span>
<span class="line"><span>        if (j == 2) {</span></span>
<span class="line"><span>            continue; // 结束当前内层循环的当前迭代，继续下一次迭代</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>        System.out.println(&quot;i = &quot; + i + &quot;, j = &quot; + j);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span></span></span>
<span class="line"><span>for (int i = 0; i &lt; 5; i++) {</span></span>
<span class="line"><span>    for (int j = 0; j &lt; 5; j++) {</span></span>
<span class="line"><span>        if (j == 2) {</span></span>
<span class="line"><span>            break; // 终止内层循环</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>        System.out.println(&quot;i = &quot; + i + &quot;, j = &quot; + j);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>public void exampleMethod() {</span></span>
<span class="line"><span>    for (int i = 0; i &lt; 5; i++) {</span></span>
<span class="line"><span>        for (int j = 0; j &lt; 5; j++) {</span></span>
<span class="line"><span>            if (j == 2) {</span></span>
<span class="line"><span>                return; // 终止方法执行，返回到调用点</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span>            System.out.println(&quot;i = &quot; + i + &quot;, j = &quot; + j);</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    System.out.println(&quot;This will not be printed if j == 2&quot;);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>public static void main(String[] args) {</span></span>
<span class="line"><span>    new MyClass().exampleMethod();</span></span>
<span class="line"><span>    System.out.println(&quot;Method has returned&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><h4 id="string-为什么是不可变的" tabindex="-1">String 为什么是不可变的 <a class="header-anchor" href="#string-为什么是不可变的" aria-label="Permalink to &quot;String 为什么是不可变的&quot;">​</a></h4><ul><li><code>String</code> 类内部使用 <code>private final char[]</code> 或 <code>private final byte[]</code> 来存储字符串数据。</li><li>好处 <ul><li>防止被恶意更改</li><li>作为HashMap的key可以保证不可变性</li><li>可以实现字符串常量池，在Java中，创建字符串对象的⽅式 <ul><li>通过字符串常量进⾏创建 <ul><li>在字符串常量池判断是否存在，如果存在就返回，不存 在就在字符串常量池创建后返回</li></ul></li><li>通过new字符串对象进⾏创建 <ul><li>在字符串常量池中判断是否存在，如果不存在就创建， 再判断堆中是否存在，如果不存在就创建，然后返回该 对象，总之要保证字符串常量池和堆中都有该对象</li></ul></li></ul></li></ul></li></ul><blockquote><p>是不是 String 使用 final 修饰 ，它才是不可变的；被 final 修饰的常量，是不可变的吗</p></blockquote><p>当一个变量被 <code>final</code> 修饰时，它是不可变的，即它的引用不能被改变，但如果这个变量是一个对象的引用，那么对象本身还是可以被改变的（除非这个对象本身也是不可变的）</p><p><code>final</code> 关键字用于修饰变量、方法和类，其作用如下：</p><ol><li><strong>修饰变量</strong>：表示该变量只能被赋值一次，赋值后不能被重新赋值。</li><li><strong>修饰方法</strong>：表示该方法不能被子类重写。</li><li><strong>修饰类</strong>：表示该类不能被继承。</li></ol><p><code>String</code> 类本身是不可变的，这是因为：</p><ol><li><code>String</code> 类是由 <code>final</code> 修饰的类，因此不能被继承。</li><li><code>String</code> 类中的字符数组 <code>value</code> 是私有的，并且没有提供任何修改字符数组的方法。</li><li><code>String</code> 类的方法不会修改字符串对象本身，而是返回一个新的字符串对象。</li></ol><h4 id="string、stringbuffer、stringbuilder-的区别" tabindex="-1">String、StringBuffer、StringBuilder 的区别 <a class="header-anchor" href="#string、stringbuffer、stringbuilder-的区别" aria-label="Permalink to &quot;String、StringBuffer、StringBuilder 的区别&quot;">​</a></h4><table tabindex="0"><thead><tr><th>维度</th><th>String</th><th>StringBuffer</th><th>StringBuilder</th></tr></thead><tbody><tr><td><strong>可变性</strong></td><td>不可变（<code>final char[]</code>/<code>byte[]</code>）</td><td>可变</td><td>可变</td></tr><tr><td><strong>线程安全</strong></td><td>天然安全（不可变）</td><td>安全（方法加 <code>synchronized</code>）</td><td>非线程安全</td></tr><tr><td><strong>性能</strong></td><td>频繁拼接最差（每次新建对象）</td><td>中等（有锁开销）</td><td>最好</td></tr><tr><td><strong>适用场景</strong></td><td>少量、不频繁修改的字符串</td><td>多线程下频繁拼接</td><td>单线程下频繁拼接</td></tr></tbody></table><blockquote><p><strong>String 不可变，每次拼接都产生新对象；StringBuffer 可变且线程安全，但方法加锁有开销；StringBuilder 可变但非线程安全，单线程性能最好。</strong></p></blockquote><p><strong>补充考点</strong>：</p><ul><li><code>String s = &quot;a&quot; + &quot;b&quot;</code> 编译期会优化成 <code>&quot;ab&quot;</code>，不产生中间对象；但循环里 <code>s += i</code> 会反复 <code>new StringBuilder</code>，要用 <code>StringBuilder</code> 替代；</li><li>JDK 9 之后 String 底层从 <code>char[]</code> 改成 <code>byte[] + coder</code>，拉丁字符省一半空间；</li><li><code>StringBuilder</code> 默认容量 16，可预设容量避免扩容。</li></ul><p>关于 StringBuffer 和 StringBuilder 的扩容操作</p><p>两者的扩容逻辑<strong>完全一致</strong>，核心实现在共同的父类 <strong><code>AbstractStringBuilder</code></strong> 中。<code>StringBuffer</code> 只是在方法上加了 <code>synchronized</code>，扩容的算法本身没有区别</p><p>扩容操作：<strong>计算候选新容量</strong>：<code>旧容量 × 2 + 2</code>，从 16 开始，容量按 16 → 34 → 70 → 142 → 286 ... 增长</p><hr><h4 id="泛型通配符-extends-与-super-的区别" tabindex="-1">泛型通配符 extends 与 super 的区别 <a class="header-anchor" href="#泛型通配符-extends-与-super-的区别" aria-label="Permalink to &quot;泛型通配符 extends 与 super 的区别&quot;">​</a></h4><ul><li>extends：任意 T 或 T 的子类型</li><li>super：任意 T 或 T 的父类型</li></ul><h4 id="讲述一下-java-中的异常体系。" tabindex="-1">讲述一下 Java 中的异常体系。 <a class="header-anchor" href="#讲述一下-java-中的异常体系。" aria-label="Permalink to &quot;讲述一下 Java 中的异常体系。&quot;">​</a></h4><p>实际项目中，使用最多的异常还是 SpringBoot 里面的 GlobalException，然后我们会使用同一个的异常枚举，同时我们定义业务异常和系统异常。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202401181322703.png" alt="image.png"></p><p><strong>Unchecked Exception</strong> 即 <strong>不受检查异常</strong> ，Java 代码在编译过程中 ，我们即使不处理不受检查异常也可以正常通过编译。</p><p><strong>Checked Exception</strong> 即 受检查异常 ，Java 代码在编译过程中，如果受检查异常没有被 <code>catch</code>或者<code>throws</code> 关键字处理的话，就没办法通过编译。</p><p>不受检查异常</p><ul><li><code>NullPointerException</code>(空指针错误)</li><li><code>IllegalArgumentException</code>(参数错误比如方法入参类型错误)</li><li><code>NumberFormatException</code>（字符串转换为数字格式错误，<code>IllegalArgumentException</code>的子类）</li><li><code>ArrayIndexOutOfBoundsException</code>（数组越界错误）</li><li><code>ClassCastException</code>（类型转换错误）</li><li><code>ArithmeticException</code>（算术错误）</li><li><code>SecurityException</code> （安全错误比如权限不够）</li><li><code>UnsupportedOperationException</code>(不支持的操作错误比如重复创建同一用户)</li><li>……</li></ul><p>当我们在尝试使用 null 引用的时候，会发生 NPE</p><ul><li>避免空指针异常 <ul><li><ol><li>在使用之前先检查一下是否为 null</li></ol></li><li><ol start="2"><li>调用方法的时候进行参数检查</li></ol></li><li><ol start="3"><li>在设计方法或者API 的时候，尽量不要返回 null 值，而且返回一个空集合或者默认值；</li></ol></li><li><ol start="4"><li>初始化使用字段，保证不为 null</li></ol></li><li><ol start="5"><li>使用 Optional</li></ol></li><li><ol start="6"><li>使用断言（开发和测试环境）</li></ol></li></ul></li></ul><p>方法上</p><ul><li>throws 方法声明上进行抛出异常</li><li>throw 方法体中进行抛出异常</li></ul><h3 id="jvm" tabindex="-1">JVM <a class="header-anchor" href="#jvm" aria-label="Permalink to &quot;JVM&quot;">​</a></h3><h4 id="类的生命周期-七个阶段" tabindex="-1">类的生命周期：七个阶段 <a class="header-anchor" href="#类的生命周期-七个阶段" aria-label="Permalink to &quot;类的生命周期：七个阶段&quot;">​</a></h4><p>类的生命周期是「加载 → 连接 → 初始化 → 使用 → 卸载」五步，其中连接细分为验证、准备、解析</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20261108173958189.png" alt="image.png"></p><p>理解这个还是需要先理解一下 JDK 和 JVM 的关系，这里JVM，编译这一步是JDK里面做的，JVM会将编译后的 .class 文件，进行加载后的操作。</p><p>生命周期其实就是从生到死、从有到无的过程，加载之后会进行连接，验证是连接的第一步，检查的是 class 文件书写得对不对：类的定义是否正确、方法、变量的格式有没有问题。这一层是格式与合法性守卫，跟业务语义无关。验证没问题后就准备，准备之后解析 。</p><h4 id="讲一下-jvm-类加载器与双亲委派机制" tabindex="-1">讲一下：JVM 类加载器与双亲委派机制 <a class="header-anchor" href="#讲一下-jvm-类加载器与双亲委派机制" aria-label="Permalink to &quot;讲一下：JVM 类加载器与双亲委派机制&quot;">​</a></h4>`,46)),a("p",null,[l[4]||(l[4]=i("类加载器负责把 .class 加载进内存；JDK8 有三个——启动、扩展、应用，靠",-1)),l[5]||(l[5]=a("strong",null,"单一职责",-1)),l[6]||(l[6]=i("分工。加载时遵循",-1)),l[7]||(l[7]=a("strong",null,"双亲委派",-1)),l[8]||(l[8]=i("：",-1)),s(e,{color:"#4bacc6"},{default:o(()=>[...l[3]||(l[3]=[i("子加载器先委派父加载器，一路委派到顶层，父加载不到才轮到自己",-1)])]),_:1}),l[9]||(l[9]=i("。它的两个作用是保证",-1)),l[10]||(l[10]=a("strong",null,"唯一性",-1)),l[11]||(l[11]=i("与",-1)),l[12]||(l[12]=a("strong",null,"安全性",-1)),l[13]||(l[13]=i("，但可以被打破，Tomcat 就是例子",-1))]),l[26]||(l[26]=n('<table tabindex="0"><thead><tr><th>加载器（JDK8）</th><th>负责加载</th><th>备注</th></tr></thead><tbody><tr><td>启动 Bootstrap</td><td>JRE/lib 下核心类库，如 rt.jar</td><td>委派链顶端</td></tr><tr><td>扩展 Extension</td><td>JRE/lib/ext 下的 jar 包</td><td>JDK9 改名为平台类加载器</td></tr><tr><td>应用 Application</td><td>classpath 下自己的类与引用的 jar</td><td>最常打交道的一层</td></tr><tr><td>自定义</td><td>用户自行实现，加载过程自定义</td><td>委派行为由自己决定</td></tr></tbody></table><p>首先加载自定义类加载器，然后说应用，再是扩展，最后是启用引导类加载器。</p><p>JDK 8 和 JDK 9 之后有区分，JDK9 之后，JDK9 把扩展类加载器改成了平台类加载器（原因是 JDK9 引入了模块化，把 Java 中的包一个一个划分到具体模块下，而模块里指定了由哪个类加载器加载）；</p><p>双亲委派机制能不能打破？</p><p>能，场景是这样的：Tomcat 是 web 服务器，对 Java 来说它本身也是一个应用程序，但它内部可以同时承载多个 web 应用，比如 web1 和 web2。如果两个应用里定义了同一个全限定名的类（比如 com.xxx.User），按双亲委派这个类只会被加载一次，另一个应用就加载不到，直接 ClassNotFoundException。</p><p>所以 Tomcat 为了保证每个应用都有自己独立的类，必须打破双亲委派，让不同 web 应用各用自己的类。这条也解释了为什么「唯一性」不是绝对的好事——它需要作用域。</p><p>具体是如何打破的（实现手段）？</p><ul><li><code>loadClass()</code> 主要负责类加载流程，双亲委派就体现在它的默认实现里。重写它可以改变“先父后子”的委派顺序，比如 Tomcat 的 <code>WebappClassLoader</code> 会优先尝试当前 web 应用自己的类，再委派父加载器，从而实现应用隔离。<strong>打破双亲委派主要靠重写 <code>loadClass</code>。</strong></li><li><code>findClass()</code> 主要负责“去哪里找目标类的字节码”，比如从某个目录、Jar 包、网络等加载。重写它通常只是自定义类来源，<strong>单靠重写 <code>findClass</code> 一般不算打破双亲委派</strong>，因为委派流程还在 <code>loadClass</code> 里；它常和 <code>loadClass</code> 配合使用。</li></ul><hr><h4 id="jvm-运行区区域" tabindex="-1">JVM 运行区区域 <a class="header-anchor" href="#jvm-运行区区域" aria-label="Permalink to &quot;JVM 运行区区域&quot;">​</a></h4><ul><li>堆</li><li>虚拟机栈</li><li>本地方法栈</li><li>程序计数器</li><li>方法区 <ul><li>JDK8 本地内存 → 元空间 → 方法区</li><li>JDK8 之前 → 堆中（永久代） → 方法区</li></ul></li></ul><h4 id="在1-8-中-运行时常量池是放置在哪个区域-🚩" tabindex="-1">在1.8 中，运行时常量池是放置在哪个区域？ 🚩 <a class="header-anchor" href="#在1-8-中-运行时常量池是放置在哪个区域-🚩" aria-label="Permalink to &quot;在1.8 中，运行时常量池是放置在哪个区域？  🚩&quot;">​</a></h4><p>在Java 8中，<strong>字符串常量池</strong>已经被移动到了<strong>堆内存</strong>中，以提高性能和减少内存溢出的风险。</p><p>而<strong>运行时常量池</strong>除了字符串常量外的部分，仍然存储在方法区中，但方法区的实现已从永久代变更为<strong>元空间</strong>。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240315210151.png" alt="image.png"></p><h4 id="栈上分配-💣" tabindex="-1">栈上分配 💣 <a class="header-anchor" href="#栈上分配-💣" aria-label="Permalink to &quot;栈上分配   💣&quot;">​</a></h4><p>栈上分配是一种优化技术，用于减少堆内存分配和垃圾回收的压力。通常情况下，通过 <code>new</code> 关键字创建的对象都是分配在堆上的，但在某些情况下，JVM 可以通过逃逸分析（Escape Analysis）将一些临时对象分配到栈上。这意味着这些对象会随着栈帧的出栈而被销毁，从而减少对垃圾回收器（GC）的压力。</p><blockquote><p>逃逸分析</p></blockquote><p>逃逸分析是一种静态代码分析技术，用于确定对象的引用范围，即对象是否会逃逸出方法或线程。根据逃逸分析的结果，JVM 可以对对象进行不同的优化处理。</p><ul><li><strong>方法逃逸</strong>：如果对象被返回或传递到方法外部，则认为它逃逸出了方法。</li><li><strong>线程逃逸</strong>：如果对象被共享到其他线程中，则认为它逃逸出了当前线程。</li></ul><p>如果对象没有逃逸出方法或线程，JVM 可以进行进一步优化，比如栈上分配或标量替换。</p><blockquote><p>标量替换</p></blockquote><p>标量替换是逃逸分析优化的一部分。它将对象的成员变量拆分为单独的标量（例如，基本类型或引用），而不是将整个对象分配到堆上。通过这种方式，可以避免不必要的对象创建。</p><blockquote><p>栈上分配的原理</p></blockquote><ul><li><strong>对象分配到栈上</strong>：如果通过逃逸分析确定对象没有逃逸出方法，则可以将该对象分配到栈上。栈上分配的对象在栈帧出栈时自动销毁，不需要GC。</li><li><strong>减少GC压力</strong>：栈上分配避免了临时对象在堆上的分配和回收，从而减轻了GC的压力，提高了性能。</li></ul><h4 id="判断垃圾回收" tabindex="-1">判断垃圾回收 <a class="header-anchor" href="#判断垃圾回收" aria-label="Permalink to &quot;判断垃圾回收&quot;">​</a></h4><ul><li>引用计数法</li><li>可达性分析算法</li></ul><h4 id="垃圾回收算法" tabindex="-1">垃圾回收算法 <a class="header-anchor" href="#垃圾回收算法" aria-label="Permalink to &quot;垃圾回收算法&quot;">​</a></h4><ul><li>标记整理</li><li>标记清除</li><li>复制</li></ul><h4 id="对象的分配策略" tabindex="-1">对象的分配策略 <a class="header-anchor" href="#对象的分配策略" aria-label="Permalink to &quot;对象的分配策略&quot;">​</a></h4><p>在 Java 虚拟机（JVM）中，对象的分配和回收策略有助于提升内存管理效率和系统性能。以下是 JVM 对象分配的具体策略：</p><ol><li>对象优先在 Eden 区进行分配</li></ol><ul><li><strong>新对象分配</strong>：新创建的对象会被分配到 Eden 区。当 Eden 区内存不足时，会触发 Minor GC。</li><li><strong>Minor GC 后对象移动</strong>：每次 Minor GC 后，存活的对象会被移动到 Survivor 区的一个区域。在下一次 Minor GC 时，Eden 区和 Survivor 区存活的对象会被移动到 Survivor 区的另一个区域，同时对象的分代年龄会增加 1。</li><li><strong>对象晋升</strong>：当对象分代年龄达到一定次数后（默认 15 次，CMS 为 6 次），对象会被晋升到老年代。如果老年代使用空间达到阈值，会进行 Full GC。如果 Full GC 无法回收足够的内存，则会导致内存溢出（OOM）。</li></ul><ol start="2"><li>大对象直接进入老年代</li></ol><ul><li><strong>大对象处理</strong>：由于复制算法对大对象的来回复制会带来性能开销，JVM 可以设置一个阈值，当新创建的对象大小超过这个阈值时，会直接分配到老年代。</li></ul><ol start="3"><li>长期存活的对象进入老年代</li></ol><ul><li><strong>分代年龄机制</strong>：对象在年轻代存活一定次数（分代年龄）后，会被晋升到老年代。</li><li><strong>动态年龄判断机制</strong>： <ul><li><strong>机制</strong>：经过 Minor GC 后，如果 Survivor 区中存活的前 N 代对象的内存总和超过 Survivor 区内存的一半，会将 N 代及以上的对象直接移动到老年代。</li><li><strong>目的</strong>：尽可能将长期存活的对象直接进入老年代，避免频繁的 GC。</li></ul></li></ul><ol start="4"><li>老年代空间分配担保机制</li></ol><ul><li><strong>Minor GC 前的计算</strong>：在每次 Minor GC 之前，JVM 会计算老年代剩余可用空间。 <ul><li><strong>触发 Full GC 条件</strong>： <ol><li>如果老年代剩余可用空间小于年轻代所有对象的内存，会触发 Minor GC。</li><li>如果老年代剩余可用空间不小于年轻代所有对象的内存，会检查是否配置了担保参数。</li><li>如果配置了担保参数，并且老年代剩余可用空间小于历史上每次 Minor GC 进入老年代对象的内存大小，会触发 Full GC。</li><li>如果老年代剩余可用空间不小于历史上每次 Minor GC 进入老年代对象的内存大小，则触发 Minor GC。</li><li>如果没有担保参数，直接触发 Full GC。</li></ol></li></ul></li></ul><h4 id="垃圾收集器-🚩" tabindex="-1">垃圾收集器 🚩 <a class="header-anchor" href="#垃圾收集器-🚩" aria-label="Permalink to &quot;垃圾收集器  🚩&quot;">​</a></h4><ul><li>Serial 、Serial Old <ul><li>Serial 和 Serial Old 是 单线程垃圾收集器，在GC时，只允许⼀个 线程进⾏</li><li>Serial ⽤在年轻代采⽤的是 复制算法、Serial Old ⽤在⽼年代采⽤ 的是 标记整理算法</li><li>在单核处理器的情况下，简单⾼效，但是多核处理器下⽆法发挥 多核的性能不推荐使⽤，适合 100M以内 内存</li></ul></li><li>Parallel、Parallel Old <ul><li>Parallel 和 Parallel Old 是 多线程垃圾收集器，是serial系列的多线 程版本</li><li>Parallel ⽤在年轻代采⽤的是 <strong>复制算法</strong>，Parallel Old采⽤的是 <strong>标 记整理算法</strong></li><li>关注点在于吞吐量，⽐较适合CPU密集型场景，⼀般 4G以下 内存 推荐使⽤</li></ul></li><li>ParNew 、CMS <ul><li>ParNew 与 Parallel类似，只是为了配合 CMS 才出现的</li><li>ParNew ⽤在年轻代采⽤的是 复制算法， CMS ⽤在⽼年代采⽤的 是 <strong>标记清除算法</strong></li><li>CMS关注点是最⼤停顿时间，也就是**⽤户的体验度，⽐较适合 4~8G 内存的情况使⽤**</li></ul></li><li>G1 <ul><li>分区模型</li></ul></li></ul><p>CMS</p><ul><li><p>初始标记 → 并发标记 → 重新标记 → 并发清理 → 并发重置</p></li><li><p>并发标记会产生多标、漏标问题，漏标主要的解决方案是三色标记</p></li><li><p>CMS的运作步骤</p><ul><li>初始标记 <ul><li>STW，从GC Root出发，<strong>只标记直接引⽤对象</strong>(不包含内部 成员变量相关的间接引⽤对象)</li></ul></li><li>并发标记 <ul><li>从GC Root的直接引⽤对象出发，遍历整个对象图进⾏标 记，耗时较⻓，由于⽤户线程和GC线程都在运⾏着，所以 会有多标、漏标的问题</li><li>多标 <ul><li>多标 就是本应该是垃圾对象，但是由于⽤户线程还 在运⾏，所以没来及去清除标记</li></ul></li><li>漏标 <ul><li>漏标 就是 新来的对象引⽤了GC Root链上的对象， 但是由于⽤户线程还在运⾏，没来得及标记为⾮垃 圾，被GC误清除</li><li>漏标 的处理⽅案主要是 三⾊标记算法，主要分为 增量更新 和 原始快照 <ul><li>三⾊标记主要是分为三种颜⾊，分别是⿊⾊、⽩ ⾊、灰⾊ <ul><li>⿊⾊对象 表示 当前对象的引⽤对象图都扫描 完了</li><li>灰⾊对象 表示 当前对象的引⽤对象图只扫描 了⼀部分</li><li>⽩⾊对象 表示 当前对象的引⽤对象图没扫描</li></ul></li><li>增量更新 是通过 记录下⿊⾊对象新增的⽩⾊对 象引⽤关系，将⿊⾊对象回退到灰⾊对象，重新 深度扫描⼀次</li><li>原始快照 是通过 记录下灰⾊对象删除的⽩⾊对 象的引⽤关系，以灰⾊对象为根简单扫描⼀下， 将⽩⾊对象标记为⿊⾊对象，当作浮动垃圾处 理，等待下⼀轮GC <ul><li>浮动垃圾 <ul><li>浮动垃圾 就是在 并发标记 和 并发清理 阶 段产⽣的垃圾，对GC最终效果影响不 ⼤，只要等待下⼀轮GC处理就⾏</li></ul></li></ul></li></ul></li></ul></li></ul></li><li>重新标记 <ul><li>STW，对 并发标记 过程中产⽣状态改变的对象进⾏修正， 这⾥对于 漏标 的问题采⽤的是 三⾊标记算法 中的 增量更 新 来做的重新标记</li></ul></li><li>并发清理 <ul><li>对未标记的对象进⾏清理，这⾥因为没有进⾏STW，所以 对于新增对象会被标记为⿊⾊对象</li></ul></li><li>并发重置 <ul><li>将对象的标记位进⾏重置，进⾏下⼀轮GC</li></ul></li></ul></li></ul><h4 id="触发-full-gc-的一些情况-🚩" tabindex="-1">触发 Full GC 的一些情况 🚩 <a class="header-anchor" href="#触发-full-gc-的一些情况-🚩" aria-label="Permalink to &quot;触发 Full GC 的一些情况  🚩&quot;">​</a></h4><h4 id="哪些对象可以作为-gc-root" tabindex="-1">哪些对象可以作为 GC Root ？ <a class="header-anchor" href="#哪些对象可以作为-gc-root" aria-label="Permalink to &quot;哪些对象可以作为 GC Root ？&quot;">​</a></h4><ul><li>虚拟机栈中（栈帧中的本地变量表）中引用的对象</li><li>方法区中类静态属性引用的对象</li><li>方法区中常量引用的对象</li><li>本地方法栈中 JNI 引用的对象</li></ul><h3 id="集合" tabindex="-1">集合 <a class="header-anchor" href="#集合" aria-label="Permalink to &quot;集合&quot;">​</a></h3><ul><li>常见的一些问题 <ul><li>主要还是围绕 HashMap 去问的，相关的 put 流程和扩容机制需要掌握</li></ul></li><li>概念前提 <ul><li>ArrayList的数组默认⻓度10，1.5倍数组扩容，扩容通过开辟新数 组进⾏转移⽼数组元素</li><li>HashMap、ConcurrentHashMap的数组默认⻓度16，2倍数组扩 容，扩容通过开辟新数组进⾏转移⽼数组元素</li></ul></li><li>核⼼思想 <ul><li>读写分离 <ul><li>CopyOnWriteArrayList底层实现、处理快速失败</li></ul></li><li>分散热点 <ul><li>ConcurrentHashMap底层addCount计算</li></ul></li><li>索引优化 <ul><li>HashMap/ConcurrentHashMap 从数组-&gt;链表-&gt;红⿊树</li></ul></li></ul></li><li>考察重点 <ul><li>集合底层实现以及设计思想</li></ul></li><li>注意点 <ul><li>对于存放⼤量元素到ArrayList 或 HashMap中时，建议提前初始化 好容量避免扩容导致性能损耗</li></ul></li></ul><h4 id="成员关系" tabindex="-1">成员关系 <a class="header-anchor" href="#成员关系" aria-label="Permalink to &quot;成员关系&quot;">​</a></h4><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202311141122413.png" alt="image.png"></p><h4 id="hashmap-的-put-流程讲一下" tabindex="-1">HashMap 的 put 流程讲一下 <a class="header-anchor" href="#hashmap-的-put-流程讲一下" aria-label="Permalink to &quot;HashMap 的 put 流程讲一下&quot;">​</a></h4><ul><li>1、计算数组下标：首先基于键（Key）的 hash 值计算得到数组下标。</li><li>2、如果数组下标为空 <ul><li>如果下标位置为空： <ul><li>在 JDK 7 中，会将键值对（K-V）封装成 Entry 对象。</li><li>在 JDK 8 中，会将键值对封装成 Node 对象。</li></ul></li><li>然后将该对象放到数组对应的槽位中。</li></ul></li><li>3、如果数组下标不为空 <ul><li>如果下标位置不为空： <ul><li><strong>JDK 7</strong>: <ul><li>先判断是否需要扩容，如果需要扩容就先进行扩容。</li><li>然后采用头插法将新的节点插入当前槽位的链表上。</li><li>如果键相同，就更新对应的值（Value）。</li></ul></li><li><strong>JDK 8</strong>: <ul><li>不会先判断是否需要扩容，而是先判断节点类型（链表节点或红黑树节点）。</li><li>如果是链表节点： <ul><li>将键值对封装成链表节点，采用尾插法插入当前槽位的链表上。</li><li>如果键相同，就更新对应的值（Value）。</li><li>当数组长度达到 64 且链表长度达到 8 时，会将链表转化为红黑树以提升查询速度。</li></ul></li><li>如果是红黑树节点： <ul><li>将键值对封装成红黑树节点，放到红黑树上。</li><li>如果键相同，就更新对应的值（Value）。</li><li>当红黑树节点数减少到 6 时，会退化成链表</li></ul></li></ul></li></ul></li></ul></li></ul><h4 id="hashmap-的-get-流程" tabindex="-1">HashMap 的 get 流程 <a class="header-anchor" href="#hashmap-的-get-流程" aria-label="Permalink to &quot;HashMap 的 get 流程&quot;">​</a></h4><ol><li><strong>计算数组下标</strong><ul><li>基于键（Key）的 hash 值计算得到数组的下标。</li></ul></li><li><strong>查找元素</strong><ul><li>遍历下标位置的每个槽位（链表/红黑树）。</li><li>通过 <code>equals</code> 方法查找与键相同的元素。</li></ul></li></ol><h4 id="hashmap-的扩容流程-🚩" tabindex="-1">HashMap 的扩容流程 🚩 <a class="header-anchor" href="#hashmap-的扩容流程-🚩" aria-label="Permalink to &quot;HashMap 的扩容流程  🚩&quot;">​</a></h4><p>参考： <a href="https://www.bilibili.com/video/BV14r4y1R7e6" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV14r4y1R7e6</a></p><p>扩容操作：</p><ul><li>1、每次扩容是两倍</li><li>2、当元素个数 &gt; 槽位数组长度 * 负载因子，进行扩容操作</li><li>3、JDK 7 是数组 + 链表，JDK 8 是 数组 + 链表 + 红黑树，JDK7 链表是头插法，JDK8 是尾插法</li><li>4、resize 的时候会重新哈希计算，红黑树的话会进行拆分操作，当当数组长度达到 64 且链表长度达到 8 时，会将链表转化为红黑树，当红黑树元素个数减少到 6 时，会退化成链表</li><li>JDK 7 头插法存在并发情况下循环链表问题，JDK8 通过尾插进行解决。</li></ul><hr><p>HashMap 的扩容实质上是数组的扩容，会重新开辟一份容量为原数组两倍的新数组，并将老数组的元素转移过来。</p><ul><li>扩容条件 <ul><li>当插入新元素后，HashMap 中元素的数量超过当前数组容量的负载因子（默认是 0.75）时，HashMap 会触发扩容</li></ul></li><li>扩容过程 <ul><li>JDK7 <ul><li>新数组容量为原数组容量的两倍。</li><li>将老数组中的元素重新计算哈希值，得到新数组的下标。</li><li>将元素放到新数组对应槽位的链表上。</li><li>扩容的主要目的是解决链表过长的问题</li></ul></li><li>JDK8 <ul><li>新数组容量为原数组容量的两倍。</li><li>重新计算老数组中元素的数组下标。</li><li><strong>红黑树槽位</strong>: <ul><li>通过低位和高位（老位置的元素和新位置的元素）拆分成两个子链表，存放到不同的槽位。</li><li>当数组长度达到 64 且链表长度达到 8 时，会将链表转化为红黑树。</li></ul></li><li><strong>链表槽位</strong>: <ul><li>操作与 JDK 7 相同，将元素放到新数组对应槽位的链表上</li></ul></li></ul></li></ul></li></ul><p>低位和高位的概念</p><p>在扩容过程中，重新计算数组下标时，会出现两种情况：</p><ol><li><strong>低位</strong>：元素在新数组中的位置与在旧数组中的位置相同。</li><li><strong>高位</strong>：元素在新数组中的位置是旧数组位置加上旧数组的容量。</li></ol><p>这两种情况取决于元素的哈希值与旧数组容量进行按位与操作的结果：</p><ul><li>低位：<code>index = oldIndex</code></li><li>高位：<code>index = oldIndex + oldCapacity</code></li></ul><h4 id="concurrenthashmap" tabindex="-1">ConcurrentHashMap <a class="header-anchor" href="#concurrenthashmap" aria-label="Permalink to &quot;ConcurrentHashMap&quot;">​</a></h4><p>ConcurrentHashMap 是一种线程安全的高效Map集合</p><ul><li>ConcurrentHashMap <ul><li>底层数据结构 <ul><li>1.7：底层采用分段 Segment，每一个 Segment 是由 数组 + 链表实现</li><li>1.8：采用的数据结构跟 HashMap 1.8 的结构一样，Node 数组 + 链表/红黑二叉树</li></ul></li><li>加锁的方式 <ul><li>1.7：采用 Segment 分段锁，底层使用的是 ReentrantLock</li><li>1.8：采用 CAS 添加新节点，采用 synchronized 锁定链表或红黑二叉树的首节点，相对 Segment 分段锁粒度更细，性能更好</li></ul></li><li>新增元素（1.8） <ul><li>hash(key) → 在该数组节点下通过 CAS 操作新增元素操作</li><li>采用 synchronized 锁定链表或红黑二叉树的首节点</li></ul></li></ul></li></ul><p>加锁程度</p><ul><li>1.7 通过对Segment加锁实现，每个 Segment 有自己的锁</li><li>1.8 对于链表的修改操作，通过synchronized关键字对 Node 进行加锁；对于新增操作，如果需要更新链表的头部，使用CAS操作来确保原子性。当链表长度达到一定阈值后，链表会转换为红黑树，提高搜索效率</li></ul><p>1.7 中使用了分段锁的机制，通过对于 HashEntry 数组进行加锁，每一个 Segment 元素都是使用的 ReentrantLock ，用于在高并发环境下对于集合的线程安全保护。</p><p>同时为了 hash 冲突的解决，这里是通过拉链法的方式进行解决的。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240407222040.png" alt="image.png"></p><p>锁粒度更细</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240407222700.png" alt="image.png"></p><h4 id="deque-queue" tabindex="-1">Deque/Queue <a class="header-anchor" href="#deque-queue" aria-label="Permalink to &quot;Deque/Queue&quot;">​</a></h4><ul><li>Queue是单端队列，只能从一端插入元素，另一端删除元素，实现上一般遵循先进先出(FIFO)规则。</li><li>Deque是双端队列，在队列的两端均可以插入或删除元素。</li></ul><h4 id="sortedset-treeset" tabindex="-1">SortedSet/TreeSet <a class="header-anchor" href="#sortedset-treeset" aria-label="Permalink to &quot;SortedSet/TreeSet&quot;">​</a></h4><ul><li>TreeSet 是 SortedSet 的实现类</li><li>一般是两种排序方式：一种是自然排序（实现 Comparable 接口，重写 compareTo 方法）：还有一种是自定义比较器（Comparator）</li></ul><p>TreeSet ：<code>TreeSet</code> 是通过 <code>TreeMap</code> 来实现的（内部结构）</p><h4 id="threadlocal" tabindex="-1">ThreadLocal <a class="header-anchor" href="#threadlocal" aria-label="Permalink to &quot;ThreadLocal&quot;">​</a></h4><ul><li>ThreadLocal主要是保存线程变量副本的，⼀般可以⽤来缓存⽤户信 息、连接等，通过保证每个线程变量隔离来实现线程安全 <ul><li>ThreadLocal 会对线程维护⼀个以 ThreadLocal 作为 Key 的 Map(ThreadLocalMap，Value对应的是当前线程变量的副本，Key 是弱引⽤所以GC时会回收，但是Value是强引⽤，所以如果不⼿动 清除，Value会⼀直霸占⽼年代空间导致内存泄露(ML)</li></ul></li><li>对于ThreadLocal只能保证线程内部的通信，如果想要进⾏⽗⼦线程 通信，可以使⽤InheritableThreadLocal，它实现原理是⽗线程在创建 ⼦线程时会将当前的变量副本拷⻉⼀份给⼦线程，但是 InheritableThreadLocal遇到线程池就不能完成⽗⼦通信了，因为线程 池⼀旦创建完线程就会进⾏复⽤，所以可以使⽤ TransmittableThreadLocal，它实现原理就是在线程池中不管线程是 否是新建都会在调⽤时抓取⽗线程的上下⽂给⼦线程</li><li>另外 ThreadLocal 内部 ThreadLocalMap 使⽤线性探测法实现的哈希 表，所以⾯临⼤量线程绑定数据时性能较低，所以 Netty 引出了 FastThreadLocal，底层直接通过更⼤数组空间的开辟，通过数组索引 进⾏定位，避免线性探测，采⽤⽤空间换时间，并且 FastThreadLocal 在任务执⾏完之后会对Value清除避免内存泄露 <ul><li>哈希冲突的解决⽅法 <ul><li>拉链法</li><li>红⿊树</li><li>线性探测法 <ul><li>寻找最靠近的下⼀个空槽</li></ul></li></ul></li></ul></li></ul><h4 id="遍历集合你一般使用什么方式" tabindex="-1">遍历集合你一般使用什么方式 <a class="header-anchor" href="#遍历集合你一般使用什么方式" aria-label="Permalink to &quot;遍历集合你一般使用什么方式&quot;">​</a></h4><ul><li>增强 for 循环</li><li>迭代器</li><li>for 循环</li><li>stream</li></ul><h4 id="集合中使用最多的应该是-arraylist-项目中你怎么使用他的-使用的时候要注意什么。" tabindex="-1">集合中使用最多的应该是 ArrayList，项目中你怎么使用他的，使用的时候要注意什么。 <a class="header-anchor" href="#集合中使用最多的应该是-arraylist-项目中你怎么使用他的-使用的时候要注意什么。" aria-label="Permalink to &quot;集合中使用最多的应该是 ArrayList，项目中你怎么使用他的，使用的时候要注意什么。&quot;">​</a></h4><p>ArrayList 首先他是一个动态的数组，底层是 Array。</p><p>每次 add 新增元素的时候会判断是否要扩容，默认初始容量是 16，如果不够容量会按照 1.5 倍进行扩容。</p><h4 id="你对链表-linkedlist-的理解讲述一下。" tabindex="-1">你对链表 LinkedList 的理解讲述一下。 <a class="header-anchor" href="#你对链表-linkedlist-的理解讲述一下。" aria-label="Permalink to &quot;你对链表 LinkedList 的理解讲述一下。&quot;">​</a></h4><p>LinkedList 本身也是一个动态数组，不够他的底层结构是链表。他的插入和删除很方便，只需要修改指针就行，但是遍历的时候需要从链表头部开始查找。</p><h4 id="copyonwritearraylist-这个集合你知道吗-怎么使用的你讲述下。" tabindex="-1">CopyOnWriteArrayList 这个集合你知道吗，怎么使用的你讲述下。 <a class="header-anchor" href="#copyonwritearraylist-这个集合你知道吗-怎么使用的你讲述下。" aria-label="Permalink to &quot;CopyOnWriteArrayList 这个集合你知道吗，怎么使用的你讲述下。&quot;">​</a></h4><p>这种其实就是 java.util.concurrent 并发包下的类，在多线程的情况下，最好使用一下相关的类。</p><p>他非常适合读多写的场景，每次修改操作（如添加、删除、更新）时，都创建一个新数组来保证线程安全。</p><h4 id="hashmap的扩容机制讲讲。" tabindex="-1">HashMap的扩容机制讲讲。 <a class="header-anchor" href="#hashmap的扩容机制讲讲。" aria-label="Permalink to &quot;HashMap的扩容机制讲讲。&quot;">​</a></h4><ul><li>1.7 头插法会导致循环链表问题 <ul><li>由于每次插入都会改变链表的顺序，这可能会导致长时间的性能下降</li></ul></li><li>1.8 改为了尾插法，在并发修改时减少了循环链表出现的风险</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240311195612.png" alt="image.png"></p><ul><li>头插</li><li>尾插</li><li>扩容</li></ul><h3 id="并发" tabindex="-1">并发 <a class="header-anchor" href="#并发" aria-label="Permalink to &quot;并发&quot;">​</a></h3><h4 id="高并发场景下-死锁如何避免。" tabindex="-1">高并发场景下，死锁如何避免。 <a class="header-anchor" href="#高并发场景下-死锁如何避免。" aria-label="Permalink to &quot;高并发场景下，死锁如何避免。&quot;">​</a></h4><h4 id="阻塞队列长度设置" tabindex="-1">阻塞队列长度设置 <a class="header-anchor" href="#阻塞队列长度设置" aria-label="Permalink to &quot;阻塞队列长度设置&quot;">​</a></h4><ul><li>如果任务执行时间较长，建议设置较大的队列长度，以防止过多的任务被拒绝。</li></ul><h4 id="什么是-cas" tabindex="-1">什么是 CAS <a class="header-anchor" href="#什么是-cas" aria-label="Permalink to &quot;什么是 CAS&quot;">​</a></h4><ul><li>比较并交换</li></ul><h4 id="线程池中-如果一个线程没有捕获异常-发送异常后会发生什么情况" tabindex="-1">线程池中，如果一个线程没有捕获异常，发送异常后会发生什么情况 <a class="header-anchor" href="#线程池中-如果一个线程没有捕获异常-发送异常后会发生什么情况" aria-label="Permalink to &quot;线程池中，如果一个线程没有捕获异常，发送异常后会发生什么情况&quot;">​</a></h4><ul><li><p>当线程在执行任务时抛出未捕获的异常，该线程会立即终止。这意味着任务没有正确完成，并且该线程将不再继续执行后续代码。</p></li><li><p>线程池（如 <code>ThreadPoolExecutor</code>）有一个内部机制来捕获线程抛出的异常。默认情况下，线程池会记录这个异常，但不会重新抛出或进行其他特殊处理。任务的提交者（调用 <code>submit</code> 方法的线程）不会直接感知到异常，除非通过 <code>Future</code> 获取任务的执行结果。</p></li><li><p>线程池会创建一个新的线程来替换抛出异常并终止的线程，从而保证线程池中的线程数量维持在配置的核心线程数或最大线程数。线程池本身不会因为一个线程的异常而崩溃或停止工作。</p></li><li><p>使用 <code>Future.get()</code> 可以捕获任务抛出的异常</p></li></ul><h4 id="可见性" tabindex="-1">可见性 <a class="header-anchor" href="#可见性" aria-label="Permalink to &quot;可见性&quot;">​</a></h4><p>volatile 保证</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240326205410.png" alt="image.png"></p><h4 id="原子性" tabindex="-1">原子性 <a class="header-anchor" href="#原子性" aria-label="Permalink to &quot;原子性&quot;">​</a></h4><ul><li>这里 synchronized 的描述优点问题，是先有 偏向锁，再有轻量级锁，再有自旋锁，然后是重量级锁</li><li>如果问 AQS 的话，其实是有一个 acquire 方法之类的进行加锁和放锁的操作</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240312224915.png" alt="image.png"></p><ul><li><p>改一下：原子性一般是线程通过对资源加锁的方式来实现的，这里可以引入 synchronized 和 ReetrantLock 的相关内容</p></li><li><p>synchronized 的重量级锁</p></li></ul><h4 id="线程状态" tabindex="-1">线程状态 <a class="header-anchor" href="#线程状态" aria-label="Permalink to &quot;线程状态&quot;">​</a></h4><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240304154734.png" alt="image.png"></p><p>阻塞：没有获取到资源（没有获取到锁）</p><ul><li>线程状态</li></ul><h4 id="线程池" tabindex="-1">线程池 <a class="header-anchor" href="#线程池" aria-label="Permalink to &quot;线程池&quot;">​</a></h4><ul><li><p>使用场景</p><ul><li>1、异步</li><li>2、记录日志</li><li>3、定时任务</li></ul></li><li><p>线程池的核心线程数可以设置为 0 （通过非核心线程去处理任务）</p></li><li><p>阻塞队列</p><ul><li>Array 单个锁</li><li>Linked 两个锁，加锁</li></ul></li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240313111136.png" alt="image.png"></p><p>callable 接口回调：</p><p><code>FutureTask</code> 提供了 <code>Future</code> 接口的基本实现，常用来封装 <code>Callable</code> 和 <code>Runnable</code>，具有取消任务、查看任务是否执行完成以及获取任务执行结果的方法</p><blockquote><p>为什么不建议使用 Execution 创建线程池</p></blockquote><p><code>Executors</code> 返回线程池对象的弊端如下(后文会详细介绍到)：</p><ul><li><strong><code>FixedThreadPool</code> 和 <code>SingleThreadExecutor</code></strong>：使用的是无界的 <code>LinkedBlockingQueue</code>，任务队列最大长度为 <code>Integer.MAX_VALUE</code>,可能堆积大量的请求，从而导致 OOM。</li><li><strong><code>CachedThreadPool</code></strong>：使用的是同步队列 <code>SynchronousQueue</code>, 允许创建的线程数量为 <code>Integer.MAX_VALUE</code> ，可能会创建大量线程，从而导致 OOM。</li><li><strong><code>ScheduledThreadPool</code> 和 <code>SingleThreadScheduledExecutor</code></strong> : 使用的无界的延迟阻塞队列<code>DelayedWorkQueue</code>，任务队列最大长度为 <code>Integer.MAX_VALUE</code>,可能堆积大量的请求，从而导致 OOM。</li></ul><p>说白了就是：<strong>使用有界队列，控制线程创建数量。</strong></p><p>除了避免 OOM 的原因之外，不推荐使用 <code>Executors</code>提供的两种快捷的线程池的原因还有：</p><ul><li>实际使用中需要根据自己机器的性能、业务场景来<strong>手动配置线程池的参数比如核心线程数、使用的任务队列、饱和策略</strong>等等。</li><li>我们应该显示地给我们的线程池命名，这样有助于我们定位问题</li></ul><blockquote><p>线程池参数定义</p></blockquote><p>核心线程数</p><ul><li>IO密集型： CPU核数 * 2</li><li>CPU计算性：CPU核心 + 1</li></ul><p>最大线程数</p><ul><li>一个常见的做法是设置最大线程数为核心线程数的2到4倍</li></ul><p>阻塞队列</p><ul><li>队列大小的设置取决于你期望的任务处理模式。如果希望能够缓冲大量的请求，那么可以设置较大的队列。如果希望减少等待时间，可以设置较小的队列</li><li>IO密集型： 设置多一些（会有网络阻塞等，等待线程可能会多）</li><li>CPU计算性：可以设置小一点（任务可以迅速完成，不需要太大的等待队列）</li></ul><hr><p><strong>理解有一个问题改一下（线程池的执行流程）</strong></p><ul><li>1、提交任务</li><li>2、核心线程处理任务</li><li>3、核心线程忙碌，放入新任务到阻塞队列</li><li>4、阻塞队列满了之后，再来一个任务，线程池会创建一个非核心线程去处理新的任务。当非核心线程完成它们的任务后，如果阻塞队列中还有待处理的任务，这些非核心线程也会从阻塞队列中取任务来执行。</li><li>5、如果 核心线程数 + 非核心线程数 &gt; 最大线程数，才会进行触发拒绝策略</li></ul><p>拒绝策略方式</p><ul><li>1.AbortPolicy:直接抛出异常，默认策略：</li><li>2.CallerRunsPolicy:用调用者所在的线程来执行任务；</li><li>3.DiscardOldestPolicy:丢弃阻塞队列中靠最前的任务，并执行当前任务：</li><li>4.DiscardPolicy:直接丢弃任务：</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240512172606.png" alt="image.png"></p><p>线程计算公式</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240512173029.png" alt="image.png"></p><p>假设：核数 12、CPU 利用率 90%，等待时间 50ms，计算时间51ms</p><p>N = 12 * 0.9 * (1 + 50/51) ≈ 22</p><p>设置核心线程数 22 是比较符合预期的值</p><p>在真实的程序中，<strong>一般很难获得准确的等待时间和计算时间，因为程序很复杂，不只是“计算”</strong>。一段代码中会有很多的内存读写，计算，I/O 等复合操作，精确的获取这两个指标很难，所以光靠公式计算线程数过于理想化。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240512173427.png" alt="image.png"></p><h4 id="死锁" tabindex="-1">死锁 <a class="header-anchor" href="#死锁" aria-label="Permalink to &quot;死锁&quot;">​</a></h4><p>线程死锁：通过 JVM 排查工具去排查到具体原因，然后定位现象</p><p>MySQL：一般有监控信息，可以看到，看到后进行处理，通过现象分析死锁原因，然后去进行事务或者SQL的优化</p><h4 id="使用-synchronized-修饰类和方法的区别" tabindex="-1">使用 synchronized 修饰类和方法的区别 <a class="header-anchor" href="#使用-synchronized-修饰类和方法的区别" aria-label="Permalink to &quot;使用 synchronized 修饰类和方法的区别&quot;">​</a></h4><ul><li><code>synchronized</code>修饰代码块（类锁） <ul><li>当使用<code>synchronized</code>修饰代码块时，需要指定一个锁对象。如果指定的是类的<code>Class</code>对象，那么这个<code>synchronized</code>代码块就相当于对这个类进行了锁定。</li></ul></li><li><code>synchronized</code>修饰方法 <ul><li>当<code>synchronized</code>修饰一个实例方法时， <ul><li>它锁定的是当前实例对象。</li><li>这意味着，同一时间内，<strong>只有一个线程能够访问这个对象的所有<code>synchronized</code>实例方法</strong>。如果一个线程访问该对象的一个<code>synchronized</code>实例方法，其他线程试图访问该对象的任何其他<code>synchronized</code>实例方法将会被阻塞，直到第一个线程完成方法的执行。</li></ul></li><li>当<code>synchronized</code>修饰一个静态方法时， <ul><li>它锁定的是这个类的所有实例。因为静态方法是属于类的，而不是任何实例对象的，所以此时锁定的是类的<code>Class</code>对象本身。这意味着，同一时间内，<strong>只有一个线程能够访问这个类的所有<code>synchronized</code>静态方法。</strong></li></ul></li></ul></li></ul><h4 id="死锁问题如何排查定位" tabindex="-1">死锁问题如何排查定位 <a class="header-anchor" href="#死锁问题如何排查定位" aria-label="Permalink to &quot;死锁问题如何排查定位&quot;">​</a></h4><ul><li><strong>排查定位</strong>：使用线程转储、监控工具和日志分析来识别死锁。</li><li><strong>解决</strong>：通过调整锁顺序、使用 <code>tryLock</code>、破坏死锁条件等方法来解决死锁问题。</li><li><strong>避免</strong>：避免嵌套锁定、使用超时锁定、采用高层次锁定机制、排序和定期检测等方法来避免死锁。</li></ul><p>tryLock：ReentrantLock 的加锁方法，一般为了避免死锁可以用它并设置下超时时间</p><p>如何排查：一般需要查看当前死锁的进程是哪个，然后通过 jstack 之类的操作进行生成转储文件，通过 VisualVM 工具之类的进行查看，生产情况下可能需要通过适当时间重启并优化程序的方式来进行解决；</p><p>如何避免：可以使用数据库锁、分布式锁来避免代码的显示问题</p><h3 id="计算机网络" tabindex="-1">计算机网络 <a class="header-anchor" href="#计算机网络" aria-label="Permalink to &quot;计算机网络&quot;">​</a></h3><h4 id="从http协议跟报文的角度上-讲一下session和cookie的关系是什么" tabindex="-1">从HTTP协议跟报文的角度上，讲一下session和cookie的关系是什么？ <a class="header-anchor" href="#从http协议跟报文的角度上-讲一下session和cookie的关系是什么" aria-label="Permalink to &quot;从HTTP协议跟报文的角度上，讲一下session和cookie的关系是什么？&quot;">​</a></h4><h4 id="http协议在osi七层模型中的哪一层-osi七层模型讲一下-tcp和udp在哪一层-口述一下tcp的三次握手和四次挥手" tabindex="-1">HTTP协议在OSI七层模型中的哪一层？OSI七层模型讲一下，TCP和UDP在哪一层，口述一下TCP的三次握手和四次挥手 <a class="header-anchor" href="#http协议在osi七层模型中的哪一层-osi七层模型讲一下-tcp和udp在哪一层-口述一下tcp的三次握手和四次挥手" aria-label="Permalink to &quot;HTTP协议在OSI七层模型中的哪一层？OSI七层模型讲一下，TCP和UDP在哪一层，口述一下TCP的三次握手和四次挥手&quot;">​</a></h4><h3 id="mysql" tabindex="-1">MySQL <a class="header-anchor" href="#mysql" aria-label="Permalink to &quot;MySQL&quot;">​</a></h3><h4 id="常见编码和字符集" tabindex="-1">常见编码和字符集 <a class="header-anchor" href="#常见编码和字符集" aria-label="Permalink to &quot;常见编码和字符集&quot;">​</a></h4><ul><li><strong>UTF-8</strong>：最常用的字符编码，支持所有的 Unicode 字符。</li><li><strong>UTF-8MB4</strong>：UTF-8 的扩展版本，支持 4 字节 Unicode 字符（如表情符号）</li></ul><h4 id="varchar-和-char-的区别" tabindex="-1"><code>VARCHAR</code> 和 <code>CHAR</code> 的区别 <a class="header-anchor" href="#varchar-和-char-的区别" aria-label="Permalink to &quot;`VARCHAR` 和 `CHAR` 的区别&quot;">​</a></h4><ul><li><strong>VARCHAR</strong><ul><li>可变长度字符数据类型。</li><li>存储时仅保存实际字符串的长度，并在前面加上一个或两个字节来存储字符串的长度（长度 &lt;= 255 时使用一个字节，长度 &gt; 255 时使用两个字节）</li><li>可变长度，节省空间，适用于存储长度不确定或变化较大的字符串。</li><li><code>VARCHAR</code> 类型可以存储的最大字符数是 65535 字节</li></ul></li><li><strong>CHAR</strong><ul><li>固定长度字符数据类型。</li><li>固定长度，性能稳定，适用于存储长度固定或变化较小的字符串。</li></ul></li></ul><h4 id="你们慢查事件怎么处理的。" tabindex="-1">你们慢查事件怎么处理的。 <a class="header-anchor" href="#你们慢查事件怎么处理的。" aria-label="Permalink to &quot;你们慢查事件怎么处理的。&quot;">​</a></h4><p>其实一般会有慢查报告和监听，这种一般都是架构那边的工作。我们会拿到具体的执行SQL，然后去做执行分析。然后索引执行情况。其实使用最多的时候，还是最多匹配的方式，添加索引，但是有时候索引加了效果也挺一般的，这个时候就是因为大表的原因，我们就会冷热表分离，但是具体场景具体分析，要看实际上是怎么做的。</p><h4 id="平时开发中对于数据库查询有没有什么特别注意的事项" tabindex="-1">平时开发中对于数据库查询有没有什么特别注意的事项？ <a class="header-anchor" href="#平时开发中对于数据库查询有没有什么特别注意的事项" aria-label="Permalink to &quot;平时开发中对于数据库查询有没有什么特别注意的事项？&quot;">​</a></h4><p>尽量查询或者更新通过ID去具体更新，而不是直接根据范围。ID 一般会命中索引，更新效率也挺高。</p><p>我们一般使用很多的情况也会是走覆盖索引，能够进行回表操作。</p><p>流程</p><ul><li>根据业务完成sql代码之后，可以先评估有哪些字段需要索引，尽 量使⽤组合索引</li><li>后续根据线上 skywalking/grafana/监控告警/耗时⽇志 去观察接 ⼝以及定位慢SQL，再通过explain⼯具以及DBA建议进⾏优化， ⼀般情况下都能处理，如果索引优化已经满⾜不了业务场景了， 可以使⽤ES作为查询⼯具(将数据的关键字段 通过MQ + canal/ogg 同步到ES)</li></ul><h4 id="日常工作中-你看-explain-会关注什么字段信息-怎么判断要不要添加一个索引。" tabindex="-1">日常工作中，你看 EXPLAIN 会关注什么字段信息，怎么判断要不要添加一个索引。 <a class="header-anchor" href="#日常工作中-你看-explain-会关注什么字段信息-怎么判断要不要添加一个索引。" aria-label="Permalink to &quot;日常工作中，你看 EXPLAIN 会关注什么字段信息，怎么判断要不要添加一个索引。&quot;">​</a></h4><p><strong>EXPLAIN 重点看什么？</strong></p><p>执行<code>EXPLAIN</code>时，你的目光可以聚焦在这几个核心字段上，它们是判断查询效率的“仪表盘”：</p><ul><li><strong><code>type</code> (访问类型)</strong>：这是<strong>最重要的字段</strong>，直接反映了查询的“好坏”。优化目标至少是<code>range</code>级别，要极力避免出现<code>ALL</code>（全表扫描）或<code>index</code>（全索引扫描）。理想状态是<code>const</code>、<code>eq_ref</code>或<code>ref</code>。</li><li><strong><code>key</code></strong>：显示MySQL<strong>实际决定使用的索引</strong>。如果这里是<code>NULL</code>，意味着没走索引，通常需要创建或优化索引。</li><li><strong><code>rows</code></strong>：这是<strong>预估需要扫描的行数</strong>。关键不在于绝对值大小，而在于它与最终返回行数的<strong>比例</strong>。如果<code>rows</code>很大但返回结果很少，说明索引过滤性不好。</li><li><strong><code>Extra</code></strong>：包含了很多关键细节，几个重要值包括：<strong><code>Using index</code></strong>（用了覆盖索引，无需回表，性能好）、<strong><code>Using filesort</code></strong>（需要额外排序，可能需优化<code>ORDER BY</code>的索引）、<strong><code>Using temporary</code></strong>（使用了临时表，通常需要关注）。</li></ul><p><strong>添加索引的经验与衡量指标是什么？</strong></p><p>设计索引时，可以遵循一套从经验法则到量化指标的决策流程：</p><ol><li><strong>核心前提：查询频繁度</strong>。只为<strong>频繁出现在<code>WHERE</code>、<code>ORDER BY</code>、<code>GROUP BY</code>或<code>JOIN</code>条件中</strong>的字段建立索引。</li><li><strong>黄金量化指标：区分度 (Cardinality)</strong>。这是最重要的衡量标准，计算公式为 <strong><code>COUNT(DISTINCT column_name) / COUNT(*)</code></strong>。区分度越接近1，索引过滤性越好。一般来说，<strong>区分度超过33%</strong> 就算比较高效了。比如，身份证号区分度极高（≈1），适合建索引；而性别字段区分度极低（≈0.002），单独建索引意义不大，但如果<strong>和区分度高的字段组成联合索引</strong>，则能发挥作用。</li><li><strong>其他重要原则</strong>： <ul><li><strong>最左前缀原则</strong>：设计联合索引时，把最常用、区分度最高的列放在最左边。</li><li><strong>覆盖索引优先</strong>：尽量让查询所需的列都包含在索引中，避免回表，性能提升显著。</li><li><strong>控制索引数量</strong>：索引虽好，但会降低写入性能。<strong>单表索引数量建议不超过5个</strong>。</li><li><strong>索引列尽量小</strong>：优先选择整型、较短的字符串，因为索引键越短，B+树节点能容纳的键越多，树越矮，IO效率越高。</li></ul></li></ol><p>这里记忆 explain 的字段建议还是直接执行看，关于一下 type，key，rows，Extra；</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20261108195458011.png" alt="image.png"></p><p>上面这个SQL 还有一个小细节</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20261108195548383.png" alt="image.png"></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>explain</span></span>\n<span class="line"><span>select * from collaboration_artifact ca where ca.room_id = 100;</span></span></code></pre></div><p>如果不添加双引号操作，还会触发隐式转换导致索引失效：<strong>隐式转换为数字</strong>来进行比较。这就相当于在索引列上使用了函数： <code>where CAST(room_id AS SIGNED) = 100;</code>。</p><h4 id="什么情况下会切换索引结构-已经有数据后-还能更新索引结构吗" tabindex="-1">什么情况下会切换索引结构？已经有数据后，还能更新索引结构吗？ <a class="header-anchor" href="#什么情况下会切换索引结构-已经有数据后-还能更新索引结构吗" aria-label="Permalink to &quot;什么情况下会切换索引结构？已经有数据后，还能更新索引结构吗？&quot;">​</a></h4><p><strong>什么情况下会切换索引结构？</strong></p><p>在MySQL的InnoDB引擎中，<strong>默认且几乎总是使用B+树索引</strong>，一般不需要切换。只有在极少数特殊场景下才会考虑其他结构，例如：</p><ul><li><strong>哈希索引</strong>：仅适用于<strong>等值查询</strong>（如内存表或自适应哈希索引），不支持范围查询和排序。</li><li><strong>全文索引</strong>：用于解决<strong>文本内容的模糊搜索</strong>问题，底层是倒排索引。</li><li><strong>空间索引</strong>：用于<strong>地理空间数据</strong>（如经纬度）的查询。</li></ul><p><strong>已经有数据后，还能更新索引结构吗？</strong></p><p><strong>可以，但操作代价不同</strong>。主要涉及<strong>添加/删除索引</strong>和<strong>修改主键（聚簇索引）</strong> 两种情况：</p><ul><li><strong>添加/删除二级索引</strong>：在MySQL 5.6+中，通常可以使用<strong>在线DDL（Online DDL）</strong> 完成，一般<strong>允许并发DML</strong>（即增删改操作），对业务影响较小。</li><li><strong>修改聚簇索引（主键）</strong>：这是一个<strong>重量级操作</strong>。MySQL会创建一个包含新索引结构的临时表，将数据<strong>全量复制</strong>过去，然后用新表替换旧表。这个过程<strong>通常会阻塞所有查询</strong>，需要在维护窗口进行。</li></ul><p><strong>索引是单个表维度的，还是数据库维度的？</strong></p><p><strong>索引是表级别的</strong>。每个索引都直接建立在某一张具体的表上，只加速对该表的查询，不会跨表生效。虽然索引定义是表级的，但在<strong>分区表</strong>中，索引会在每个分区上分别创建和维护，逻辑上仍属于该表。</p><h4 id="常见的索引结构" tabindex="-1">常见的索引结构 <a class="header-anchor" href="#常见的索引结构" aria-label="Permalink to &quot;常见的索引结构&quot;">​</a></h4><ul><li>二叉树</li><li>红黑树</li><li>哈希表</li><li>B-Tree</li><li>B+Tree</li></ul><h4 id="b树和b-树的区别" tabindex="-1">B树和B+树的区别？ <a class="header-anchor" href="#b树和b-树的区别" aria-label="Permalink to &quot;B树和B+树的区别？&quot;">​</a></h4><p>B树各节点都存数据，B+树非叶子只存索引，数据全在最底层</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20261108203945767.png" alt="image.png|800"></p><blockquote><p>?为什么 MySQL（InnoDB）选择了 B+ 树而不是 B 树？</p></blockquote><ol><li><strong>范围查询极多</strong>：数据库经常有 <code>WHERE id &gt; 10</code>、<code>ORDER BY</code> 这样的操作，B+树的叶子链表简直是为此量身定制的。</li><li><strong>磁盘IO要求极致</strong>：MySQL 数据存在磁盘里，IO 是最大的瓶颈。B+树的非叶子节点不存数据，使得树变得<strong>更矮更胖</strong>。一棵三层高的B+树（根节点常驻内存，只需2次磁盘IO）就能存2000万行左右的数据，极大地减少了磁盘访问次数。</li><li><strong>全表扫描更快</strong>：B+树只需要遍历一遍叶子节点的链表即可拿到全表数据；而B树需要遍历整棵树的所有节点，效率极低。</li></ol><p>个人理解更多还是结构上的差别，B+树这种结构更加适合IO稳定（就是第二点，减少磁盘访问速度，访问效率高）</p><h4 id="索引失效" tabindex="-1">索引失效 <a class="header-anchor" href="#索引失效" aria-label="Permalink to &quot;索引失效&quot;">​</a></h4><ul><li>对于组合索引 没有⾛ 左前缀原则 会导致索引失效</li><li>进⾏like模糊查询时，%放在索引字段之前⾛不了索引下推会导致索 引失效，倘若数据量过⼤，索引下推会失效</li><li>查询条件的类型为字符串时，没有加单引号，可能因为类型不同导致 索引失效</li><li>对索引列进⾏计算会导致索引失效</li><li>查询条件使⽤or连接会导致索引失效</li><li>判断索引列不等于某个值时会导致索引失效</li></ul><h4 id="索引优化原则" tabindex="-1">索引优化原则 <a class="header-anchor" href="#索引优化原则" aria-label="Permalink to &quot;索引优化原则&quot;">​</a></h4><ul><li>不要基于使⽤频率较低的列加索引</li><li>组合索引列、排序要遵循 左前缀原则</li><li>where 和 order by冲突时优先使⽤where，能⽤where过滤就不要 使⽤having <ul><li>不要对索引列进⾏运算，⽐如使⽤函数 <ul><li>MySQL 8/Oracle⽀持函数索引，但是数据量过⼤时，索引 列维护成本较⾼</li></ul></li></ul></li><li>不要⽤or连接索引列 <ul><li>对于like的使⽤，尽量使⽤右模糊匹配，让索引可以⾛索引下 推 <ul><li>%A%、%A不⾛索引</li><li>A%⼀般情况下可以⾛索引下推，但是数据量过⼤时会导致 失效</li></ul></li></ul></li><li>索引列判空，⽐如is null、is not null不⾛索引 <ul><li>join要做到小表驱动⼤表 <ul><li>left join 左⼩右⼤</li><li>right join 右⼩左⼤</li><li>inner join 优化器会处理</li></ul></li><li>in、exists要做到小表驱动⼤表 <ul><li>in 适合 ⼦表小于主表的，exists反之</li></ul></li></ul></li><li>索引列建议都设置为not null，可以节省1字节</li><li>对于获取总数count优先使⽤count( * ) 或 count(1)，如果数据量过 ⼤建议采⽤ES进⾏记录 <ul><li>倘若count字段有索引，count(* ) = count(1) &gt; count(字段) &gt; count(主键) <ul><li>count(字段)效率⽐count(主键)好的原因是⾛了覆盖索引， ⼆级索引树⽐主键索引树数据量⼩</li></ul></li><li>倘若count字段⽆索引，count( * ) = count(1) &gt; count(主键) &gt; count(字段)</li></ul></li><li>频繁增删改的字段不要加索引，数据量⼀⼤维护成本会很⾼</li><li>⻓字符串可以采纳左20字符作为索引，满⾜90%场景</li><li>查询字段时，能采⽤覆盖索引的地⽅就去使⽤，避免查全部字段</li></ul><h4 id="讲述一下聚簇-vs-非聚簇索引的区别-以及-索引失效-的情况一般有哪些-以及怎么处理的。什么是索引覆盖" tabindex="-1">讲述一下聚簇 vs 非聚簇索引的区别，以及 索引失效 的情况一般有哪些，以及怎么处理的。什么是索引覆盖？ <a class="header-anchor" href="#讲述一下聚簇-vs-非聚簇索引的区别-以及-索引失效-的情况一般有哪些-以及怎么处理的。什么是索引覆盖" aria-label="Permalink to &quot;讲述一下聚簇 vs 非聚簇索引的区别，以及 索引失效 的情况一般有哪些，以及怎么处理的。什么是索引覆盖？&quot;">​</a></h4><p><strong>聚簇索引和非聚簇索引</strong></p><ul><li><strong>聚簇索引 (Clustered Index)</strong>：通常是<strong>主键索引</strong>。叶子节点直接存储<strong>完整的行数据</strong>。找到索引就找到了数据。一张表<strong>有且只有一个</strong>聚簇索引。</li><li><strong>非聚簇索引 (Non-Clustered Index)</strong>：也叫<strong>二级索引</strong>或辅助索引。叶子节点存储的是<strong>主键值</strong>。通过它查询通常需要<strong>回表</strong>：先找到二级索引树中的主键，再拿主键去聚簇索引树中查找完整行数据。一张表可以有<strong>多个</strong>非聚簇索引。</li></ul><p>一般主键是聚簇索引，唯一主键或者ID更多一点。</p><p><strong>InnoDB 的聚簇索引默认是主键索引，但主键不一定是 <code>id</code>，也不一定是自增 <code>id</code>。有显式主键就用主键；没有主键就用第一个唯一非空索引；都没有就用隐藏 <code>rowid</code>。大家常用自增 <code>id</code> 做主键，是因为它短、有序、不变，对 B+ 树和二级索引最友好，不是 InnoDB 强制要求</strong></p><p><strong>具体例子说明</strong></p><p>假设有<code>student</code>表：<code>id</code> (主键)，<code>no</code> (唯一索引)，<code>name</code>，<code>address</code>。</p><ol><li><p><strong>查询<code>SELECT * FROM student WHERE id = 1;</code></strong></p><ul><li>走<strong>聚簇索引</strong>。在<code>id</code>的B+树叶子节点直接拿到整行数据，<strong>无需回表</strong>。</li></ul></li><li><p><strong>查询<code>SELECT name FROM student WHERE no = &#39;test&#39;;</code></strong></p><ul><li>走<strong>非聚簇索引</strong>（<code>no</code>索引）。先在<code>no</code>的B+树叶子节点找到主键<code>id</code>的值，然后<strong>必须回表</strong>，用这个<code>id</code>再去聚簇索引中查找<code>name</code>字段。</li></ul></li><li><p><strong>查询<code>SELECT no FROM student WHERE no = &#39;test&#39;;</code></strong></p><ul><li>走<strong>非聚簇索引</strong>，但发生<strong>覆盖索引</strong>。查询需要的<code>no</code>字段已经在<code>no</code>索引的叶子节点中，<strong>无需回表</strong>。</li></ul></li></ol><p><strong>索引失效能通过EXPLAIN看到吗？是不是直接改SQL、加索引？</strong></p><p><strong><code>EXPLAIN</code>是 发现索引失效 最直接的工具。</strong> 如果一条SQL本该走索引但<code>key</code>显示为<code>NULL</code>（或走了不合适的索引），<code>type</code>为<code>ALL</code>，就说明索引失效了。</p><p>但<strong>不能“直接改SQL，然后新增索引”</strong>，正确的优化流程是一个先诊断后治疗的闭环：</p><ol><li><strong>定位慢查询</strong>：从慢查询日志中找到真实的慢SQL。</li><li><strong>用<code>EXPLAIN</code>分析</strong>：判断是“没索引”（<code>key</code>为<code>NULL</code>）还是“索引失效”（有索引但没被用上）。</li><li><strong>分类修复</strong>： <ul><li><strong>如果“没索引”</strong>：根据前面的设计原则（区分度、最左前缀等）<strong>新增索引</strong>。</li><li><strong>如果“索引失效”</strong>：<strong>优先改写SQL</strong>。索引失效常由以下原因引起，改写SQL通常比加索引更有效： <ul><li>对索引列使用<strong>函数</strong>或<strong>表达式</strong>。</li><li><strong>隐式类型转换</strong>（如字符串列用数字查）。</li><li>使用<strong>前导模糊查询</strong><code>LIKE &#39;%abc&#39;</code>。</li><li>联合索引<strong>不满足最左前缀</strong>。</li></ul></li></ul></li><li><strong>验证效果</strong>：优化后，<strong>再次执行<code>EXPLAIN</code></strong>，确认<code>key</code>、<code>rows</code>、<code>Extra</code>等字段是否符合预期。</li></ol><p>所以，整个过程是：<strong>用<code>EXPLAIN</code>发现问题 → 判断是“缺索引”还是“索引失效” → 缺索引则加，失效则优先改SQL → 最后用<code>EXPLAIN</code>验证</strong>。</p><hr><p>索引覆盖：</p><p>非聚簇索引查询索引字段的时候，不用进行回表的时候，直接就可以通过索引覆盖查询（其实就是 B+ 树的叶子节点就是查询的数据，不用通过主键回表查整行数据）。</p><h4 id="sql-的执行流程" tabindex="-1">SQL 的执行流程 <a class="header-anchor" href="#sql-的执行流程" aria-label="Permalink to &quot;SQL 的执行流程&quot;">​</a></h4><ul><li>客户端 通过 连接器 进⾏权限验证，⽼版本的先去判断有没有开启缓 存，如果开启了，先从缓存中查询数据返回，</li><li>如果没有开启，就通过 词法分析器去 进⾏词法分析，然后通过 优化器 去进⾏SQL优化，然 后再通过 执⾏器 去选择 存储引擎 去进⾏SQL执⾏ <ul><li>客户端 -&gt; (缓存) -&gt; 词法分析器 -&gt; 优化器 -&gt; 执⾏器 -&gt; 存储引擎</li></ul></li></ul><blockquote><p>5.7 以后缓存默认不开启</p></blockquote><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20261108202444263.png" alt="image.png"></p><h4 id="mqsql-引擎层是如何工作的" tabindex="-1">MqSql 引擎层是如何工作的？ <a class="header-anchor" href="#mqsql-引擎层是如何工作的" aria-label="Permalink to &quot;MqSql 引擎层是如何工作的？&quot;">​</a></h4><h4 id="为什么要选择使用-starrocks-数据库。" tabindex="-1">为什么要选择使用 StarRocks 数据库。 <a class="header-anchor" href="#为什么要选择使用-starrocks-数据库。" aria-label="Permalink to &quot;为什么要选择使用 StarRocks 数据库。&quot;">​</a></h4><p>StarRocks 是一款<strong>新一代 MPP（大规模并行处理）架构的 OLAP（在线分析处理）数据库</strong>，核心定位是解决海量数据下的<strong>实时、多维、高并发分析</strong>问题</p><p>StartRocks 数据库类似ES高查询性能的数据库，他的架构设计就比较支持大数据查询，而且性能比较好，不过实际下来，在进行分区和更新的时候还是会有一些问题。</p><h4 id="讲一下-mysql-的事务。" tabindex="-1">讲一下 MySQL 的事务。 <a class="header-anchor" href="#讲一下-mysql-的事务。" aria-label="Permalink to &quot;讲一下 MySQL 的事务。&quot;">​</a></h4><p>首先事务有四大特性：原子性、一致性、隔离性、持久性。</p><ul><li>原子性 Atomicity <ul><li>要么全部成功，要么全部失败</li></ul></li><li>一致性 Consistency <ul><li>数据在事务的开始到结束的过程中要保持⼀致</li><li>一致性是目的，AID 都是手段。</li></ul></li><li>隔离性 Isolation <ul><li>每个事务要互相隔离</li></ul></li><li>持久性 Durability <ul><li>事务完成后数据会被持久化下来</li></ul></li></ul><p>如果没有遵循这四大特征：破坏了里面的“隔离性（I）”和“一致性（C）”，会出现：脏写、脏读、不可重复读、幻读 的情况。</p><ul><li>脏写 <ul><li>操作同⼀数据时，⼀个事务的修改被另外⼀个事务的修改覆盖</li><li><strong>脏写其实违反了原子性</strong>，在<strong>任何隔离级别下，脏写都是绝对不允许的</strong>。</li><li>如何解决：靠<strong>行锁</strong>解决。两个事务改同一行，后一个等前一个释放锁。</li></ul></li><li>脏读 <ul><li>⼀个事务读取了另⼀个事务尚未提交的数据时</li><li>如何解决： <ul><li>靠 <strong>MVCC 的 ReadView</strong> 解决。RC 下每次查询生成新 ReadView，只看到已提交事务；未提交的版本不可见。</li></ul></li><li>MVCC 理解 <ul><li><strong>MVCC 只在“快照读”（普通 <code>SELECT</code>）下生效</strong>。如果事务中用了 <code>SELECT ... FOR UPDATE</code> 或 <code>UPDATE</code> / <code>DELETE</code>（<strong>当前读</strong>），MVCC 就失效了，必须靠 <strong>Next-Key Lock（记录锁+间隙锁）</strong> 来防止别的插入</li><li></li></ul></li></ul></li><li>不可重复读 <ul><li>同⼀事务下，由于其他事务的修改导致同⼀数据被读取两次的结 果不⼀致</li><li>针对场景：针对的是 <strong>UPDATE</strong>。两次读<strong>同一行</strong>，数据变了</li><li>RR 下事务第一次快照读生成 ReadView 后<strong>复用</strong>，后续快照读都看同一个一致性视图，别的事务提交的 UPDATE 不可见。</li></ul></li><li>幻读 <ul><li>⼀个事务读取到另外⼀个事务已提交的新增数据</li><li>针对场景：针对的是 <strong>INSERT / DELETE</strong>。两次读<strong>同一范围</strong>，行数变了</li><li>RR 下快照读靠 MVCC 解决；当前读靠 <strong>Next-Key Lock</strong> 锁住索引区间，阻止范围内插入。</li></ul></li></ul><p>其中隔离级别与上面四个问题的对应</p>',236)),a("table",u,[l[23]||(l[23]=a("thead",null,[a("tr",null,[a("th",null,"隔离级别"),a("th"),a("th",null,"脏写"),a("th",null,"脏读"),a("th",null,"不可重复读"),a("th",null,"幻读")])],-1)),a("tbody",null,[l[20]||(l[20]=a("tr",null,[a("td",null,"READ UNCOMMITTED"),a("td",null,"读未提交"),a("td",null,"不允许"),a("td",null,[a("strong",null,"允许")]),a("td",null,"允许"),a("td",null,"允许")],-1)),l[21]||(l[21]=a("tr",null,[a("td",null,"READ COMMITTED"),a("td",null,"读已提交"),a("td",null,"不允许"),a("td",null,"解决"),a("td",null,[a("strong",null,"允许")]),a("td",null,"允许")],-1)),l[22]||(l[22]=a("tr",null,[a("td",null,"REPEATABLE READ（MySQL 默认）"),a("td",null,"可重复读"),a("td",null,"不允许"),a("td",null,"解决"),a("td",null,"解决"),a("td",null,"快照读基本解决；当前读用 Next-Key Lock 解决")],-1)),a("tr",null,[l[15]||(l[15]=a("td",null,"SERIALIZABLE",-1)),l[16]||(l[16]=a("td",null,"串行化",-1)),l[17]||(l[17]=a("td",null,"不允许",-1)),l[18]||(l[18]=a("td",null,"解决",-1)),l[19]||(l[19]=a("td",null,"解决",-1)),a("td",null,[s(e,{color:"#4bacc6"},{default:o(()=>[...l[14]||(l[14]=[i("解决",-1)])]),_:1})])])])]),l[27]||(l[27]=n(`<p><strong>隔离级别越高，越接近完全隔离，并发问题越少，但并发性能越低。</strong></p><p>关于串行化：所有读操作后⾯加读锁 lock in share mode，因为读锁、写锁 互斥，所以不能同时发⽣</p><hr><p>MySQL8的默认隔离级别是什么？可重复读。</p><h4 id="行锁什么情况下会升级为表锁" tabindex="-1">行锁什么情况下会升级为表锁 <a class="header-anchor" href="#行锁什么情况下会升级为表锁" aria-label="Permalink to &quot;行锁什么情况下会升级为表锁&quot;">​</a></h4><p>在 MySQL 的 InnoDB 存储引擎中，行锁（Row Lock）是默认的锁机制，</p><ul><li>大量行锁导致内存耗尽</li><li>表扫描导致锁定所有行</li><li>锁升级 <ul><li>多个行锁导致的锁升级。</li><li>当多个行锁导致死锁或锁冲突时，InnoDB 可能会选择将行锁升级为表锁以简化锁管理。</li></ul></li></ul><p>为避免行锁升级为表锁，可以采取以下策略：</p><ul><li>使用合适的索引。</li><li>分批处理大数据量操作。</li><li>控制事务长度，减少锁的持有时间。</li><li>使用合适的隔离级别，降低锁冲突</li></ul><h4 id="数据库死锁问题怎么解决-你项目中有没有遇到死锁现象-怎么优化处理的-讲一下思路。" tabindex="-1">数据库死锁问题怎么解决？你项目中有没有遇到死锁现象，怎么优化处理的，讲一下思路。 <a class="header-anchor" href="#数据库死锁问题怎么解决-你项目中有没有遇到死锁现象-怎么优化处理的-讲一下思路。" aria-label="Permalink to &quot;数据库死锁问题怎么解决？你项目中有没有遇到死锁现象，怎么优化处理的，讲一下思路。&quot;">​</a></h4><p>排查：一般可以通过 SQL语句或者监控平台看到死锁现象，一般是资源争夺或者资源等待的问题，比如同时更新某一行等，事务长时间不释放锁，其他事务进行等待，也会导致死锁的现象。</p><p>解决：</p><ul><li>手动干预 <ul><li>手动终止一个或多个导致死锁的事务，使其他事务可以继续执行。可以使用数据库管理工具或命令终止事务</li></ul></li><li>自动处理 <ul><li>大多数现代数据库系统可以自动检测到死锁，并选择一个事务进行回滚以解除死锁。例如，MySQL 的 InnoDB 引擎会自动回滚最小的事务</li></ul></li></ul><p>优化建议：</p><ul><li>建议一些长事务，可以将它改为多个短事务去执行，避免事务一直没执行完，下一个事务又来了，导致死锁等待</li><li>使用数据库特性 <ul><li><strong>使用悲观锁和乐观锁</strong>：根据业务场景选择适合的锁策略，悲观锁确保严格的并发控制，而乐观锁则适用于减少锁冲突的场景。</li><li><strong>设置死锁检测和超时时间</strong>：配置数据库的死锁检测和锁等待超时时间，确保死锁能及时被检测和处理。</li></ul></li></ul><hr><h4 id="间隙锁" tabindex="-1">间隙锁 <a class="header-anchor" href="#间隙锁" aria-label="Permalink to &quot;间隙锁&quot;">​</a></h4><p>间隙锁主要是在索引记录之间的间隙加锁，从而保证某个间隙内的数据在锁定情况下不会发生任何变化</p><h4 id="多大的数据量建议分表-你们项目中分表策略是怎么做的。" tabindex="-1">多大的数据量建议分表，你们项目中分表策略是怎么做的。 <a class="header-anchor" href="#多大的数据量建议分表-你们项目中分表策略是怎么做的。" aria-label="Permalink to &quot;多大的数据量建议分表，你们项目中分表策略是怎么做的。&quot;">​</a></h4><p>这个行数其实并不是一定的，而是要结合实际的表字段大小，然后看实际的一个预估。我个人感觉还是看业务反馈，实际像这种如果收益不是很大的话，其实并不是那么有必要做。</p><h4 id="日志" tabindex="-1">日志 <a class="header-anchor" href="#日志" aria-label="Permalink to &quot;日志&quot;">​</a></h4><ul><li>undolog <ul><li>数据的快照⽇志，可以⽤于数据回滚</li><li>基于MVCC机制实现，通过创建多个版本的数据，从⽽使并发事务 互不影响，对于每个事务都会对应⾃⼰的版本链，读写操作都是 基于各⾃的版本去进⾏</li><li>undo log innerdb 储存引擎层面的日志，提供回滚和多版本并发控制下的读(MVCC)；</li></ul></li><li>redolog <ul><li>InnoDB级别的，主要⽤于BufferPool数据恢复的</li><li>redo log 数据备份和数据提交</li></ul></li><li>binlog <ul><li>会记录所有操作的⽇志，可⽤于数据归档</li><li>binlog 是 MySQ 服务层维护的一种二进制日志，主要做主从复制、数据恢复和备份</li></ul></li></ul><h4 id="redo-log-与-binlog-的区别" tabindex="-1">redo log 与 binlog 的区别 <a class="header-anchor" href="#redo-log-与-binlog-的区别" aria-label="Permalink to &quot;redo log 与 binlog 的区别&quot;">​</a></h4><ul><li>redo log 是在 InnoDB 存储引擎层产生，而 binlog 是 MySQL 数据库的上层产生的</li><li>写入磁盘的时间点不同，binlog 在事务提交完成后进行一次写入。而 redo log 在事务进行中不断地被写入</li><li>binlog 在写满或者重启之后，会生成新的 binlog 文件，redo log 是循环使用</li></ul><h4 id="正常我们使用-orm-框架-从-orm-框架-到-sql-执行的这个过程你了解多少。" tabindex="-1">正常我们使用 ORM 框架，从 ORM 框架 到 SQL 执行的这个过程你了解多少。 <a class="header-anchor" href="#正常我们使用-orm-框架-从-orm-框架-到-sql-执行的这个过程你了解多少。" aria-label="Permalink to &quot;正常我们使用 ORM 框架，从 ORM  框架 到 SQL 执行的这个过程你了解多少。&quot;">​</a></h4><ul><li>实体类映射</li><li>会话工厂</li><li>持久化操作</li><li>生成执行操作</li></ul><h4 id="高并发场景下-我们如何调优" tabindex="-1">高并发场景下，我们如何调优？ <a class="header-anchor" href="#高并发场景下-我们如何调优" aria-label="Permalink to &quot;高并发场景下，我们如何调优？&quot;">​</a></h4><p>参考来源1： <a href="https://www.bilibili.com/video/BV1yr421G7Lw" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1yr421G7Lw</a></p><ul><li>是否要考虑切换存储引擎 <ul><li>视频中是建议可以考虑 mysiam 引擎，不过弹幕中提到：备份方面的操作不好，</li><li>AI回答： MyISAM 的锁机制：它只支持<strong>表级锁</strong>。这意味着，任何一个写操作（INSERT/UPDATE/DELETE）都会锁住整张表，阻塞其他所有读写请求。在写操作频繁的场景下，这会导致严重的排队和性能瓶颈，并发能力极低。此外，MyISAM 不支持事务，且崩溃后数据损坏风险高、难以安全恢复</li><li><strong>在现代 MySQL（5.5+ 默认 InnoDB）中，对于高并发、有数据一致性要求的业务，基本不应再考虑 MyISAM</strong></li></ul></li><li>隔离级别的切换 <ul><li>隔离级别可以选择PC，而不是非要PR。</li><li>从默认的 RR（可重复读）切换到 RC（读已提交），核心目的正是为了<strong>提升并发写入性能</strong>。</li><li>关键原因在于<strong>间隙锁（Gap Lock）</strong>。RR 级别为了防止幻读，会使用间隙锁锁住索引记录之间的空隙，这在高并发下会阻塞其他事务的插入操作，增加死锁风险。而 RC 级别下<strong>间隙锁通常会失效</strong>，仅保留行锁，锁的范围更小，冲突概率更低，因此并发写入性能更高，死锁风险也更低。</li><li>RC 的代价是可能出现“不可重复读”和“幻读”，但这在许多互联网业务（如社交、电商浏览）中是可以接受的。</li></ul></li><li>连接数配置</li><li>创建表</li><li>索引，区分度好，避免失效（optimizer trace 索引）</li><li>缓存 <ul><li>一般指 添加 Redis 组件</li></ul></li><li>异步化 <ul><li>引入MQ，将业务的频率削峰降低</li></ul></li><li>分库分表，周期冷热分离</li></ul><h3 id="redis" tabindex="-1">Redis <a class="header-anchor" href="#redis" aria-label="Permalink to &quot;Redis&quot;">​</a></h3><h4 id="将数据库用户表的信息存入到缓存中-建议使用什么数据结构" tabindex="-1">将数据库用户表的信息存入到缓存中，建议使用什么数据结构 <a class="header-anchor" href="#将数据库用户表的信息存入到缓存中-建议使用什么数据结构" aria-label="Permalink to &quot;将数据库用户表的信息存入到缓存中，建议使用什么数据结构&quot;">​</a></h4><p>一般使用 Hash 就可以了，如果数据量少的话；</p><p>数据量多的时候需要考虑通过哈希或者其他方式将数据分散存入到多个 Key 中</p><p>如果是存入一些用户信息，比如用户相关联的信息，一对多的时候，可以考虑 List 或者 Set 存入</p><h4 id="redis-的一些常用命令" tabindex="-1">Redis 的一些常用命令 <a class="header-anchor" href="#redis-的一些常用命令" aria-label="Permalink to &quot;Redis 的一些常用命令&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#Key 操作</span></span>
<span class="line"><span>#设置键的值</span></span>
<span class="line"><span>SET key value</span></span>
<span class="line"><span>#获取键的值</span></span>
<span class="line"><span>GET key</span></span>
<span class="line"><span>#删除键</span></span>
<span class="line"><span>DEL key</span></span>
<span class="line"><span>#设置键的过期时间</span></span>
<span class="line"><span>EXPIRE key seconds</span></span>
<span class="line"><span>#获取键的数据类型</span></span>
<span class="line"><span>TYPE key</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#String 操作</span></span>
<span class="line"><span>#设置键的值，并设置过期时间</span></span>
<span class="line"><span>SETEX key seconds value</span></span>
<span class="line"><span>#追加字符串到现有键值</span></span>
<span class="line"><span>APPEND key value</span></span>
<span class="line"><span>#获取字符串长度</span></span>
<span class="line"><span>STRLEN key</span></span>
<span class="line"><span>#设置并返回键的旧值</span></span>
<span class="line"><span>GETSET key value</span></span>
<span class="line"><span>#批量设置多个键值对</span></span>
<span class="line"><span>MSET key1 value1 key2 value2</span></span>
<span class="line"><span>#批量获取多个键值</span></span>
<span class="line"><span>MGET key1 key2</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#Hash 操作</span></span>
<span class="line"><span>HSET key field value                #设置哈希字段的值</span></span>
<span class="line"><span>HGET key field                #获取哈希字段的值</span></span>
<span class="line"><span>HDEL key field1 field2                #删除一个或多个哈希字段</span></span>
<span class="line"><span>HGETALL key                #获取哈希中的所有字段和值</span></span>
<span class="line"><span>HKEYS key                #获取哈希中的所有字段</span></span>
<span class="line"><span>HVALS key                #获取哈希中的所有值</span></span>
<span class="line"><span>HEXISTS key field                #判断哈希字段是否存在</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#List 操作</span></span>
<span class="line"><span>LPUSH key value1 value2                #从列表左端推入元素</span></span>
<span class="line"><span>RPUSH key value1 value2                #从列表右端推入元素</span></span>
<span class="line"><span>LPOP key                #从列表左端弹出元素</span></span>
<span class="line"><span>RPOP key                #从列表右端弹出元素</span></span>
<span class="line"><span>LLEN key                #获取列表长度</span></span>
<span class="line"><span>LRANGE key start stop                #获取列表中指定范围的元素</span></span>
<span class="line"><span>LREM key count value                #移除列表中等于 value 的元素</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#Set 操作</span></span>
<span class="line"><span>SADD key member1 member2                #向集合添加一个或多个元素</span></span>
<span class="line"><span>SREM key member1 member2                #移除集合中的一个或多个元素</span></span>
<span class="line"><span>SISMEMBER key member                #检查集合中是否包含指定元素</span></span>
<span class="line"><span>SMEMBERS key                #获取集合中的所有元素</span></span>
<span class="line"><span>SCARD key                #获取集合的元素个数</span></span>
<span class="line"><span>SRANDMEMBER key                #随机返回集合中的一个元素</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Sorted Set 操作</span></span>
<span class="line"><span>ZADD key score1 member1 score2 member2                #向有序集合添加元素及其分数</span></span>
<span class="line"><span>ZRANGE key start stop                #获取有序集合中指定范围内的元素(按分数升序）</span></span>
<span class="line"><span>ZREVRANGE key start stop                #获取有序集合中指定范围内的元素（按分数降序）</span></span>
<span class="line"><span>ZRANGEBYSCORE key min max                #按分数范围获取有序集合中的元素</span></span>
<span class="line"><span>ZREM key member1 member2                #移除有序集合中的一个或多个元素</span></span>
<span class="line"><span>ZCARD key                 #获取有序集合中的元素个数</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#事务操作</span></span>
<span class="line"><span>MULTI                  #开始事务</span></span>
<span class="line"><span>EXEC                #执行事务</span></span>
<span class="line"><span>DISCARD                #放弃事务</span></span></code></pre></div><h4 id="更新-hash-中某个-field-值的数据" tabindex="-1">更新 hash 中某个 field 值的数据 <a class="header-anchor" href="#更新-hash-中某个-field-值的数据" aria-label="Permalink to &quot;更新 hash 中某个 field 值的数据&quot;">​</a></h4><ol><li><strong>增加用户信息</strong>：使用 <code>HSET key field value</code> 将用户对象序列化后存储到 Redis 哈希表中。</li><li><strong>查询用户信息</strong>：使用 <code>HGET key field</code> 根据用户ID查询对应的值，并反序列化为用户对象。</li><li><strong>更新用户信息</strong>：再次使用 <code>HSET key field value</code> 更新用户信息。</li><li><strong>删除用户信息</strong>：使用 <code>HDEL key field</code> 删除指定用户ID的信息。</li><li><strong>获取所有用户信息</strong>：使用 <code>HGETALL key</code> 获取哈希表中的所有字段和值。</li><li><strong>获取所有用户ID</strong>：使用 <code>HKEYS key</code> 获取哈希表中的所有字段。</li><li><strong>获取所有用户对象</strong>：使用 <code>HVALS key</code> 获取哈希表中的所有值。</li><li><strong>判断用户是否存在</strong>：使用 <code>HEXISTS key field</code> 判断哈希字段是否存在</li></ol><h4 id="常用的缓存读写策略" tabindex="-1">常用的缓存读写策略 <a class="header-anchor" href="#常用的缓存读写策略" aria-label="Permalink to &quot;常用的缓存读写策略&quot;">​</a></h4><p>缓存常用的三种读写策略：Cache Aside Pattern（旁路缓存模式）、Read/Write Through Pattern（读写穿透）、Write Behind Pattern（异步缓存写入）</p><ul><li>常用的缓存读写策略 <ul><li>Cache Aside Pattern（旁路缓存模式） <ul><li>读 <ul><li>从 cache 中读取数据，读取到就直接返回</li><li>cache 中读取不到的话，就从 db 中读取数据返回</li><li>再把数据放到 cache 中。</li></ul></li><li>写 <ul><li>先更新 db</li><li>然后直接删除 cache</li></ul></li></ul></li><li>Read/Write Through Pattern（读写穿透） <ul><li>读 <ul><li>从 cache 中读取数据，读取到就直接返回 。</li><li>读取不到的话，先从 db 加载，写入到 cache 后返回响应。</li></ul></li><li>写 <ul><li>先查 cache，cache 中不存在，直接更新 db。</li><li>cache 中存在，则先更新 cache，然后 cache 服务自己更新 db（<strong>同步更新 cache 和 db</strong>）。</li></ul></li></ul></li><li>Write Behind Pattern（异步缓存写入） <ul><li>读</li><li>写 <ul><li>**Read/Write Through 是同步更新 cache 和 db，</li><li>Write Behind 则是只更新缓存，不直接更新 db，而是改为异步批量的方式来更新 db</li></ul></li></ul></li></ul></li></ul><h4 id="内存淘汰策略有哪些" tabindex="-1">内存淘汰策略有哪些 <a class="header-anchor" href="#内存淘汰策略有哪些" aria-label="Permalink to &quot;内存淘汰策略有哪些&quot;">​</a></h4><p>数据的淘汰策略：当Redis中的内存不够用时，此时在向Redisr中添加新的key,那么Redis 就会按照某一种规则将内存中的数据删除掉，这种数据的删除规则被称之为内存的淘汰策略。</p><ul><li>默认策略noeviction，当内存不⾜以容纳新写⼊数据时，新写⼊操作 会报错</li><li>针对设置过期时间的key <ul><li>volatile-lru，按照LRU算法删除</li><li>volatile-lfu，按照LFU算法删除</li><li>volatile-radom，随机删除</li><li>volatile-ttl，按过期时间顺序删除</li></ul></li><li>针对所有key <ul><li>allkeys-random，随机删除</li><li>allkeys-lru，按照LRU算法删除</li><li>allkeys-lfu，按照LFU算法删除</li></ul></li></ul><h4 id="缓存加载和更新策略" tabindex="-1">缓存加载和更新策略 <a class="header-anchor" href="#缓存加载和更新策略" aria-label="Permalink to &quot;缓存加载和更新策略&quot;">​</a></h4><ul><li>缓存加载 <ul><li>预加载（Cache Warming）</li><li>惰性加载（Lazy Loading）</li><li>定时加载（Scheduled Loading）</li></ul></li><li>缓存更新 <ul><li>过期时间（TTL）</li><li>写通（Write Through） <ul><li>在更新数据源的同时，也同步更新缓存</li></ul></li><li>写回（Write Back / Write Behind） <ul><li>首先更新缓存，然后异步地将数据更新到数据源</li></ul></li><li>失效（Cache Invalidation） <ul><li>在数据源更新后，立即使缓存中的对应数据失效</li><li>当数据源更新时，删除缓存中的旧数据。</li></ul></li></ul></li></ul><p>这里讲一下一般什么情况下会使用定时加载，一般来说我们会使用旁路缓存模式，比如先读缓存，如果缓存没有再读数据库，这里可以避免减少数据的负担，可以通过定时操作，先进行定时刷写到缓存中，避免读数据的时候再往数据库中查。</p><p>这里定时加载并不需要说每次全部更新缓存数据，你也可以设置修改数据库的时候同时更新缓存的数据，然后定时的时候再将数据库中有的数据而缓存中没有的数据，放入到缓存中。</p><h4 id="redis-在你项目中是怎么使用的" tabindex="-1">Redis 在你项目中是怎么使用的 <a class="header-anchor" href="#redis-在你项目中是怎么使用的" aria-label="Permalink to &quot;Redis 在你项目中是怎么使用的&quot;">​</a></h4><p>讲一下 Redis 的用法</p><p>缓冲、分布式锁</p><p>缓冲 → Jwt</p><h4 id="常用的缓存读写策略-1" tabindex="-1">常用的缓存读写策略 <a class="header-anchor" href="#常用的缓存读写策略-1" aria-label="Permalink to &quot;常用的缓存读写策略&quot;">​</a></h4><p>缓存常用的三种读写策略：Cache Aside Pattern（旁路缓存模式）、Read/Write Through Pattern（读写穿透）、Write Behind Pattern（异步缓存写入）</p><h4 id="讲一下-redis-事务" tabindex="-1">讲一下 Redis 事务 <a class="header-anchor" href="#讲一下-redis-事务" aria-label="Permalink to &quot;讲一下 Redis 事务&quot;">​</a></h4><p>不是很推荐使用Redis事务，跟我们常见的关系型数据库事务不同：</p><ul><li>1、Redis 事务是不支持回滚（roll back）操作的，Redis 事务不满足原子性。</li><li>2、Redis 事务的持久性是没办法保证的</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202402261559889.png" alt="image.png"></p><blockquote><p>Lua 脚本</p></blockquote><p>与事务相对的话，更推荐使用 Lua 脚本执行批量任务；</p><ul><li>一段 Lua 脚本可以视作一条命令执行，一段 Lua 脚本执行过程中不会有其他脚本或 Redis 命令同时执行，保证了操作不会被其他指令插入或打扰。</li></ul><p>不过，如果 Lua 脚本运行时出错并中途结束，出错之后的命令是不会被执行的。并且，出错之前执行的命令是无法被撤销的，无法实现类似关系型数据库执行失败可以回滚的那种原子性效果。因此， <strong>严格来说的话，通过 Lua 脚本来批量执行 Redis 命令实际也是不完全满足原子性的。</strong></p><hr><p>Redis的Lua脚本功能是其强大特性之一，提供了在Redis服务器端执行脚本的能力。这允许执行一系列操作，这些操作作为一个整体原子地执行，而不是由客户端逐一发送命令然后由服务器逐一执行。</p><p>Lua是一种轻量级的编程语言，被嵌入到Redis中用于执行复杂的逻辑，这在多个命令需要作为单个原子操作执行时特别有用。</p><blockquote><p>使用示例：</p></blockquote><p>假设我们需要更新一个计数器，但只有在另一个键存在时才进行更新。不使用Lua脚本，我们可能需要先检查键是否存在，然后再更新计数器，这两步操作不能保证原子性。</p><p>使用Lua脚本，我们可以这样做：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>if redis.call(&quot;EXISTS&quot;, KEYS[1]) == 1 then</span></span>
<span class="line"><span>    return redis.call(&quot;INCR&quot;, KEYS[2])</span></span>
<span class="line"><span>else</span></span>
<span class="line"><span>    return 0</span></span>
<span class="line"><span>end</span></span></code></pre></div><ul><li>这个脚本接受两个键作为输入：<code>KEYS[1]</code>用于检查存在性，<code>KEYS[2]</code>是需要增加的计数器。如果<code>KEYS[1]</code>存在，脚本将增加<code>KEYS[2]</code>的值并返回新值；如果不存在，返回0。</li></ul><p>执行脚本操作(使用<code>EVAL</code>命令执行Lua脚本)：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>EVAL &lt;script&gt; &lt;numkeys&gt; &lt;key&gt; [&lt;key2&gt; ...] [&lt;arg&gt; [&lt;arg2&gt; ...]]</span></span></code></pre></div><ul><li><code>&lt;script&gt;</code>：Lua脚本文本。</li><li><code>&lt;numkeys&gt;</code>：脚本中将要处理的键的数量。</li><li><code>&lt;key&gt;</code>：脚本中用到的Redis键。</li><li><code>&lt;arg&gt;</code>：传递给脚本的其他参数。</li></ul><h4 id="redis-的常用命令" tabindex="-1">Redis 的常用命令 <a class="header-anchor" href="#redis-的常用命令" aria-label="Permalink to &quot;Redis 的常用命令&quot;">​</a></h4><h4 id="配置项" tabindex="-1">配置项 <a class="header-anchor" href="#配置项" aria-label="Permalink to &quot;配置项&quot;">​</a></h4><ul><li><strong><code>maxmemory</code></strong>: 设置 Redis 使用的最大内存量。</li><li><strong><code>maxmemory-policy</code></strong>: 定义当内存达到上限时 Redis 的行为策略（淘汰策略）</li><li><strong><code>appendonly</code></strong>: 是否启用 AOF（Append Only File）持久化。</li><li><strong><code>appendfsync</code></strong>: 设置 AOF 持久化的同步策略。</li><li><strong><code>save</code></strong>: 设置 RDB 快照的触发条件，格式为 <code>seconds_to_elapsed changes_to_record</code>。</li><li><strong><code>cluster-enabled</code></strong>: 是否启用 Redis 集群模式。</li></ul><h4 id="redis-常见的数据结构" tabindex="-1">Redis 常见的数据结构 <a class="header-anchor" href="#redis-常见的数据结构" aria-label="Permalink to &quot;Redis 常见的数据结构&quot;">​</a></h4><ul><li>String <ul><li>string 主要是⽤来存储字符串，底层是基于 动态字符串sds 实 现的，sds 通过动态调整⻓度来节省内存</li><li>应⽤场景 <ul><li>分布式session</li><li>分布式锁</li></ul></li><li>常用指令： <ul><li>set、get、setnx、setex ..</li></ul></li></ul></li><li>hash <ul><li>hash 类似于 Map，底层采⽤两种⽅式来实现，当数据量较少 并且元素占⽤内存少(⼩整数或短字符串)时，采⽤ ziplist(压缩 列表)，反之采⽤ hashtable(哈希表)，两种⽅式都是为了节省 内存 <ul><li>ziplist 是⼀个连续的内存空间，通过紧凑的存储来节省空 间</li><li>hashtable 是基于dict(字典)实现，采⽤拉链法解决hash冲 突</li></ul></li><li>应用场景 <ul><li>实现购物⻋</li></ul></li><li>常用指令 <ul><li>hset、hget、hgetall、hdel、hincrby ..</li></ul></li></ul></li><li>list <ul><li>list 是⼀个有序可重复集合，底层采⽤两种⽅式实现，当数据 量较少并且元素占⽤内存少(⼩整数或短字符串)时，采⽤ ziplist(压缩列表)，反之采⽤ quicklist(快速列表)，两种⽅式都 是为了节省内存 <ul><li>ziplist 是⼀个连续的内存空间，通过紧凑的存储来节省空 间</li><li>quicklist 是基于 ziplist 和 双向链表 实现的，可以在节省空 间的同时保证⾼效增删</li></ul></li><li>应用场景 <ul><li>栈(lpush + lpop)</li><li>队列(lpush + rpop)</li><li>阻塞队列(lpush + brpop)</li><li>发布订阅</li></ul></li><li>常用指令 <ul><li>lpush、lpop、rpush、rpop、blpop、brpop、lrange ..</li></ul></li></ul></li><li>set <ul><li>set 是⼀个⽆序不可重复集合，底层采⽤两种⽅式实现，当数 据量较少且元素为整数时，采⽤ intset(整数集合)，反之采⽤ hashtable(哈希表)，两种⽅式都是为了节省内存 <ul><li>intset 是⼀个有序的整数数组，通过紧凑的存储来节省空 间</li><li>hashtable 是基于dict(字典)实现，采⽤拉链法解决hash冲 突</li></ul></li><li>应用场景 <ul><li>抽奖(srandmember)</li><li>点赞收藏关注(sadd)</li><li>共同关注(sinter)</li><li>可能认识的⼈(sdiff)</li></ul></li><li>常用指令 <ul><li>sadd、srem、smembers、scard、srandmember、 sismember、spop、sinter、sunion、sdiff、sinterstore、 sdiffstore</li></ul></li></ul></li><li>zset(sorted set) <ul><li>zset 是⼀个有序不可重复集合，底层采⽤两种⽅式实现，当数 据量较少并且元素占⽤内存少(⼩整数或短字符串)，采⽤ ziplist(压缩列表)，反之采⽤skiplist(跳表) + dict(字典)，两种 ⽅式都是为了节省内存，另外skiplist主要是为了提升score查 询效率 <ul><li>ziplist 是⼀个连续的内存空间，通过紧凑的存储来节省空 间</li><li>skiplist 是⼀个有序链表配上多级索引，通过多级索引位置 的跳转来实现快速查找元素，主要⽤于按照分值对元素进 ⾏排序，同样也⽀持范围查询 <ul><li>跳表如何定位元素 <ul><li>每隔⼀个元素建⽴⼀个索引，通过建⽴多个索引， 利⽤⼀次索引定位到需要查询的元素，如果觉得 慢，可以在⼀级索引的基础上建⽴⼆级索引，依次 类推，在多级索引之间来回转跳实现快速定位，当 数据量特别⼤的时候，查找时间复杂度为O(logN)， 因为它本身的思想就类似⼆分查找</li></ul></li></ul></li></ul></li><li>应用场景 <ul><li>排⾏榜(zrange/zreverange/zunionscore)</li></ul></li><li>常用指令 <ul><li>zadd、zrem、zsore、zincrby、zrange、zreverange、 zrangebyscore、zreverangescore、zunionscore、 zinterscore</li></ul></li></ul></li><li>bitmap <ul><li>bitmap是⼀个位图</li><li>应⽤场景 <ul><li>⽉打卡、⽉活跃 <ul><li>⽉打卡可以通过将 当前第⼏天 作为 偏移量，如果打卡 对应的位置为1，反之为0</li></ul></li><li>布隆过滤器</li></ul></li></ul></li><li>stream <ul><li>stream 是参考kafka设计的消息队列，⽀持持久化，适合⼩基 数的消息队列场景</li></ul></li></ul><h4 id="string-数据类型在项目中的实际使用" tabindex="-1">String 数据类型在项目中的实际使用 <a class="header-anchor" href="#string-数据类型在项目中的实际使用" aria-label="Permalink to &quot;String 数据类型在项目中的实际使用&quot;">​</a></h4><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240311220409.png" alt="image.png"></p><h4 id="zset-为什么使用跳表" tabindex="-1">ZSet 为什么使用跳表 <a class="header-anchor" href="#zset-为什么使用跳表" aria-label="Permalink to &quot;ZSet 为什么使用跳表&quot;">​</a></h4><h4 id="谈一下布隆过滤器" tabindex="-1">谈一下布隆过滤器 <a class="header-anchor" href="#谈一下布隆过滤器" aria-label="Permalink to &quot;谈一下布隆过滤器&quot;">​</a></h4><p>布隆过滤器 是基于bitmap实现的，主要⽤于粗略的数据过滤</p><ul><li>添加数据时，经过hash运算得到对应的 bit位，将该 bit位 置为1 <ul><li>bit位为1 表示可能存在</li><li>bit位为0 表示⼀定不存在</li></ul></li></ul><h4 id="redis-字符串最大不能超过多少" tabindex="-1">Redis 字符串最大不能超过多少 <a class="header-anchor" href="#redis-字符串最大不能超过多少" aria-label="Permalink to &quot;Redis 字符串最大不能超过多少&quot;">​</a></h4><p>512 MB</p><h4 id="讲一下-redis-持久化-🚩" tabindex="-1">讲一下 Redis 持久化 🚩 <a class="header-anchor" href="#讲一下-redis-持久化-🚩" aria-label="Permalink to &quot;讲一下 Redis 持久化  🚩&quot;">​</a></h4><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240312171845.png" alt="image.png"></p><h4 id="redis-为什么这么快-🚩" tabindex="-1">Redis 为什么这么快 🚩 <a class="header-anchor" href="#redis-为什么这么快-🚩" aria-label="Permalink to &quot;Redis 为什么这么快  🚩&quot;">​</a></h4><ul><li>1、主要还是基于内存操作</li><li>2、是单线程的，避免了不必要的上下文切换可竞争条件，多线程需要考虑线程安全问题</li><li>3、使用 IO 多路复用模型，非阻塞 IO</li><li>4、Redis 的每种数据结构进行了优化处理</li></ul><h4 id="什么是-io-多路复用" tabindex="-1">什么是 IO 多路复用 <a class="header-anchor" href="#什么是-io-多路复用" aria-label="Permalink to &quot;什么是 IO 多路复用&quot;">​</a></h4><p>Rdis是纯内存操作，执行速度非常快，它的性能瓶颈是网络延迟而不是执行速度，</p><p>I/O多路复用模型主要就是实现了高效的网络请求</p><ul><li>用户空间和内核空间</li><li>常见的 IO 模型 <ul><li>阻塞IO(Blocking IO)</li><li>非阻塞IO(Nonblocking IO)</li><li>IO多路复用(IO Multiplexing)</li></ul></li><li>Redis网络模型</li></ul><p>阻塞IO 是常见 的IO 操作模型，但是它实际的效率并不是很高；用户态在内核读取数据和从内核拷贝到用户缓冲区的两个阶段都需要等待阻塞运行。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240317144125.png" alt="image.png"></p><p>非阻塞IO，在内核态读取这一阶段，用户阶段并不会持续阻塞等待，而是自旋询问是否数据准备就绪，如果未就绪，就循环尝试读取。</p><p>阶段二仍然会被阻塞，但由于忙等机制实际效率并没有提高很多。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240317144427.png" alt="image.png"></p><p>IO 多路复用</p><p>监听了多个 socker，并且其中只要有一个 socket 就绪，就可以进行系统调用 recvfrom</p><p>和前者最大的区别是：非阻塞 iO 或者 阻塞 IO 需要等待它目前在读取的 socket 数据准备就绪才可以下一步操作（而实际上可能它后面的 socket 是已经准备就绪了）</p><p>通过这个监听机制，可以有效提高效率</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240317145015.png" alt="image.png"></p><p>常见 的 IO 多路复用模式有： select、poll、epoll；</p><p>然后前两个的机制：select 和 poll 会有一个监听，然后只是监听里面有没有就绪的，如果有，遍历逐个来判断； 而 epoll 机制能够精确定位到具体是哪一个，而不用遍历。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240317145752.png" alt="image.png"></p><p>Reids 网络模型：IO多路复用 + 事件派发机制</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240317150021.png" alt="image.png"></p><h4 id="redis-为什么要引入多线程" tabindex="-1">Redis 为什么要引入多线程 <a class="header-anchor" href="#redis-为什么要引入多线程" aria-label="Permalink to &quot;Redis 为什么要引入多线程&quot;">​</a></h4><p>影响效率最大的是 网络 IO</p><p>Redis 多线程 在命令回复处理器和 接受参数数据，转换Redis 命令 （网络IO 方面的内容）进行了优化（加入了多线程）</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240317150227.png" alt="image.png"></p><ul><li>Redis引⼊多线程主要想发挥多核处理器的能⼒，处理在⼤数据量下 ⽹络IO读写速度慢的问题，但是指令的执⾏依旧采⽤的是单线程</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240317150349.png" alt="image.png"></p><p>面试官：Redis是单线程的，但是为什么还那么快？</p><p>候选人：</p><p>嗯，这个有几个原因吧~~~ 1、完全基于内存的，C语言编写 2、采用单线程，避免不必要的上下文切换可竞争条件 3、使用多路1/0复用模型，非阻塞I0</p><p>例如：bgsave和bgrewriteaof都是在后台执行操作，不影响主线程的正常使用，不会产生阻塞</p><p>面试官：能解释一下1/O多路复用模型？</p><p>候选人：嗯~，I/O多路复用是指利用单个线程来同时监听多个Socket,并在某个Socketi可读、可写时 得到通知，从而避免无效的等待，充分利用CPU资源。目前的1/O多路复用都是采用的epo模式实现， 它会在通知用户进程Socket就绪的同时，把己就绪的Socket写入用户空间，不需要挨个遍历Socket来判 断是否就绪，提升了性能。 其中Redis的网络模型就是使用I/O多路复用结合事件的处理器来应对多个Socketi请求，比如，提供了连 接应答处理器、命令回复处理器，命令请求处理器： 在Redis6.0之后，为了提升更好的性能，在命令回复处理器使用了多线程来处理回复事件，在命令请求 处理器中，将命令的转换使用了多线程，增加命令转换速度，在命令执行的时候，依然是单线程</p><h4 id="讲一下-redis-的-reactor-模型" tabindex="-1">讲一下 Redis 的 Reactor 模型 <a class="header-anchor" href="#讲一下-redis-的-reactor-模型" aria-label="Permalink to &quot;讲一下 Redis 的 Reactor 模型&quot;">​</a></h4><h4 id="redis-的过期策略" tabindex="-1">Redis 的过期策略 <a class="header-anchor" href="#redis-的过期策略" aria-label="Permalink to &quot;Redis 的过期策略&quot;">​</a></h4><ul><li>定时过期：每个设置过期时间的 key 都需要创建一个定时器， 到过期时间就会立即对 key 进行清除</li><li>惰性过期：只有当访问一个 key 时，才会判断该 key 是否已过 期，过期则清除</li><li>定期过期：每隔一定的时间，会扫描一定数量的数据库的 expires 字典中一定数量的 key，并清除其中已过期的 ke</li></ul><h4 id="过期键的删除策略-🚩" tabindex="-1">过期键的删除策略 🚩 <a class="header-anchor" href="#过期键的删除策略-🚩" aria-label="Permalink to &quot;过期键的删除策略  🚩&quot;">​</a></h4><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240312184918.png" alt="image.png"></p><p>假如redis的 key 过期之后，会立即删除吗？ set name heima 10</p><ul><li>Redis 对数据设置数据的有效时间，数据过期以后，就需要将数据从内存中删除掉。</li><li>可以按照不同的规则进行删除，这种删除规则就被称之为数据的删除策略（数据过期策略）。</li></ul><p>常见的过期策略</p><ul><li>惰性删除 <ul><li>只有当访问一个key的时候，才会判断的当前key是否已过期，已过期就会删除</li><li>这个策略可以节省CPU资源，但是占用内存，可能因为大量的key不被再次访问，导致一直不清除从而占用内存</li></ul></li><li>定期删除 <ul><li>每隔一段时间会扫描一定数量的过期key,并且清除已过期的key。</li><li>这个策略属于折中方案，可以有效的平衡CPU资源以及内存资源</li><li>定期清理有两种模式： <ul><li>SLOW 模式是定时任务，执行频率默认为10hz,每次不超过25ms,以通过修改配置文件redis.conf的hz选项来调整这个次数</li><li>FAST 模式执行频率不固定，但两次间隔不低于2ms,每次耗时不超过1ms</li></ul></li></ul></li><li>强制删除 <ul><li>当已使用内存超过Redis:最大允许内存，会触发内存淘汰策略</li></ul></li><li>Redis中<strong>同时使用了惰性删除和定期删除</strong></li></ul><h4 id="内存淘汰策略有哪些-1" tabindex="-1">内存淘汰策略有哪些 <a class="header-anchor" href="#内存淘汰策略有哪些-1" aria-label="Permalink to &quot;内存淘汰策略有哪些&quot;">​</a></h4><p>数据的淘汰策略：当Redis中的内存不够用时，此时在向Redisr中添加新的key,那么Redis 就会按照某一种规则将内存中的数据删除掉，这种数据的删除规则被称之为内存的淘汰策略。</p><ul><li>默认策略noeviction，当内存不⾜以容纳新写⼊数据时，新写⼊操作 会报错</li><li>针对设置过期时间的key <ul><li>volatile-lru，按照LRU算法删除</li><li>volatile-lfu，按照LFU算法删除</li><li>volatile-radom，随机删除</li><li>volatile-ttl，按过期时间顺序删除</li></ul></li><li>针对所有key <ul><li>allkeys-random，随机删除</li><li>allkeys-lru，按照LRU算法删除</li><li>allkeys-lfu，按照LFU算法删除</li></ul></li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240312171303.png" alt="image.png"></p><p>关于数据淘汰策略其他的面试问题</p><ul><li>1.数据库有1000万数据，Redis只能缓存20w数据，如何保证Redis 中的数据都是热点数据？ <ul><li>使用allkeys-lru(挑选最近最少使用的数据淘汰)淘汰策略，留下来的都是经常访问的热点数据</li></ul></li><li>2.Redis的内存用完了会发生什么？ <ul><li>主要看数据淘汰策略是什么？如果是默认的配置(noeviction),会直接报错</li></ul></li></ul><p>记忆点：</p><p>数据淘汰策略</p><ul><li>1.Redis提供了8种不同的数据淘汰策略，默认是 noeviction 不删除任何数据，内存不足直接报错</li><li>2.LRU: 最少最近使用。用当前时间减去最后一次访问时间，这个值越大则淘汰优先级越高。</li><li>3.LFU:最少频率使用。会统计每个key的访问频率，值越小淘汰优先级越高</li></ul><p>平时开发过程中用的比较多的就是allkeys-lru(结合自己的业务场景)</p><h4 id="redis-怎么实现高可用的" tabindex="-1">Redis 怎么实现高可用的 <a class="header-anchor" href="#redis-怎么实现高可用的" aria-label="Permalink to &quot;Redis 怎么实现高可用的&quot;">​</a></h4><h4 id="redisi主从复制-同步-原理" tabindex="-1">Redisi主从复制（同步）原理 <a class="header-anchor" href="#redisi主从复制-同步-原理" aria-label="Permalink to &quot;Redisi主从复制（同步）原理&quot;">​</a></h4><ul><li>通过 RDB 日志文件和偏移量操作</li></ul><p>全量同步操作</p><ul><li>1、从节点发起同步请求</li><li>2、主节点判断是否是第一次同步，如果是第一次，进行全量同步，如果不是，判断 数据集 replid 是否一致 <ul><li>是，第一次，会返回 master 的数据版本信息 replid、offset</li></ul></li><li>3、从节点会保存版本信息</li><li>4、主节点会生成 RDB 文件进行发送操作</li><li>5、从节点会清空本地数据，加载 RDB 文件</li><li>6、从节点加载过程会主节点会生成一个 repl_baklog 的文件（中间执行操作），并发送到从节点</li><li>7、从节点再进行加载进行同步</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240317151632.png" alt="image.png"></p><p>增量同步操作</p><ul><li>从 reol_baklog 获取数据发送到从节点</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240317152226.png" alt="image.png"></p><p>参考</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240317152304.png" alt="image.png"></p><h4 id="讲一下-哨兵选主过程" tabindex="-1">讲一下 哨兵选主过程 <a class="header-anchor" href="#讲一下-哨兵选主过程" aria-label="Permalink to &quot;讲一下 哨兵选主过程&quot;">​</a></h4><p>哨兵：高可用，提供监控范围和自动故障恢复与通知</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240317152413.png" alt="image.png"></p><ul><li>选取操作</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240317152506.png" alt="image.png"></p><p>哨兵模式中会遇到一个问题：脑裂问题</p><h4 id="讲一下-主从选举的脑裂问题" tabindex="-1">讲一下 主从选举的脑裂问题 <a class="header-anchor" href="#讲一下-主从选举的脑裂问题" aria-label="Permalink to &quot;讲一下 主从选举的脑裂问题&quot;">​</a></h4><p>集群脑裂是由于主节点和从节点和sentinel处于不同的网络分区，使得sentinel没有能够心跳感知到主节点，所以通过选举的方式提升了一个从节点为主，这样就存在了两个master,就像大脑分裂了一样，这样会导致客户端还在老的主节点那里写入数据，新节点无法同步数据，当网络恢复后，sentinel会将老的主节点降为从节点，这时再从新master 同步数据，就会导致数据丢失</p><p>解决：我们可以修改rds的配置，可以设置最少的从节点数量以及缩短主从数据同步的延迟时间，达不到要求就拒绝请求就可以避免大量的数据丢失。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240317152818.png" alt="image.png"></p><p>参考</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240317152938.png" alt="image.png"></p><h4 id="分片集群" tabindex="-1">分片集群 <a class="header-anchor" href="#分片集群" aria-label="Permalink to &quot;分片集群&quot;">​</a></h4><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240317153141.png" alt="image.png"></p><p>参考</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240317153308.png" alt="image.png"></p><h4 id="讲一下redis-cluster主从选举过程" tabindex="-1">讲一下Redis Cluster主从选举过程 <a class="header-anchor" href="#讲一下redis-cluster主从选举过程" aria-label="Permalink to &quot;讲一下Redis Cluster主从选举过程&quot;">​</a></h4><h4 id="数据一致性" tabindex="-1">数据一致性 <a class="header-anchor" href="#数据一致性" aria-label="Permalink to &quot;数据一致性&quot;">​</a></h4><ul><li>查询 <ul><li>当需要获取数据时，首先查询缓存。</li><li>如果缓存中有数据（缓存命中），则直接返回缓存中的数据。</li><li>如果缓存中没有数据（缓存未命中），则查询数据库，将查询结果存入缓存，并返回数据。</li><li>设置合理的缓存过期时间，以保证数据的时效性。</li></ul></li><li>更新 <ul><li>遇到写请求的时候是先更新数据库，再删除 cache</li></ul></li><li>删除 <ul><li>当数据需要被删除时，首先删除数据库中的数据。</li><li>然后删除缓存中对应的数据，保持数据库和缓存的一致性。</li></ul></li></ul><p>缓存读写策略一般选择使用旁路缓存模式</p><p>常用的缓存读写策略</p><ul><li>Cache Aside Pattern（旁路缓存模式） <ul><li>读 <ul><li>从 cache 中读取数据，读取到就直接返回</li><li>cache 中读取不到的话，就从 db 中读取数据返回</li><li>再把数据放到 cache 中。</li></ul></li><li>写 <ul><li>先更新 db，然后直接删除 cache</li></ul></li></ul></li><li>Read/Write Through Pattern（读写穿透） <ul><li>读 <ul><li>从 cache 中读取数据，读取到就直接返回 。</li><li>读取不到的话，先从 db 加载，写入到 cache 后返回响应。</li></ul></li><li>写 <ul><li>先查 cache，cache 中不存在，直接更新 db。</li><li>cache 中存在，则先更新 cache，然后 cache 服务自己更新 db（<strong>同步更新 cache 和 db</strong>）。</li></ul></li></ul></li><li>Write Behind Pattern（异步缓存写入） <ul><li>读</li><li>写 <ul><li>**Read/Write Through 是同步更新 cache 和 db，</li><li>Write Behind 则是只更新缓存，不直接更新 db，而是改为异步批量的方式来更新 db</li></ul></li></ul></li></ul><p>保持数据库和缓存数据一致性</p><ul><li>1、数据库中数据中全量刷写到缓存中，不设置失效时间 + 定时任务</li><li>2、保留热数据（都设置一个合理的过期时间）</li><li>3、旁路缓存模式 + <strong>保证删除操作非异常执行</strong>（MQ异步 + 订阅日志机制）</li></ul><h4 id="怎么保存缓存和数据库数据一致-数据一致性怎么保证" tabindex="-1">怎么保存缓存和数据库数据一致（数据一致性怎么保证） <a class="header-anchor" href="#怎么保存缓存和数据库数据一致-数据一致性怎么保证" aria-label="Permalink to &quot;怎么保存缓存和数据库数据一致（数据一致性怎么保证）&quot;">​</a></h4><p>延迟双删 + 定时刷新</p><p>策略</p><ul><li>1、数据库中数据中全量刷写到缓存中，不设置失效时间 + 定时任务</li><li>2、保留热数据</li></ul><p>旁路缓存模式 + 保证删除操作非异常执行（MQ异步 + 订阅日志机制）</p><p>思考：</p><ul><li>一旦我们决定使用缓存，那必然要面临一致性问题。性能和一致性就像天平的两端，无法做到都满足要求。</li><li>既然决定使用缓存，就必须容忍「一致性」问题，我们只能尽可能地去降低问题出现的概率。</li></ul><blockquote><p>缓存和数据库不一致</p></blockquote><p>一般是采用：Cache Aside Pattern（旁路缓存模式）: 遇到写请求的时候是先更新数据库，再删除 cache</p><p>这种情况下发生数据不一致的情况比较小，</p><p>在这种情况下，在数据库更新和缓存删除之间有读取请求，它也只会读到旧的数据，一旦缓存被删除，下一个读取请求将从数据库中获取最新的数据，并更新缓存，从而保持了一致性。</p><p>需要避免缓存和数据库不一致需要考虑的点：避免第二步操作【删除 cache】失败</p><p>解决方案：</p><ol><li>缓存失效时间变短（不推荐，治标不治本） <ol><li>我们让缓存数据的过期时间变短，这样的话缓存就会从数据库中加载数据。</li></ol></li><li>增加 cache 更新重试机制（常用） <ol><li>如果 cache 服务当前不可用导致缓存删除失败的话，我们就隔一段时间进行重试，</li><li>重试次数可以自己定。如果多次重试还是失败的话，我们可以把当前更新失败的 key 存入队列中，等缓存服务可用之后，再将缓存中对应的 key 删除即可。</li></ol></li></ol><blockquote><p>第二种方式采用方案：</p></blockquote><ol><li>引入消息队列来进行异步重试操作（将删除 cache 操作放在消费者这步操作）</li><li>订阅数据库变更日志，再操作缓存</li></ol><hr><p>当缓存操作失败时，通过设置重试机制来确保缓存最终能够与数据库数据保持一致。具体步骤包括：</p><p>A. <strong>直接重试</strong></p><p>在缓存操作（如删除、更新）失败时，立即进行重试。可以设定一个最大重试次数，避免无限重试。</p><p>B. <strong>延时重试</strong></p><p>如果直接重试仍然失败，可以将失败的操作延时一段时间后再重试，延时重试可以通过定时任务或延时队列实现。</p><p>C. <strong>失败队列</strong></p><p>如果重试多次后仍然失败，将更新失败的key存入一个特定的队列中。等到缓存服务恢复正常后，再统一处理这些失败的操作。</p><blockquote><p>具体实施方案</p></blockquote><p>引入消息队列（异步重试）</p><ul><li><strong>消息队列保证可靠性</strong>：写到队列中的消息，成功消费之前不会丢失（重启项目也不担心）</li><li><strong>消息队列保证消息成功投递</strong>：下游从队列拉取消息，成功消费后才会删除消息，否则还会继续投递消息给消费者（符合我们重试的场景）</li></ul><p>使用消息队列作为异步处理机制，<strong>将需要更新或删除的缓存操作</strong>作为消息发送到队列中，由消费者负责执行实际的缓存更新任务。这样即使缓存服务暂时不可用，也不会影响主业务流程，待缓存服务恢复后再通过消费消息来同步缓存。</p><p>订阅数据库变更日志</p><p>另一个高级的方案是直接订阅数据库的变更日志（如果数据库支持），如MySQL的binlog。通过解析变更日志，对相关缓存进行更新或删除操作。这种方法可以确保缓存数据的最终一致性，但实现复杂，对数据库和缓存系统的要求较高。</p><h4 id="数据双写不一致-数据一致性" tabindex="-1">数据双写不一致（数据一致性） <a class="header-anchor" href="#数据双写不一致-数据一致性" aria-label="Permalink to &quot;数据双写不一致（数据一致性）&quot;">​</a></h4><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240317223928.png" alt="image.png"></p><h4 id="讲一下延迟双删" tabindex="-1">讲一下延迟双删 <a class="header-anchor" href="#讲一下延迟双删" aria-label="Permalink to &quot;讲一下延迟双删&quot;">​</a></h4><ul><li>延迟双删 <ul><li>更新数据库智慧，等待一段时间，再次删除缓存中的数据</li></ul></li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240317223544.png" alt="image.png"></p><h4 id="缓存雪崩、缓存击穿、缓存穿透" tabindex="-1">缓存雪崩、缓存击穿、缓存穿透 <a class="header-anchor" href="#缓存雪崩、缓存击穿、缓存穿透" aria-label="Permalink to &quot;缓存雪崩、缓存击穿、缓存穿透&quot;">​</a></h4><ul><li>缓存穿透 <ul><li>缓存穿透是指当请求的数据既不在缓存中也不存在于数据库中时，导致请求直接到达数据库层的现象。</li><li>成因：频繁查询不存在的数据（可能是由于错误的输入或恶意攻击）</li><li>解决方案 <ul><li><strong>空对象缓存</strong>（缓存空结果） <ul><li>即使某个值在数据库中不存在，也可以在缓存中存储一个特殊的空对象或空值，并设置较短的过期时间。</li><li>这样，相同的无效请求在这个过期时间内会直接得到缓存中的空结果，而不会再次查询数据库。</li><li>缺点：可能会导致期间使用内存较高，缓存资源浪费</li></ul></li></ul></li><li><strong>布隆过滤器</strong><ul><li>在查询之前使用布隆过滤器判断数据是否可能存在。布隆过滤器是一种空间效率高但可能有一定误判率的数据结构。</li></ul></li></ul></li><li>缓存击穿 <ul><li>缓存击穿是指缓存中某个热点key突然失效（过期），导致大量并发请求直接落到数据库上，造成数据库短时间内压力剧增的现象。</li><li>与缓存穿透不同，缓存击穿是针对原本就存在于缓存中的热点数据。</li><li>成因：热点数据在缓存中突然过期，而此时正有大量并发请求这些数据。</li><li>解决方案 <ul><li><ul><li><strong>设置热点数据永不过期</strong><ul><li>对于一些热点数据，可以设置其缓存永不过期，或者设置一个非常长的过期时间，从而避免缓存击穿问题。</li><li>但这种方法需要定期手动或通过程序更新缓存，以保证数据的新鲜度</li></ul></li></ul></li><li><strong>互斥锁</strong><ul><li>在缓存失效的瞬间，使用互斥锁或分布式锁，确保只有一个请求去数据库查询数据并重新缓存。</li><li>其他请求等待缓存加载完成后再访问缓存</li></ul></li><li>提前预热 <ul><li>在缓存即将过期前，后台异步程序提前更新缓存中的数据，这样可以确保热点数据在缓存中始终是可用的</li></ul></li><li><strong>二级缓存策略</strong><ul><li>为热点数据设置两级缓存，第一级缓存正常设置过期时间；第二级缓存设置较长的过期时间。当第一级缓存失效时，请求可以访问第二级缓存，同时异步更新第一级缓存和第二级缓存数据。</li></ul></li></ul></li></ul></li><li>缓存雪崩 <ul><li>缓存雪崩是指缓存中<strong>大量数据同时过期</strong>，导致所有的请求都直接访问数据库，可能会使数据库压力过大甚至崩溃。</li><li>成因 <ul><li>缓存设置了相同的过期时间，导致大量数据同时过期。</li><li>缓存服务崩溃，所有数据丢失。</li></ul></li><li>解决方案 <ul><li><strong>不同的过期时间</strong>：为缓存数据设置不同的过期时间，避免同时过期。（可以在设置缓存过期时间时加入随机值）</li><li><strong>缓存数据预热</strong>：系统启动时预先加载热点数据到缓存中。</li><li>限流降级：在系统入口处使用限流降级策略，避免在缓存失效时，突发流量直接打到数据库。</li><li>使用多级缓存策略</li><li><strong>使用高可用的缓存架构</strong>：比如使用Redis集群，提高缓存系统的稳定性和容错能力。</li></ul></li></ul></li></ul><p>总结一下上面的三个常见的生产问题：缓存穿透、缓存击穿、缓存雪崩；</p><ul><li>1、缓存穿透指的不存在的数据进行访问缓存，并打到数据库中，解决方案一般有：空对象缓存、布隆过滤器</li><li>2、缓存击穿和缓存雪崩有点像，都是缓存失效，但前者一般是热点数据，后者是大量数据同时过期； <ul><li>热点数据建议做一下预热处理，在快要过期的时候进行处理一下；或者说常用的两种处理方案： <ul><li>设置热点数据不过期，不过后续需要手动进行更新缓存或者程序更新</li><li>设置互斥锁，保证同一时刻访问缓存的数据（缓存中不存在的数据），此时只有一个</li></ul></li><li>大量数据过期建议使用随机过期时间，同时可以设置一下限流，防止大量数据同时请求；也可以设置多级的一个缓存策略操作。</li></ul></li></ul><h4 id="redis分布式锁实现-🚩" tabindex="-1">Redis分布式锁实现 🚩 <a class="header-anchor" href="#redis分布式锁实现-🚩" aria-label="Permalink to &quot;Redis分布式锁实现 🚩&quot;">​</a></h4><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240312113112.png" alt="image.png"></p><p>使用 Redis 可以实现分布式情况下对访问资源进行加锁</p><ul><li>1、通过 setnx 命令进行加锁</li><li>2、是否锁通过 del 命令删除对应的key <ul><li>为了防止误删到其他的锁，这里我们建议使用 Lua 脚本通过 key 对应的 value（唯一值）来判断。</li><li>选用 Lua 脚本是为了保证解锁操作的原子性。因为 Redis 在执行 Lua 脚本时，可以以原子性的方式执行，从而保证了锁释放操作的原子性</li></ul></li><li>3、优化项 <ul><li>考虑为了避免锁无法释放，一个解决方法是：给这个锁加一个过期时间</li><li><strong>一定要保证设置指定 key 的值和过期时间是一个原子操作！！！</strong> 不然的话，依然可能会出现锁无法被释放的问题。</li><li>因为这个引入了现成的一个解决方案：Redission</li></ul></li><li>4、Redission <ul><li>Redisson 中的分布式锁自带自动续期机制，使用起来非常简单，原理也比较简单，其提供了一个专门用来监控和续期锁的 <strong>Watch Dog（ 看门狗）</strong>，如果操作共享资源的线程还未执行完成的话，Watch Dog 会不断地延长锁的过期时间，进而保证锁不会因为超时而被释放。</li></ul></li><li>5、如何实现可重入锁（锁里面又需要获取到另外一个需要锁的方法） <ul><li><strong>不可重入的分布式锁基本可以满足绝大部分业务场景了，一些特殊的场景可能会需要使用可重入的分布式锁</strong></li><li>实际实现中，Redission 是提供了实现方案的 <ul><li><strong>Redisson</strong> ，内置了多种类型的锁比如可重入锁（Reentrant Lock）、自旋锁（Spin Lock）、公平锁（Fair Lock）、多重锁（MultiLock）、 红锁（RedLock）、 读写锁（ReadWriteLock）。</li></ul></li></ul></li></ul><p>在面对高并发的库存扣减问题时，除了使用Redis分布式锁外，还可以考虑以下一些策略：</p><ol><li><strong>乐观锁</strong>：在数据表中使用版本号（或时间戳）字段，每次更新时检查版本号是否一致，如果一致则更新并增加版本号。这种方式减少了锁的使用，但在高冲突环境下可能导致大量的重试。</li><li><strong>消息队列</strong>：将库存扣减操作异步化，通过消息队列来控制对库存的操作序列。这样可以平滑高峰期的请求，但需要处理好消息的可靠性和消费顺序。</li><li><strong>令牌桶或漏斗算法</strong>：通过限流算法控制对库存操作的并发量，保证系统的稳定性。</li><li><strong>分段锁</strong>：如果库存数据可以分段（例如不同的商品或仓库），可以对每一段使用独立的锁或Redis key，从而减少锁的竞争。</li><li><strong>预扣减与补偿机制</strong>：在用户下单时先进行库存预扣减，然后异步处理订单，如果订单处理失败则进行库存补偿。这种方式可以快速响应用户请求，但需要处理好补偿逻辑。</li></ol><h4 id="大-key-问题" tabindex="-1">大 Key 问题 <a class="header-anchor" href="#大-key-问题" aria-label="Permalink to &quot;大 Key 问题&quot;">​</a></h4><blockquote><p>遇到过大 Key 问题吗，说一下当时遇到的场景，以及当时是怎么处理的</p></blockquote><p>参考： <a href="https://www.bilibili.com/video/BV1iu411v7fp" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1iu411v7fp</a></p><p>什么是大 Key：</p><p>string 类型的值大于 10 kb</p><p>hash、Iist、set、Zset元素个数超过 5000 个</p><p>如何找到 大 Key</p><ul><li>redis -cli -h 127.0.0.1 -p6379 -a &quot;password&quot; -- bigkeys</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240511112841.png" alt="image.png"></p><p>如何删除 大 Key</p><ul><li>直接删除大key会造成阻塞，因为redis是单线程执行，阻塞期间，其他所有请求可能都会超时。超时越来越多，会造成 redis 连接会耗尽，产生各种异常</li><li>低峰期删除：凌晨，观察 qps ,选择低的时候，无法彻底解决阻塞</li><li>分批次删除：对于hash,使用 hscan 扫描法，对于集合采用 srandmember 每次随机取数据进行删除。对于有序集台可以使用 zremrangebyrank 直接删除，对于列表直接pop即可。</li><li>异步删除法：用 unlink 代替del来删除，这样redis会将这个key 放入到一个异步线程中，进行删除，这样不会阻塞主线程。</li></ul><hr><p>参考： <a href="https://www.bilibili.com/video/BV1m54y1f74X" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1m54y1f74X</a></p><p>大 Key 一般会造成客户端阻塞，造成查询失败、网络阻塞等现象；</p><p>一般说这个通过 问题反馈 → 问题排查 → 问题解决</p><p>发现了 大 key 问题，一般需要逐步进行删除操作，避免影响其他业务服务</p><p>删除后，考虑如何对 redis 的大 key 进行设计和优化</p><h3 id="elasticsearch" tabindex="-1">Elasticsearch <a class="header-anchor" href="#elasticsearch" aria-label="Permalink to &quot;Elasticsearch&quot;">​</a></h3><h4 id="你们项目中使用的框架是什么" tabindex="-1">你们项目中使用的框架是什么？ <a class="header-anchor" href="#你们项目中使用的框架是什么" aria-label="Permalink to &quot;你们项目中使用的框架是什么？&quot;">​</a></h4><h3 id="spring" tabindex="-1">Spring <a class="header-anchor" href="#spring" aria-label="Permalink to &quot;Spring&quot;">​</a></h3><h4 id="spring-的生命周期" tabindex="-1">Spring 的生命周期 <a class="header-anchor" href="#spring-的生命周期" aria-label="Permalink to &quot;Spring 的生命周期&quot;">​</a></h4><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240531174218.png" alt="image.png"></p><h4 id="spring-的传播事务-🚩" tabindex="-1">Spring 的传播事务 🚩 <a class="header-anchor" href="#spring-的传播事务-🚩" aria-label="Permalink to &quot;Spring 的传播事务   🚩&quot;">​</a></h4><p>Service 中进行事务调用的时候，一般是需要注意一下事务传播行为，默认的 Spring 事务传播行为是：PROPAGATION_REQUIRED</p><ul><li>PROPAGATION_REQUIRED ✈ <ul><li>默认传播行为</li><li>存在则加入，否则创建新的事务</li></ul></li><li>PROPAGATION_SUPPORTS ✈ <ul><li>存在则加入，否则以非事务方式执行</li></ul></li><li>PROPAGATION_MANDATORY <ul><li>如果当前不存在事务就报错，否则就加 ⼊前事务</li></ul></li><li>PROPAGATION_REQUIRES_NEW ✈ <ul><li>每次都会创建新事务，外部事务可以进行捕获新事务的异常，再决定是否回滚事务</li><li>外事务发出异常进行回滚，不会影响内事务（独立事务）</li></ul></li><li>PROPAGATION_NOT_SUPPORTED <ul><li>，如果当前存在事务，就将当前事 务挂起，否则以⾮事务运⾏</li></ul></li><li>PROPAGATION_NEVER <ul><li>如果当前存在事务就报错，否则以⾮事务运 ⾏</li></ul></li><li>PROPAGATION_NESTED <ul><li>如果当前存在事务，就嵌套事务内运⾏， 如果不存在事务就按照PROPAGATION_REQUIRED运⾏</li><li>外事务发出异常进行回滚，内事务也进行回滚</li></ul></li></ul><p>propagation 传播 （朴 r 朴 ga tion）</p><table tabindex="0"><thead><tr><th>传播行为</th><th>描述</th><th>应用场景</th></tr></thead><tbody><tr><td>PROPAGATION_REQUIRED</td><td>存在则加入，否则创建新的事务</td><td>默认行为，适用于绝大多数情况</td></tr><tr><td>PROPAGATION_SUPPORTS</td><td>存在则加入，否则以非事务方式执行</td><td>可选的事务，不强制要求</td></tr><tr><td>PROPAGATION_MANDATORY</td><td>存在则加入，否则抛出异常</td><td>强制要求必须在事务中执行</td></tr><tr><td>PROPAGATION_REQUIRES_NEW</td><td>总是创建新事务，挂起当前事务</td><td>需要独立事务的场景</td></tr><tr><td>PROPAGATION_NOT_SUPPORTED</td><td>以非事务方式执行，挂起当前事务</td><td>不需要事务的操作，或者事务会导致问题的场景</td></tr><tr><td>PROPAGATION_NEVER</td><td>以非事务方式执行，如果有事务则抛出异常</td><td>强制要求不在事务中执行</td></tr><tr><td>PROPAGATION_NESTED</td><td>在嵌套事务内执行，如果没有则创建新事务</td><td>需要嵌套事务的场景，支持内外事务单独回滚</td></tr></tbody></table><p>这种传播行为主要是用来精准控制事务行为，可以看一下下面的示例</p><p>第一种是默认情况，默认情况是 Propagation_REQUEST：加入到同一个事务中</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@Service</span></span>
<span class="line"><span>public class OrderService {</span></span>
<span class="line"><span>    @Autowired</span></span>
<span class="line"><span>    private PaymentService paymentService;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    @Transactional(propagation = Propagation.REQUIRED)</span></span>
<span class="line"><span>    public void placeOrder(Order order) {</span></span>
<span class="line"><span>        // 保存订单</span></span>
<span class="line"><span>        saveOrder(order);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        // 调用支付服务</span></span>
<span class="line"><span>        paymentService.processPayment(order.getPayment());</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    private void saveOrder(Order order) {</span></span>
<span class="line"><span>        // 保存订单逻辑</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>@Service</span></span>
<span class="line"><span>public class PaymentService {</span></span>
<span class="line"><span>    @Transactional(propagation = Propagation.REQUIRED)</span></span>
<span class="line"><span>    public void processPayment(Payment payment) {</span></span>
<span class="line"><span>        // 支付处理逻辑</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>在这个示例中，<code>OrderService.placeOrder</code> 方法和 <code>PaymentService.processPayment</code> 方法都使用 <code>PROPAGATION_REQUIRED</code> 传播行为。如果 <code>placeOrder</code> 方法已经在一个事务中执行，那么 <code>processPayment</code> 方法将加入到同一个事务中。这确保了订单和支付要么同时成功，要么同时失败。</p><hr><p>示例2：<code>PROPAGATION_REQUIRES_NEW</code> 用于在现有事务中执行一个完全独立的事务</p><p>例如记录日志或处理独立的业务逻辑。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@Service</span></span>
<span class="line"><span>public class OrderService {</span></span>
<span class="line"><span>    @Autowired</span></span>
<span class="line"><span>    private PaymentService paymentService;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    @Transactional(propagation = Propagation.REQUIRED)</span></span>
<span class="line"><span>    public void placeOrder(Order order) {</span></span>
<span class="line"><span>        // 保存订单</span></span>
<span class="line"><span>        saveOrder(order);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        // 独立的事务处理支付</span></span>
<span class="line"><span>        paymentService.processPayment(order.getPayment());</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    private void saveOrder(Order order) {</span></span>
<span class="line"><span>        // 保存订单逻辑</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>@Service</span></span>
<span class="line"><span>public class PaymentService {</span></span>
<span class="line"><span>    @Transactional(propagation = Propagation.REQUIRES_NEW)</span></span>
<span class="line"><span>    public void processPayment(Payment payment) {</span></span>
<span class="line"><span>        // 支付处理逻辑</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>在这个示例中，<code>PaymentService.processPayment</code> 方法使用 <code>PROPAGATION_REQUIRES_NEW</code>。即使 <code>placeOrder</code> 方法回滚，<code>processPayment</code> 方法所做的更改也不会被回滚，因为它们是在一个独立的事务中执行的。</p><hr><p>示例 3：<code>PROPAGATION_NESTED</code> 用于在现有事务中执行嵌套事务，嵌套事务可以独立回滚。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@Service</span></span>
<span class="line"><span>public class OrderService {</span></span>
<span class="line"><span>    @Autowired</span></span>
<span class="line"><span>    private PaymentService paymentService;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    @Transactional(propagation = Propagation.REQUIRED)</span></span>
<span class="line"><span>    public void placeOrder(Order order) {</span></span>
<span class="line"><span>        // 保存订单</span></span>
<span class="line"><span>        saveOrder(order);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        // 嵌套事务处理支付</span></span>
<span class="line"><span>        try {</span></span>
<span class="line"><span>            paymentService.processPayment(order.getPayment());</span></span>
<span class="line"><span>        } catch (Exception e) {</span></span>
<span class="line"><span>            // 处理支付异常</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    private void saveOrder(Order order) {</span></span>
<span class="line"><span>        // 保存订单逻辑</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>@Service</span></span>
<span class="line"><span>public class PaymentService {</span></span>
<span class="line"><span>    @Transactional(propagation = Propagation.NESTED)</span></span>
<span class="line"><span>    public void processPayment(Payment payment) {</span></span>
<span class="line"><span>        // 支付处理逻辑</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>在这个示例中，如果 <code>processPayment</code> 方法抛出异常，嵌套事务将回滚，但外部的 <code>placeOrder</code> 事务可以根据需要选择继续或回滚。</p><p><code>nested</code> 嵌套的</p><h4 id="常见的spring事务失效场景" tabindex="-1">常见的Spring事务失效场景 <a class="header-anchor" href="#常见的spring事务失效场景" aria-label="Permalink to &quot;常见的Spring事务失效场景&quot;">​</a></h4><ul><li>@Transactional注解应用于非public方法，事务将不会生效</li><li>当一个类的方法调用同一个类中的另一个带有@Transactional注解的方法时，事务将不会生效。 <ul><li>自调用现象，解决方案是通过<code>self</code>代理调用</li></ul></li><li>事务只会在未被捕获的<code>RuntimeException</code>或<code>Error</code>类型的异常时回滚。如果抛出的是<code>CheckedException</code>，事务不会自动回滚，除非明确指定。</li><li>数据库不支持事务</li><li>Spring的事务管理依赖于线程绑定。如果在事务中切换线程（例如通过异步调用），事务将失效</li><li>错误的事务传播行为配置</li></ul><p><strong>自调用</strong></p><p>当一个类的方法调用同一个类中的另一个带有@Transactional注解的方法时，事务将不会生效。Spring AOP是通过代理实现的，self-invocation绕过了代理对象。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@Service</span></span>
<span class="line"><span>public class MyService {</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    @Autowired</span></span>
<span class="line"><span>    private MyService self;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    @Transactional</span></span>
<span class="line"><span>    public void methodA() {</span></span>
<span class="line"><span>        // 方法B的事务将不会生效</span></span>
<span class="line"><span>        methodB();</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    @Transactional</span></span>
<span class="line"><span>    public void methodB() {</span></span>
<span class="line"><span>        // 事务性代码</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><ul><li><code>methodA</code> 的事务会生效，因为它是由外部调用的，Spring 会通过代理对象来处理事务。</li><li><code>methodB</code> 的事务不会生效，因为它是通过 <code>this.methodB()</code> 调用的，没有经过 Spring 的代理对象。</li></ul><p>解决方案是通过<code>self</code>代理调用：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@Service</span></span>
<span class="line"><span>public class MyService {</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    @Autowired</span></span>
<span class="line"><span>    private MyService self;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    @Transactional</span></span>
<span class="line"><span>    public void methodA() {</span></span>
<span class="line"><span>        // 方法B的事务将生效</span></span>
<span class="line"><span>        self.methodB();</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    @Transactional</span></span>
<span class="line"><span>    public void methodB() {</span></span>
<span class="line"><span>        // 事务性代码</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><strong>异常类型抛出</strong></p><p>to be contined....</p><h4 id="编程式事务和声明式事务的优缺点" tabindex="-1">编程式事务和声明式事务的优缺点 <a class="header-anchor" href="#编程式事务和声明式事务的优缺点" aria-label="Permalink to &quot;编程式事务和声明式事务的优缺点&quot;">​</a></h4><h4 id="谈一下对于-aop-的理解" tabindex="-1">谈一下对于 AOP 的理解 <a class="header-anchor" href="#谈一下对于-aop-的理解" aria-label="Permalink to &quot;谈一下对于 AOP 的理解&quot;">​</a></h4><ul><li>AOP就是⾯向切⾯编程，跟OOP⾯向过程编程相对，AOP⼀般⽤于将 公共逻辑和业务逻辑进⾏拆分，可以减少代码间的耦合性</li><li>AOP的实现⽅式主要有基于CGLIB动态代理和基于JDK动态代理 <ul><li>基于CGLIB动态代理是<strong>基于⽗⼦类</strong>实现的，主要是通过被代理的 类⽣成⼀个代理⼦类，代理⼦类重写⽗类⽅法，并且将被代理类 赋值给内部属性target，当执⾏完切⾯逻辑后，通过target执⾏被 代理类⽅法</li><li>基于JDK动态代理是**基于接⼝**实现的，实现InvocationHandler和 Proxy接⼝就⾏</li></ul></li><li>AOP在我们业务中应⽤场景主要有⽇志处理、限流处理、事务、异 步、缓存等</li></ul><p><s>Spring AOP默认使用JDK动态代理。如果目标类没有实现任何接口，Spring会自动切换到使用CGLIB代理</s></p><p>默认代理方式，参考： <a href="https://blog.csdn.net/myli92/article/details/127586235" target="_blank" rel="noreferrer">https://blog.csdn.net/myli92/article/details/127586235</a></p><p>SpringBoot 2.x 版本默认使用的 AOP 动态代理方式是 CGLIB代理</p><h4 id="循环依赖问题如何解决" tabindex="-1">循环依赖问题如何解决 <a class="header-anchor" href="#循环依赖问题如何解决" aria-label="Permalink to &quot;循环依赖问题如何解决&quot;">​</a></h4><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240315154746.png" alt="image.png"></p><p>循环依赖是多个对象之间存在属性相互依赖的问题，例如 A 类依赖 B 类，而 B 类又依赖 A 类。解决循环依赖的方法包括使用 <code>@Lazy</code> 注解和 Spring 提供的三级缓存机制。</p><p>解决循环依赖的方法</p><ol><li><strong>使用 <code>@Lazy</code> 注解</strong>：解决构造方法造成的循环依赖问题，延迟加载依赖。</li><li><strong>使用 Spring 的三级缓存</strong>： <ul><li><strong>一级缓存（<code>singletonObjects</code>）</strong>：存放完整生命周期的对象，使用 <code>ConcurrentHashMap</code>。</li><li><strong>二级缓存（<code>earlySingletonObjects</code>）</strong>：存放半成品对象，使用 <code>ConcurrentHashMap</code>。</li><li><strong>三级缓存（<code>singletonFactories</code>）</strong>：存放 <code>ObjectFactory</code>，用于创建对象的工厂，使用 <code>HashMap</code>。</li></ul></li></ol><p>处理普通循环依赖</p><ul><li>实例化对象放入二级缓存中。</li><li>完成生命周期的对象放入一级缓存，其他依赖该对象的对象也能完成生命周期。</li></ul><p>处理有 AOP 的循环依赖</p><ul><li>三级缓存保存对象的代理配置信息。</li><li>通过 <code>ObjectFactory</code> 创建动态代理类进行 AOP 处理。</li><li>一级缓存存放代理对象。</li></ul><p>核心代码</p><p>三级缓存机制的核心代码在 <code>DefaultSingletonBeanRegistry#getSingleton</code> 方法中</p><h4 id="autowire-和-resource-的区别" tabindex="-1">Autowire 和 Resource 的区别 <a class="header-anchor" href="#autowire-和-resource-的区别" aria-label="Permalink to &quot;Autowire 和 Resource 的区别&quot;">​</a></h4><ul><li>@Resouce在没有指定别名的情况下，@Autowired和@Resource都是 先byType再byName</li><li>@Resouce在指定别名的情况下是先byName再byType</li></ul><h4 id="synchronized-关键字和-transactional-注解-一起使用的话需要注意什么" tabindex="-1"><code>synchronized</code> 关键字和 <code>@Transactional</code> 注解 一起使用的话需要注意什么 <a class="header-anchor" href="#synchronized-关键字和-transactional-注解-一起使用的话需要注意什么" aria-label="Permalink to &quot;\`synchronized\` 关键字和 \`@Transactional\` 注解 一起使用的话需要注意什么&quot;">​</a></h4><p><code>synchronized</code> 关键字和 <code>@Transactional</code> 注解可以在同一个方法中使用，但它们的作用和行为是不同的</p><ul><li>synchronized <ul><li>加锁操作，防止资源争抢</li><li><strong>线程同步</strong>：<code>synchronized</code> 确保一个方法或代码块在同一时间只能被一个线程执行。它主要解决线程之间的并发问题，防止多个线程同时操作共享资源导致数据不一致。</li></ul></li><li>@Transcational <ul><li>确保被注解的方法在一个事务中执行，如果方法抛出一个未被捕获的运行时异常，事务将被回滚</li><li><strong>事务管理</strong>：<code>@Transactional</code> 确保方法在一个事务中执行，解决数据库操作的原子性、一致性、隔离性和持久性（ACID）</li><li><strong>事务延迟</strong>：使用 <code>synchronized</code> 关键字会导致线程等待，这可能会延长事务的执行时间。如果一个方法被 <code>synchronized</code> 修饰并且同时包含数据库操作，事务可能会因为等待其他线程释放锁而保持更长时间，从而潜在地影响性能。</li><li><strong>锁和数据库资源</strong>：长时间持有 <code>synchronized</code> 锁和数据库连接可能导致资源竞争和死锁问题。在设计时需要特别注意这种情况，确保不会长时间持有锁或占用数据库连接</li></ul></li></ul><h4 id="讲一下对-ioc-容器的理解-为什么需要用到-ioc-容器呢" tabindex="-1">讲一下对 IOC 容器的理解，为什么需要用到 IOC 容器呢？ <a class="header-anchor" href="#讲一下对-ioc-容器的理解-为什么需要用到-ioc-容器呢" aria-label="Permalink to &quot;讲一下对 IOC 容器的理解，为什么需要用到 IOC 容器呢？&quot;">​</a></h4><h3 id="springmvc" tabindex="-1">SpringMVC <a class="header-anchor" href="#springmvc" aria-label="Permalink to &quot;SpringMVC&quot;">​</a></h3><h4 id="执行流程" tabindex="-1">执行流程 <a class="header-anchor" href="#执行流程" aria-label="Permalink to &quot;执行流程&quot;">​</a></h4><ul><li>前端控制器</li><li>处理器映射器</li><li>处理器适配器</li><li>处理器</li><li>视图解析器</li><li>视图</li></ul><p>SpringMVC 的执行流程可以分为两种方式：前后端分离和前后端不分离。</p><ul><li>前后端不分离的视图阶段（JSP）</li></ul><ol><li><strong>请求接收</strong>: 前端向前端控制器 <code>DispatcherServlet</code> 发起请求。</li><li><strong>处理器映射</strong>: <code>DispatcherServlet</code> 收到请求，调用处理器映射器 <code>HandlerMapping</code>，根据 URL 请求映射到具体的某一个 <code>Controller</code> 类。</li><li><strong>查找处理器</strong>: <code>HandlerMapping</code> 根据请求 URI 找到具体的处理器，并生成处理器和处理器拦截器（返回处理器执行链 <code>HandlerExecutionChain</code>），然后返回给前端控制器 <code>DispatcherServlet</code>。 <ul><li>拦截器可以在处理请求之前、之后以及视图渲染之前和之后执行额外的逻辑。</li></ul></li><li><strong>处理请求</strong>: 前端控制器根据处理器执行链向处理器适配器 <code>HandlerAdapter</code> 发起请求，<code>HandlerAdapter</code> 会找到对应的处理器（<code>Handler</code>）并发起请求（调用具体的页面控制器 <code>Controller</code>）。处理器根据请求生成对应的响应并返回到处理器适配器，处理器适配器再返回 <code>ModelAndView</code> 到前端控制器。</li><li><strong>视图解析</strong>: 前端控制器根据响应的 <code>ModelAndView</code>，发送到视图解析器 <code>ViewResolver</code>。<code>ViewResolver</code> 会解析并返回对应的 <code>View</code> 实例对象到前端控制器，前端控制器再根据 <code>View</code> 进行渲染视图，从而进行视图展示。</li></ol><ul><li>前后端分离阶段</li></ul><ol><li><strong>请求接收</strong>: 前端控制器 <code>DispatcherServlet</code> 收到前端发起的请求后，会根据请求调用处理器映射器 <code>HandlerMapping</code>。</li><li><strong>查找处理器</strong>: <code>HandlerMapping</code> 返回处理器执行链 <code>HandlerExecutionChain</code> 到前端控制器，前端控制器再发送处理器执行链到处理器适配器。</li><li><strong>处理请求</strong>: <code>HandlerAdapter</code> 会找到对应的处理器（<code>Handler</code>）并发起请求。通常，<code>Controller</code> 上的方法会添加 <code>@ResponseBody</code> 注解，这样响应结构会转换为 JSON 并返回。</li></ol><p>核心组件：前端控制器、处理器映射器、处理器、处理器适配器、处理器、视图解析器</p><ul><li>前端控制器（DispatcherServlet） <ul><li>请求首先到达前端控制器 <code>DispatcherServlet</code>。<code>DispatcherServlet</code> 是整个流程的核心，它负责协调请求处理的各个组件</li></ul></li><li>处理器映射器（Handler Mapping） <ul><li><code>DispatcherServlet</code> 调用处理器映射器（<code>HandlerMapping</code>）来查找处理该请求的处理器（Controller）。<code>HandlerMapping</code> 根据请求 URL 和配置来确定哪个 Controller 来处理该请求</li></ul></li><li>处理器（Handler / Controller） <ul><li>找到处理器后，<code>DispatcherServlet</code> 将请求发送到该处理器。处理器通常是一个带有 <code>@Controller</code> 注解的类，并包含处理请求的方法，这些方法上带有 <code>@RequestMapping</code> 注解来映射请求路径</li></ul></li><li>处理器适配器（Handler Adapter） <ul><li>为了使处理器独立于具体的实现方式，<code>DispatcherServlet</code> 使用处理器适配器（<code>HandlerAdapter</code>）来调用处理器。<code>HandlerAdapter</code> 负责执行处理器的方法并返回一个 <code>ModelAndView</code> 对象</li></ul></li><li>视图解析器</li></ul><p>简化版本</p><ul><li>前端控制器（DispatcherServlet）：接收请求，响应结果，相当于电脑的CPU。</li><li>处理器映射器（HandlerMapping）：根据URL去查找处理器。</li><li>处理器（Handler）：需要程序员去写代码处理逻辑的。</li><li>处理器适配器（HandlerAdapter）：会把处理器包装成适配器，这样就可以支持多种类型的处理器，类比笔记本的适配器（适配器模式的应用）。</li><li>视图解析器（ViewResovler）：进行视图解析，多返回的字符串，进行处理，可以解析成对应的页面。</li></ul><p>视图阶段（JSP) <img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202402290943468.png" alt="image.png"></p><p>前后端分离阶段（接口开发，异步请求） <img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202402290944546.png" alt="image.png"></p><h4 id="常用注解" tabindex="-1">常用注解 <a class="header-anchor" href="#常用注解" aria-label="Permalink to &quot;常用注解&quot;">​</a></h4><ul><li><strong>@Controller</strong><ul><li>用于标识一个类为 SpringMVC 控制器（Controller），用于处理 HTTP 请求。</li></ul></li><li><strong>@RestController</strong><ul><li>是 <code>@Controller</code> 和 <code>@ResponseBody</code> 的组合注解。标识一个类为控制器，并且该类中所有方法的返回值都会直接写入 HTTP 响应体</li></ul></li><li><code>@RequestMapping</code><ul><li>用于映射请求到控制器类或处理器方法上。可以映射 URL 路径、请求方法、请求参数等</li></ul></li><li><strong>@GetMapping, @PostMapping, @PutMapping, @DeleteMapping, @PatchMapping</strong><ul><li>这些注解是 <code>@RequestMapping</code> 的快捷方式，用于简化处理特定 HTTP 请求方法的映射。</li></ul></li><li><strong>@RequestParam</strong><ul><li>用于将请求参数绑定到控制器方法的参数上</li></ul></li><li><strong>@PathVariable</strong><ul><li>用于将 URL 路径中的变量绑定到控制器方法的参数上。</li></ul></li><li><strong>@RequestBody</strong><ul><li>用于将 HTTP 请求体绑定到控制器方法的参数上，常用于处理 JSON 请求</li></ul></li><li><strong>@ResponseBody</strong><ul><li>用于将控制器方法的返回值直接写入 HTTP 响应体，而不是解析为视图。</li></ul></li></ul><h4 id="过滤器和拦截器" tabindex="-1">过滤器和拦截器 <a class="header-anchor" href="#过滤器和拦截器" aria-label="Permalink to &quot;过滤器和拦截器&quot;">​</a></h4><ul><li><p><strong>过滤器（Filter）</strong>：</p><ul><li>适用于需要对请求和响应进行全局过滤和处理的场景。</li><li>例如：安全检查、日志记录、字符编码设置、跨域处理等。</li></ul></li><li><p><strong>拦截器（Interceptor）</strong>：</p><ul><li>适用于需要在控制器方法执行前后进行特定处理的场景。</li><li>例如：权限验证、事务管理、日志记录、性能监控</li></ul></li></ul><h4 id="辩论一个问题-你认为get请求可以带请求体吗-如果可以-你觉得可以的依据是什么" tabindex="-1">辩论一个问题，你认为Get请求可以带请求体吗？如果可以，你觉得可以的依据是什么？ <a class="header-anchor" href="#辩论一个问题-你认为get请求可以带请求体吗-如果可以-你觉得可以的依据是什么" aria-label="Permalink to &quot;辩论一个问题，你认为Get请求可以带请求体吗？如果可以，你觉得可以的依据是什么？&quot;">​</a></h4><h3 id="mybatis" tabindex="-1">Mybatis <a class="header-anchor" href="#mybatis" aria-label="Permalink to &quot;Mybatis&quot;">​</a></h3><h4 id="动态sql标签" tabindex="-1">动态SQL标签 <a class="header-anchor" href="#动态sql标签" aria-label="Permalink to &quot;动态SQL标签&quot;">​</a></h4><ol><li><strong><code>&lt;if&gt;</code></strong> 标签</li><li><strong><code>&lt;choose&gt;</code>、<code>&lt;when&gt;</code>、<code>&lt;otherwise&gt;</code></strong> 标签</li><li><strong><code>&lt;where&gt;</code></strong> 标签</li><li><strong><code>&lt;set&gt;</code></strong> 标签</li><li><strong><code>&lt;trim&gt;</code></strong> 标签</li><li><strong><code>&lt;foreach&gt;</code></strong> 标签</li><li><strong><code>&lt;bind&gt;</code></strong> 标签</li></ol><h4 id="二级缓存" tabindex="-1">二级缓存 <a class="header-anchor" href="#二级缓存" aria-label="Permalink to &quot;二级缓存&quot;">​</a></h4><ul><li>一级缓存 <ul><li>sqlsession</li></ul></li><li>二级缓存 <ul><li>namespace</li></ul></li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240325175422.png" alt="image.png"></p><h4 id="jdbc-的执行流程" tabindex="-1">JDBC 的执行流程 <a class="header-anchor" href="#jdbc-的执行流程" aria-label="Permalink to &quot;JDBC 的执行流程&quot;">​</a></h4><ul><li><ol><li>加载数据库驱动</li></ol></li><li><ol start="2"><li>建立连接</li></ol></li><li><ol start="3"><li>创建Statement或PreparedStatement</li></ol></li><li><ol start="4"><li>执行SQL语句</li></ol></li><li><ol start="5"><li>处理结果</li></ol></li><li><ol start="6"><li>关闭连接</li></ol></li></ul><h4 id="mapper-常用的标签" tabindex="-1">Mapper 常用的标签 <a class="header-anchor" href="#mapper-常用的标签" aria-label="Permalink to &quot;Mapper 常用的标签&quot;">​</a></h4><ul><li>基本标签 <ul><li><code>&lt;configuration&gt;</code></li><li><code>&lt;mapper&gt;</code></li></ul></li><li>SQL 操作标签 <ul><li><code>&lt;select&gt;</code></li><li><code>&lt;insert&gt;</code></li><li><code>&lt;update&gt;</code></li><li><code>&lt;delete&gt;</code></li></ul></li><li>动态 SQL 标签 <ul><li><code>&lt;if&gt;</code></li><li><code>&lt;trim&gt;</code>, <code>&lt;where&gt;</code>, <code>&lt;set&gt;</code></li><li><code>&lt;foreach&gt;</code></li><li><code>&lt;bind&gt;</code></li></ul></li><li>SQL 片断标签 <ul><li><code>&lt;sql&gt;</code> 和 <code>&lt;include&gt;</code></li></ul></li><li>ResultMap 标签 <ul><li><code>&lt;resultMap&gt;</code></li></ul></li></ul><h3 id="springboot" tabindex="-1">SpringBoot <a class="header-anchor" href="#springboot" aria-label="Permalink to &quot;SpringBoot&quot;">​</a></h3><h4 id="自动配置原理" tabindex="-1">自动配置原理 <a class="header-anchor" href="#自动配置原理" aria-label="Permalink to &quot;自动配置原理&quot;">​</a></h4><ul><li>SpringBootApplication <ul><li>SpringBootConfiguration</li><li>ComponentScan</li><li>EnableAutoConfiguration <ul><li>@Import</li><li>spring-factries</li></ul></li></ul></li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240314214559.png" alt="image.png"></p><h5 id="starter" tabindex="-1">starter <a class="header-anchor" href="#starter" aria-label="Permalink to &quot;starter&quot;">​</a></h5><p>在项目的资源目录中创建一个 <code>META-INF/spring.factories</code> 文件，并指定自动配置类。</p><h4 id="内置的-tomcat-替换为其他嵌入式服务器" tabindex="-1">内置的 Tomcat 替换为其他嵌入式服务器 <a class="header-anchor" href="#内置的-tomcat-替换为其他嵌入式服务器" aria-label="Permalink to &quot;内置的 Tomcat 替换为其他嵌入式服务器&quot;">​</a></h4><p>在 <code>pom.xml</code> 文件中排除默认的 Tomcat 依赖，并添加所需的嵌入式服务器依赖</p><p>示例</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;dependencies&gt;</span></span>
<span class="line"><span>    &lt;!-- Exclude Tomcat --&gt;</span></span>
<span class="line"><span>    &lt;dependency&gt;</span></span>
<span class="line"><span>        &lt;groupId&gt;org.springframework.boot&lt;/groupId&gt;</span></span>
<span class="line"><span>        &lt;artifactId&gt;spring-boot-starter-web&lt;/artifactId&gt;</span></span>
<span class="line"><span>        &lt;exclusions&gt;</span></span>
<span class="line"><span>            &lt;exclusion&gt;</span></span>
<span class="line"><span>                &lt;groupId&gt;org.springframework.boot&lt;/groupId&gt;</span></span>
<span class="line"><span>                &lt;artifactId&gt;spring-boot-starter-tomcat&lt;/artifactId&gt;</span></span>
<span class="line"><span>            &lt;/exclusion&gt;</span></span>
<span class="line"><span>        &lt;/exclusions&gt;</span></span>
<span class="line"><span>    &lt;/dependency&gt;</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    &lt;!-- Add Jetty --&gt;</span></span>
<span class="line"><span>    &lt;dependency&gt;</span></span>
<span class="line"><span>        &lt;groupId&gt;org.springframework.boot&lt;/groupId&gt;</span></span>
<span class="line"><span>        &lt;artifactId&gt;spring-boot-starter-jetty&lt;/artifactId&gt;</span></span>
<span class="line"><span>    &lt;/dependency&gt;</span></span>
<span class="line"><span>&lt;/dependencies&gt;</span></span></code></pre></div><h3 id="springcloud" tabindex="-1">SpringCloud <a class="header-anchor" href="#springcloud" aria-label="Permalink to &quot;SpringCloud&quot;">​</a></h3><h4 id="ribbon" tabindex="-1">Ribbon <a class="header-anchor" href="#ribbon" aria-label="Permalink to &quot;Ribbon&quot;">​</a></h4><h4 id="分布式事务的不同方案" tabindex="-1">分布式事务的不同方案 <a class="header-anchor" href="#分布式事务的不同方案" aria-label="Permalink to &quot;分布式事务的不同方案&quot;">​</a></h4><h4 id="限流" tabindex="-1">限流 <a class="header-anchor" href="#限流" aria-label="Permalink to &quot;限流&quot;">​</a></h4><ul><li>Nginx <ul><li>漏桶算法</li></ul></li><li>Gateway <ul><li>令牌桶</li></ul></li></ul><h3 id="rocketmq" tabindex="-1">RocketMQ <a class="header-anchor" href="#rocketmq" aria-label="Permalink to &quot;RocketMQ&quot;">​</a></h3><h4 id="rocketmq-的主要组件-🚩" tabindex="-1">RocketMQ 的主要组件 🚩 <a class="header-anchor" href="#rocketmq-的主要组件-🚩" aria-label="Permalink to &quot;RocketMQ 的主要组件   🚩&quot;">​</a></h4><p>待完善一下</p><ul><li>NameServer <ul><li>作为服务注册以及Broker 路由</li></ul></li><li>Broker <ul><li>作为消息存储，转发的服务</li></ul></li><li>Producer <ul><li>发送消息到 Broker 端</li></ul></li><li>Consumer <ul><li>接收 Broker 端推送的消息或主动 从 Broker 端拉取消息</li></ul></li><li>Topic <ul><li>RocketMQ 根据主题进行消息分类，生产端发送消息时需要指定主题</li></ul></li><li>MessageQueue <ul><li>相当于 Topic 的分区，一个 Topic 默认四个 MessageQueue</li></ul></li></ul><h4 id="rocketmq的推、拉模式-以及广播、集群模式怎么理解的" tabindex="-1">RocketMQ的推、拉模式，以及广播、集群模式怎么理解的 <a class="header-anchor" href="#rocketmq的推、拉模式-以及广播、集群模式怎么理解的" aria-label="Permalink to &quot;RocketMQ的推、拉模式，以及广播、集群模式怎么理解的&quot;">​</a></h4><ul><li>分配策略 <ul><li>广播模式和集群模式是可以在消费者端进行设置的</li><li>集群模式 <ul><li>消费者默认开启的是集群模式</li><li>集群模式下的消费者会和同一个 Consumer Group 中的其他同样开启了集群模式的消费者（如果有）一起分摊消费消息。如果没有其他消费者在同一个 Consumer Group 中，消费者 A 将独自消费所有消息。</li></ul></li><li>广播模式 <ul><li>当消费者开启的是广播模式，它会接收所有消息，不管是否有其他消费者存在。</li></ul></li></ul></li><li>处理方式 <ul><li>消费者对于消息从 Broker 获取消息的方式：拉模式 vs 推模式</li><li>针对推、拉模式，是消费者如何进行处理消息的一种策略，推模式是自动推送，实时消费，拉模式是主动拉取，理解推模式其实也是一种拉模式，只不过开启了定时监听。</li><li>推模式在实现上是通过客户端定期向 Broker 拉取消息，然后触发回调函数进行消息处理。换句话说，推模式是一种高频拉取，并在消息到达时立即处理的模式</li></ul></li></ul><h4 id="消息队列如何保证消息可靠传输" tabindex="-1">消息队列如何保证消息可靠传输 <a class="header-anchor" href="#消息队列如何保证消息可靠传输" aria-label="Permalink to &quot;消息队列如何保证消息可靠传输&quot;">​</a></h4><ul><li>可靠传输，需要保证的点，避免消息丢失 + 避免消息重复消费</li><li>开启消息持久化（避免消息丢失） <ul><li>RocketMQ 使用文件存储（CommitLog）来持久化消息 <ul><li>同步刷盘</li><li>异步刷盘</li></ul></li></ul></li><li>集群模式（提高可靠性，高可用） <ul><li>主从复制 <ul><li>同步复制</li><li>异步复制</li></ul></li></ul></li><li>重试机制（提高可靠性，高可用） <ul><li><strong>Producer 端重试</strong>：Producer 在发送消息失败时，自动进行重试</li><li><strong>Consumer 端重试</strong>：Consumer 在消费消息失败时，RocketMQ 会将消息重新放回队列，稍后再重试消费。</li></ul></li><li>消息重复消费 <ul><li>消息幂等性 <ul><li>消费者应在消费消息时，检查消息是否已被处理。可以使用消息的唯一 ID（例如 Message ID 或自定义业务 ID）来进行去重</li></ul></li></ul></li><li>监控预警 <ul><li>通过 <strong>定时任务与监控</strong>，保持对系统状态的实时监控和告警</li></ul></li></ul><p>说一下这里的重试机制</p><ul><li><strong>生产者端重试</strong>：如果消息发送失败，生产者可以配置自动重试，确保消息最终发送成功。</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#在生产者端设置重试次数</span></span>
<span class="line"><span>DefaultMQProducer producer = new DefaultMQProducer(&quot;ProducerGroupName&quot;);</span></span>
<span class="line"><span>producer.setRetryTimesWhenSendFailed(3);</span></span>
<span class="line"><span>producer.start();</span></span></code></pre></div><ul><li><strong>消费者端重试</strong>：如果消费者处理消息失败，RocketMQ 会将消息重新放回队列，稍后重新投递给消费者。</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>consumer.registerMessageListener(new MessageListenerConcurrently() {</span></span>
<span class="line"><span>    @Override</span></span>
<span class="line"><span>    public ConsumeConcurrentlyStatus consumeMessage(List&lt;MessageExt&gt; msgs, ConsumeConcurrentlyContext context) {</span></span>
<span class="line"><span>        try {</span></span>
<span class="line"><span>            // 处理消息</span></span>
<span class="line"><span>            return ConsumeConcurrentlyStatus.CONSUME_SUCCESS;</span></span>
<span class="line"><span>        } catch (Exception e) {</span></span>
<span class="line"><span>            // 处理异常，返回稍后重新消费状态</span></span>
<span class="line"><span>            return ConsumeConcurrentlyStatus.RECONSUME_LATER;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>});</span></span></code></pre></div><p>同时需要注意的是：RocketMQ 默认是开启持久化的，默认使用异步刷盘（<code>ASYNC_FLUSH</code>）策略。</p><h4 id="rocketmq-为什么要放弃-zookeeper" tabindex="-1">RocketMQ 为什么要放弃 Zookeeper <a class="header-anchor" href="#rocketmq-为什么要放弃-zookeeper" aria-label="Permalink to &quot;RocketMQ 为什么要放弃 Zookeeper&quot;">​</a></h4><ul><li>RocketMQ 主要是保障最终一致性，他只需要一个轻量级的元数据服务就行</li><li>ZK 是作为强一致性的解决方案，同时减少一个中间件使用可以减少维护成本</li></ul><h4 id="rocketmq-的消息模型" tabindex="-1">RocketMQ 的消息模型 <a class="header-anchor" href="#rocketmq-的消息模型" aria-label="Permalink to &quot;RocketMQ 的消息模型&quot;">​</a></h4><ul><li>顺序消息 <ul><li>顺序消息只能保证局部消息有序，不能保证全局有序，实现全局 有序 可以 ⽣产端将⼀批消息有序发往MessageQueue，消费端通 过锁队列的⽅式，每次只拿⼀个MessageQueue⾥的消息</li></ul></li><li>广播消息 <ul><li>⼴播消息并没有特定的消费者，因为这涉及到消费者的集群消费 模式，默认是集群模式</li></ul></li><li>延迟消息 <ul><li>默认提供了18个延迟级别，延迟消息的难点其实是性能，需要不 断进⾏定时轮询，全部扫描所有消息是不可能的</li></ul></li><li>批量消息 <ul><li>只能对同⼀topic下的消息进⾏批量发送，不⽀持延迟消息，以及 批量消息的⼤⼩不超过1MB，超过了需要⾃⾏拆分</li></ul></li><li>过滤消息 <ul><li>消费端可以通过⼀定规则匹配topic下需要的消息，⽀持简单过滤 以及SQL过滤</li><li>消息过滤在消费者端和Broker端都可以做，消费者端进⾏过滤可 以保障消息过滤的可控性，⽽Broker端过滤可以减少不必要数据 的⽹络IO(只把消费者端需要的消息发送出去就⾏)</li></ul></li><li>事务消息 <ul><li>通过事务消息可以确保上下游的数据⼀致性</li><li>实现思路 <ul><li>⽣产者端将消息发往MQ服务，MQ服务将消息持久化后，向⽣ 产端反馈已收到，此时消息为半消息(半事务消息状态)</li><li>⽣产端执⾏完本地事务后，会将执⾏结果向MQ服务进⾏⼆次 确认，判断是否提交或回滚 <ul><li>如果提交，MQ服务将半消息标记为可投递，然后转发给消 费端</li><li>如果回滚，MQ服务会将半消息删除</li></ul></li><li>如果MQ服务没有收到⼆次确认，会对⽣产端进⾏消息回查， 查看事务执⾏结果继续进⾏⼆次确认</li></ul></li></ul></li></ul><h4 id="rocketmq-分布式原理的理解讲一下" tabindex="-1">RocketMQ 分布式原理的理解讲一下 <a class="header-anchor" href="#rocketmq-分布式原理的理解讲一下" aria-label="Permalink to &quot;RocketMQ 分布式原理的理解讲一下&quot;">​</a></h4><ul><li>分布式事务 就是在分布式环境下，需要保证不同服务的数据⼀致性</li><li>分布式事务的实现⽅式可以基于2PC两阶段提交 <ul><li>准备阶段，协调者通知参与者准备提交各⾃的事务</li><li>提交阶段，参与者反馈，协调者通过反馈去决定执⾏事务提交或 回滚</li></ul></li><li>RocketMQ分布式事务也是基于2PC实现的，实现思路 <ul><li>⽣产端将消息发往MQ服务，MQ服务将消息持久化后，向⽣产端 反馈已收到，此时消息为半消息</li><li>⽣产端执⾏完本地事务后，会将执⾏结果向MQ服务进⾏⼆次确 认，判断是否提交或回滚 <ul><li>如果提交，MQ服务将半消息标记为可投递，然后转发给消费 端</li><li>如果回滚，MQ服务会将半消息删除</li></ul></li><li>如果MQ服务没有收到⼆次确认，会对⽣产端进⾏消息回查，查看 事务执⾏结果继续进⾏⼆次确认</li></ul></li></ul><h4 id="rocketmq-生产端的发送模式了解吗" tabindex="-1">RocketMQ 生产端的发送模式了解吗 <a class="header-anchor" href="#rocketmq-生产端的发送模式了解吗" aria-label="Permalink to &quot;RocketMQ 生产端的发送模式了解吗&quot;">​</a></h4><p>一共有三种发送模式</p><ul><li>同步发送 <ul><li>必须等到Broker反馈之后才能继续发，安全性最⾼但发消息最 慢</li></ul></li><li>单向发送 <ul><li>不管消息是否发成功都能继续发，所以吞吐量最⾼，但是安全 性低，容易丢消息</li></ul></li><li>异步发送 <ul><li>发送消息的同时回注册⼀个回调去处理响应，安全性低，容易 丢消息</li></ul></li></ul><h4 id="rocketmq-消费端的消费模式" tabindex="-1">RocketMQ 消费端的消费模式 <a class="header-anchor" href="#rocketmq-消费端的消费模式" aria-label="Permalink to &quot;RocketMQ 消费端的消费模式&quot;">​</a></h4><ul><li>推拉模式</li><li>推其实也是一种监听方式的拉模式</li></ul><h4 id="如何防止消息重复消费" tabindex="-1">如何防止消息重复消费 <a class="header-anchor" href="#如何防止消息重复消费" aria-label="Permalink to &quot;如何防止消息重复消费&quot;">​</a></h4><h4 id="消息堆积问题怎么解决" tabindex="-1">消息堆积问题怎么解决 <a class="header-anchor" href="#消息堆积问题怎么解决" aria-label="Permalink to &quot;消息堆积问题怎么解决&quot;">​</a></h4><ul><li>增加一个中转的消息 topic ，然后配置足够多的 Queue ，增长对应的消费者数量</li><li>如果仍然消费不过来，可以建议一个消息重试的表，将消息进行放入到这个处理表，后面定时任务根据状态去跑任务</li><li>将生产者限流，服务降级</li><li>服务保证幂等的操作</li></ul><p>消息堆积在消息队列系统中是一个常见问题，不同系统的处理方式和性能影响有所不同。以下是 RocketMQ 处理消息堆积的方法及其具体步骤：</p><p>消息堆积对性能的影响</p><ul><li><strong>Kafka 和 RocketMQ</strong>：消息堆积对性能影响不大。</li><li><strong>RabbitMQ</strong>：消息堆积会导致性能直线下降。</li></ul><p>确定 RocketMQ 消息堆积的方法</p><p>可以通过 RocketMQ 控制台查看消息的积压情况，以确定是否存在大量消息堆积。</p><p>处理大量积压消息的方法</p><ol><li>增加消费者</li></ol><p>通过增加消费者来加快消息的消费速度。</p><ul><li><p><strong>多个 MessageQueue</strong>：</p><ul><li>如果 Topic 下的 <code>MessageQueue</code> 数量充足，每个消费者会分配多个 <code>MessageQueue</code> 进行消费。</li><li>增加消费者数量可以加快消息的消费速度。</li></ul></li><li><p><strong>消费者数 = MessageQueue 数</strong>：</p><ul><li>如果消费者数量等于 <code>MessageQueue</code> 数量，增加额外的消费者不会提高消费效率。</li><li>在这种情况下，可以通过新建一个新的 Topic 并配置足够的 <code>MessageQueue</code>，将旧 Topic 中的消息转移到新 Topic 中，并指定对应数量的消费者去平摊新 Topic 的 <code>MessageQueue</code> 进行消费。</li></ul></li></ul><ol start="2"><li>新建 Topic 进行消息转移</li></ol><ul><li><p><strong>步骤</strong>：</p><ol><li><strong>创建新 Topic</strong>：创建一个新的 Topic，并配置足够的 <code>MessageQueue</code>。</li><li><strong>消息转移</strong>：将旧 Topic 中的消息转移到新 Topic 中。</li><li><strong>增加消费者</strong>：为新 Topic 配置对应数量的消费者，以平摊新 Topic 的 <code>MessageQueue</code> 进行消费。</li><li><strong>恢复原有情况</strong>：根据情况，处理完堆积消息后可以恢复原有的 Topic 和消费者配置。</li></ol></li><li><p><strong>示例流程</strong>：</p><ul><li><strong>原始配置</strong>：<code>Topic_A -&gt; Consumer_A</code></li><li><strong>消息转移和新增消费者</strong>： <ul><li><code>Topic_A -&gt; Consumer_A</code></li><li><code>Topic_A -&gt; Consumer_A -&gt; Topic_B -&gt; Consumer_B</code></li></ul></li></ul></li></ul><p>总结</p><ol><li><strong>监控消息堆积</strong>：通过 RocketMQ 控制台查看消息积压情况。</li><li><strong>增加消费者</strong>：通过增加消费者数量加快消息消费速度，前提是 <code>MessageQueue</code> 数量充足。</li><li><strong>新建 Topic 转移消息</strong>：在消费者数量等于 <code>MessageQueue</code> 数量时，通过新建 Topic 和增加消费者来处理堆积消息。</li></ol><h4 id="谈谈对rocketmq零拷⻉的理解" tabindex="-1">谈谈对RocketMQ零拷⻉的理解 <a class="header-anchor" href="#谈谈对rocketmq零拷⻉的理解" aria-label="Permalink to &quot;谈谈对RocketMQ零拷⻉的理解&quot;">​</a></h4><p>零拷贝（Zero Copy）是一种通过避免数据在用户态和内核态之间来回拷贝来提升文件传输速度的技术。其核心思想是减少用户态与内核态之间的拷贝次数，从而提高传输效率。</p><p>RocketMQ 主要使用 <code>mmap</code> 技术：</p><p>mmap是Linux提供的一种内存映射文件的机制，它实现了将内核中读缓冲区地址与用户空间缓冲区地址进行映射，从而实现内核缓冲区与用户缓冲区的共享。</p><p>这样就减少了一次用户态和内核态的CPU拷贝，但是在内核空间内仍然有一次CPU拷贝。</p><ul><li><strong><code>mmap</code></strong>： <ul><li>RocketMQ 在处理消息时采用 <code>mmap</code> 技术。</li><li><code>mmap</code> 使得 RocketMQ 能够直接访问文件内容，这不仅提升了消息传输速度，还支持处理消息的顺序和消息过滤功能。</li></ul></li></ul><p>方式不止 Mmap 一种</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240529215235.png" alt="image.png"></p><h4 id="rocketmq如何保证消息有序" tabindex="-1">RocketMQ如何保证消息有序 <a class="header-anchor" href="#rocketmq如何保证消息有序" aria-label="Permalink to &quot;RocketMQ如何保证消息有序&quot;">​</a></h4><p>在 RocketMQ 中，消息的有序性分为局部有序和全局有序两种：</p><p>局部有序</p><ul><li><strong>定义</strong>：只保证一部分消息链路的消费有序。</li><li><strong>实现</strong>：生产端可以通过消息选择器指定发送到某个特定的 <code>MessageQueue</code>，从而保证这部分消息的消费顺序。</li></ul><p>全局有序</p><ul><li><strong>定义</strong>：整个消息链路严格按照先进先出的顺序进行消费。</li><li><strong>实现</strong>：为了保证全局有序，需要牺牲吞吐量。即，一个 <code>topic</code> 只能有一个 <code>MessageQueue</code> 被消费（默认是 4 个 <code>MessageQueue</code>）。可以通过锁定队列的方式进行消费，确保消息的全局有序性。</li></ul><p>总结</p><ul><li><strong>局部有序</strong>：通过生产端指定 <code>MessageQueue</code> 来保证。</li><li><strong>全局有序</strong>：通过限制一个 <code>topic</code> 只能有一个 <code>MessageQueue</code> 被消费来实现，尽管这样会影响系统的吞吐量。</li></ul><h4 id="rocketmq-如果客户端发生消息超时的情况该如何排查" tabindex="-1">RocketMQ 如果客户端发生消息超时的情况该如何排查 <a class="header-anchor" href="#rocketmq-如果客户端发生消息超时的情况该如何排查" aria-label="Permalink to &quot;RocketMQ 如果客户端发生消息超时的情况该如何排查&quot;">​</a></h4><h3 id="rabbitmq" tabindex="-1">RabbitMQ <a class="header-anchor" href="#rabbitmq" aria-label="Permalink to &quot;RabbitMQ&quot;">​</a></h3><h4 id="讲一下rabbitmq的组成部分" tabindex="-1">讲一下RabbitMQ的组成部分 <a class="header-anchor" href="#讲一下rabbitmq的组成部分" aria-label="Permalink to &quot;讲一下RabbitMQ的组成部分&quot;">​</a></h4><p>核心概念</p><ul><li>Broker：消息队列服务进程。此进程包括两个部分：Exchange和Queue。 <ul><li>Exchange：消息队列交换机。<strong>按一定的规则将消息路由转发到某个队列</strong>。</li><li>Queue：消息队列，存储消息的队列。</li></ul></li><li>Producer：消息生产者。生产方客户端将消息同交换机路由发送到队列中。</li><li>Consumer：消息消费者。消费队列中存储的消息。</li></ul><h4 id="说一下-rabbitmq-的工作流程" tabindex="-1">说一下 RabbitMQ 的工作流程 <a class="header-anchor" href="#说一下-rabbitmq-的工作流程" aria-label="Permalink to &quot;说一下 RabbitMQ 的工作流程&quot;">​</a></h4><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240311230336.png" alt="image.png"></p><ul><li>建立连接</li><li>生产者 <ul><li>声明交换机类型、名称、是否持久化等</li><li>发送消息</li></ul></li><li>交换机 <ul><li>交换机接收消息，进行消息路由</li></ul></li><li>消费者 <ul><li>订阅消息（监听队列）</li><li>接收消息，业务处理</li></ul></li></ul><h4 id="讲一下-rabbitmq-中常用的交换机类型" tabindex="-1">讲一下 RabbitMQ 中常用的交换机类型 <a class="header-anchor" href="#讲一下-rabbitmq-中常用的交换机类型" aria-label="Permalink to &quot;讲一下 RabbitMQ 中常用的交换机类型&quot;">​</a></h4><p>（交换机 → 队列）</p><ul><li>Direct Exchange <ul><li><code>binding key</code> 与消息的 <code>routing key</code> 完全匹配队列</li></ul></li><li>Topic Exchange <ul><li>模糊匹配</li></ul></li><li>Fanout Exchange <ul><li>广播（忽略 <code>routing key</code> ）</li></ul></li><li>Headers Exchange <ul><li>不依赖 <code>routing key</code>，头部属性匹配</li></ul></li></ul><h4 id="rabbitmq的死信队列和延迟队列" tabindex="-1">RabbitMQ的死信队列和延迟队列 <a class="header-anchor" href="#rabbitmq的死信队列和延迟队列" aria-label="Permalink to &quot;RabbitMQ的死信队列和延迟队列&quot;">​</a></h4><ul><li>死信交换机 <ul><li>死信交换机（Dead-Letter Exchange, DLX）是RabbitMQ中用于处理无法正常投递的消息的一种机制。</li><li>当消息在队列中变成死信（Dead Letter）后，可以被自动重新路由到另一个交换机，这个交换机就是所谓的死信交换机。</li><li>消息变成死信的情况通常包括： <ul><li><ol><li>消息被拒绝（Basic.Reject/Basic.Nack）并且设置了requeue参数为false，不重新入队。</li></ol></li><li><ol start="2"><li>消息TTL过期（消息设置了生存时间，超过这个时间还未被消费），超时无人消费</li></ol></li><li><ol start="3"><li>队列达到最大长度（队列满了，无法再添加更多消息到队列中），最早的消息可能成为死信</li></ol></li></ul></li></ul></li><li>延迟队列 <ul><li>RabbitMQ本身并不直接支持延迟队列，但可以通过以下几种方式间接实现： <ul><li>一种方式是：RabbitMQ 的延迟队列通过死信交换机 + TTL （生存时间）来实现的；</li><li>还有一种方式是使用 RabbitMQ 的延迟队列相关的一个插件，叫做：DelayExchange，通过这种方式的话只需要在声明交互机的时候，指定这个就是死信交换机，然后在发送消息的时候直接指定超时时间就行。</li></ul></li></ul></li></ul><hr><p>延迟队列插件使用</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240228060325.png" alt="image.png"></p><h4 id="高可用" tabindex="-1">高可用 <a class="header-anchor" href="#高可用" aria-label="Permalink to &quot;高可用&quot;">​</a></h4><p>一般会使用集群模式，在 RabbitMQ 中，分为了普通集群模式、镜像集群模式、仲裁队列模式</p><p>普通集群模式（标准集群）</p><ul><li>1、在集群的各个节点共享部分数据</li><li>2、当访问集群某个节点，如果队列不在该节点，会从数据所在节点传递到当前节点并返回</li><li>3、队列所在节点宕机，队列中的消息就会丢失 <ul><li>这种模式并不能包括高可用</li><li>实际上还是为了提高吞吐量的</li></ul></li></ul><p>镜像集群：</p><ul><li>本质上是主从模式 <ul><li>交换机、队列、队列中的消息会在各个 mq 的镜像节点之间同步备份。</li><li>创建队列的节点被称为该队列的<strong>主节点</strong>，备份到的其它节点叫做该队列的镜像节点。</li><li>一个队列的主节点可能是另一个队列的镜像节点</li><li>所有操作都是主节点完成，然后同步给镜像节点</li><li>主宕机后，镜像节点会替代成新的主</li></ul></li></ul><p>仲裁队列</p><ul><li>和镜像模式不同的是，他添加了一个主从基于 Raft 协议的方式，使得消息同步变为了强一致性。</li></ul><h4 id="如何保证消息不丢失" tabindex="-1">如何保证消息不丢失 <a class="header-anchor" href="#如何保证消息不丢失" aria-label="Permalink to &quot;如何保证消息不丢失&quot;">​</a></h4><ul><li>发送消息过程中不丢失：消息 → 队列；队列本身，队列 → 消费者 <ul><li>开启生产者确认机制，确保生产者的消息能到达队列</li><li>开启持久化功能，确保消息末消费前在队列中不会丢失</li><li>开启消费者确认机制为auto,由spring确认消息处理成功后完成ack</li><li>开启消费者失数重试机别（重试次数一般设置为3），多次重试失数后将消息投递到异常交换机，交由人工处理</li></ul></li></ul><h4 id="消息重复消费问题怎么解决" tabindex="-1">消息重复消费问题怎么解决 <a class="header-anchor" href="#消息重复消费问题怎么解决" aria-label="Permalink to &quot;消息重复消费问题怎么解决&quot;">​</a></h4><p>出现消息重复消费的问题一般是在网络抖动或者消息者挂掉，由于开启了消费者确认机制，导致消息重发</p><p>一般解决方式有两种：</p><ul><li>一种是每条消息设置一个唯一的标识 ID 从而避免重发消费</li><li>也可以考虑幂等性设计问题，考虑使用分布式锁、数据库锁（悲观锁、乐观锁）等，但锁会对性能有影响，使用的时候需要考虑使用</li></ul><h4 id="消息堆积问题怎么解决-1" tabindex="-1">消息堆积问题怎么解决 <a class="header-anchor" href="#消息堆积问题怎么解决-1" aria-label="Permalink to &quot;消息堆积问题怎么解决&quot;">​</a></h4><p>RabbitMQ 如果有100万消息堆积在MQ，如何解决？</p><p>当生产者发送消息的速度超过了消费者处理消息的速度，就会导致队列中的消息堆积，直到队列存储消息达到上限。之后发送的消息就会成为死信，可能会被丢弃，这就是消息堆积问题。</p><p>解决消息堆积有三种种思路：</p><ul><li>增加更多消费者，提高消费速度</li><li>在消费者内开启线程池加快消息处理速度</li><li>扩大队列容积，提高堆积上限，采用惰性队列 <ul><li>在声明队列的时候可以设置属性x-queue-mode为lazy,即为惰性队列</li><li>基于磁盘存储，消息上限高</li><li>性能比较稳定，但基于磁盘存储，受限于磁盘 IO,时效性会降低</li></ul></li></ul><p>惰性队列：惰性队列通过改变消息存储的策略，将消息尽可能地存储在磁盘上，而不是保留在内存中，从而减轻对内存的压力。</p><h3 id="kafka" tabindex="-1">Kafka <a class="header-anchor" href="#kafka" aria-label="Permalink to &quot;Kafka&quot;">​</a></h3><h4 id="怎么控制分区-和放置重复幂等的。" tabindex="-1">怎么控制分区，和放置重复幂等的。 <a class="header-anchor" href="#怎么控制分区-和放置重复幂等的。" aria-label="Permalink to &quot;怎么控制分区，和放置重复幂等的。&quot;">​</a></h4><h3 id="系统设计" tabindex="-1">系统设计 <a class="header-anchor" href="#系统设计" aria-label="Permalink to &quot;系统设计&quot;">​</a></h3><h4 id="中台的概念" tabindex="-1">中台的概念 <a class="header-anchor" href="#中台的概念" aria-label="Permalink to &quot;中台的概念&quot;">​</a></h4><p>中台是一个平台化、服务化的系统架构层，聚合和沉淀企业内部共用的业务能力和技术服务。中台的目标是通过复用和共享，提高系统的灵活性、可扩展性和响应速度。</p><blockquote><p>主要功能</p></blockquote><ol><li><strong>业务中台</strong>：提供业务领域的共性能力，如用户管理、订单处理、库存管理等，支持前台业务应用的快速开发和迭代。</li><li><strong>数据中台</strong>：聚合和管理企业的数据资源，提供数据分析、数据治理和数据服务等功能。</li><li><strong>技术中台</strong>：提供技术基础设施服务，如微服务框架、消息队列、缓存等。</li></ol><h4 id="分库分表的概念-什么时候适合分库" tabindex="-1">分库分表的概念，什么时候适合分库 <a class="header-anchor" href="#分库分表的概念-什么时候适合分库" aria-label="Permalink to &quot;分库分表的概念，什么时候适合分库&quot;">​</a></h4><ul><li>分表 <ul><li>主要解决单个表的数据量和查询性能问题，通过增加表的数量来减少单个表的数据量。</li></ul></li><li>分库 <ul><li>主要解决数据库实例的存储和处理能力瓶颈问题，通过增加数据库实例的数量来提升系统性能。</li></ul></li></ul><h3 id="场景题" tabindex="-1">场景题 <a class="header-anchor" href="#场景题" aria-label="Permalink to &quot;场景题&quot;">​</a></h3><h4 id="后端给前端推送消息有哪几种方式" tabindex="-1">后端给前端推送消息有哪几种方式 <a class="header-anchor" href="#后端给前端推送消息有哪几种方式" aria-label="Permalink to &quot;后端给前端推送消息有哪几种方式&quot;">​</a></h4><p>一般我们会使用 websockets 的方式</p><h4 id="服务迁移如何做到无感知的" tabindex="-1">服务迁移如何做到无感知的 <a class="header-anchor" href="#服务迁移如何做到无感知的" aria-label="Permalink to &quot;服务迁移如何做到无感知的&quot;">​</a></h4><p>一般是灰度发布或者 AB 发布</p><p>滚动发布，蓝绿发布</p><h4 id="如何切流" tabindex="-1">如何切流 <a class="header-anchor" href="#如何切流" aria-label="Permalink to &quot;如何切流&quot;">​</a></h4><ul><li>前端 <ul><li>Nginx</li></ul></li><li>后端 <ul><li>Nacos，动态配置，轮询，添加对应的服务（对外提高的接口字段对应是相同的）</li></ul></li></ul><p>慢切开关</p><h4 id="什么是服务网格" tabindex="-1">什么是服务网格 <a class="header-anchor" href="#什么是服务网格" aria-label="Permalink to &quot;什么是服务网格&quot;">​</a></h4><h4 id="如果你在开发中-一个接口报错-你的排查思路有哪些" tabindex="-1">如果你在开发中，一个接口报错，你的排查思路有哪些 <a class="header-anchor" href="#如果你在开发中-一个接口报错-你的排查思路有哪些" aria-label="Permalink to &quot;如果你在开发中，一个接口报错，你的排查思路有哪些&quot;">​</a></h4><p>排查接口报错问题需要系统化的思维，从重现问题、查看日志、检查请求和响应、验证代码实现、环境检查、网络问题、数据库操作、安全问题等方面逐一排查。通过这种系统化的排查方法，可以有效定位并解决接口报错问题。</p><h4 id="如果一个接口很慢-有什么思路去排查" tabindex="-1">如果一个接口很慢，有什么思路去排查 <a class="header-anchor" href="#如果一个接口很慢-有什么思路去排查" aria-label="Permalink to &quot;如果一个接口很慢，有什么思路去排查&quot;">​</a></h4><ul><li>网络</li><li>下游接口响应</li><li>SQL 查询性能</li></ul><h4 id="水平分表的话-如果短时间内有大量数据产生-单表性能仍然不太行-你有什么策略去做。" tabindex="-1">水平分表的话，如果短时间内有大量数据产生，单表性能仍然不太行，你有什么策略去做。 <a class="header-anchor" href="#水平分表的话-如果短时间内有大量数据产生-单表性能仍然不太行-你有什么策略去做。" aria-label="Permalink to &quot;水平分表的话，如果短时间内有大量数据产生，单表性能仍然不太行，你有什么策略去做。&quot;">​</a></h4><ul><li>动态分表 <ul><li><strong>根据时间或数据量分表</strong><ul><li>按时间段分表，例如按天、周、月等。</li><li>按数据量分表，例如每当表中的数据达到一定数量时，自动创建新表。</li></ul></li></ul></li><li>读写分离</li></ul><h4 id="水平分表后-你们之前的数据是如何清除到新的数据库表" tabindex="-1">水平分表后，你们之前的数据是如何清除到新的数据库表 <a class="header-anchor" href="#水平分表后-你们之前的数据是如何清除到新的数据库表" aria-label="Permalink to &quot;水平分表后，你们之前的数据是如何清除到新的数据库表&quot;">​</a></h4><ul><li>批量查，再通过接口插入</li><li>或者先根据条件查询出需要插入的数据，再进行批量查</li></ul><h4 id="mvc-与-ddd" tabindex="-1">MVC 与 DDD <a class="header-anchor" href="#mvc-与-ddd" aria-label="Permalink to &quot;MVC  与 DDD&quot;">​</a></h4><p>MVC</p><ul><li><strong>模型（Model）</strong>：代表应用程序的数据结构，通常包含数据的处理逻辑。</li><li><strong>视图（View）</strong>：展示数据（即模型）的用户界面，不包含业务逻辑。</li><li><strong>控制器（Controller）</strong>：接收用户的输入并调用模型和视图来完成用户的请求</li></ul><p>DDD</p><ul><li>基于领域模型（Domain Model）</li><li>实体（Entity）、值对象（Value Object）、聚合（Aggregate）、领域事件（Domain Event）、领域服务（Domain Service）等</li></ul><h4 id="性能优化" tabindex="-1">性能优化 <a class="header-anchor" href="#性能优化" aria-label="Permalink to &quot;性能优化&quot;">​</a></h4><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/31a84718a5ffd47cc8e2f691ad3bd9e.png" alt="31a84718a5ffd47cc8e2f691ad3bd9e.png"></p><h4 id="授权认证" tabindex="-1">授权认证 <a class="header-anchor" href="#授权认证" aria-label="Permalink to &quot;授权认证&quot;">​</a></h4><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240324235306.png" alt="image.png"></p><h4 id="加密算法" tabindex="-1">加密算法 <a class="header-anchor" href="#加密算法" aria-label="Permalink to &quot;加密算法&quot;">​</a></h4><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240324235131.png" alt="image.png"></p><h4 id="使用账号密码访问流程-jwt-方式" tabindex="-1">使用账号密码访问流程（JWT 方式） <a class="header-anchor" href="#使用账号密码访问流程-jwt-方式" aria-label="Permalink to &quot;使用账号密码访问流程（JWT 方式）&quot;">​</a></h4><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240330222111.png" alt="image.png"></p><ul><li>SpringSecurity：matches 方法（提取盐操作，生成哈希值，比较哈希值）</li></ul><h4 id="会员批量过期方案" tabindex="-1">会员批量过期方案 <a class="header-anchor" href="#会员批量过期方案" aria-label="Permalink to &quot;会员批量过期方案&quot;">​</a></h4><p>参考： <a href="https://www.bilibili.com/video/BV1cQ4y1W7Wo" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1cQ4y1W7Wo</a></p><ul><li>场景：如果在会员订阅的情况下，当会员过期的时候向用户进行提醒 <ul><li>有一张200W数据量的会员表，每个会员会有长短不一的到期时间，现在想在快到期之前发送邮件通知提醒续费，该如何实现？</li></ul></li><li>操作 <ul><li>1、系统不主动轮询。而是等用户登绿到系统以后,触发一次检查 <ul><li>判断会员过期时间 &lt; 设定阈值，进行提醒</li><li>缺点：不登陆无法提醒</li></ul></li><li>2、使用搜索引擎，将会员 ID 和 过期时间存入</li><li>3、使用 Redis 来实现 <ul><li>设置 redis 的过期时间，使用它的 redis 提醒功能 <ul><li>修改配置项：notify-keyspace-events 改为notify-keyspace-events &quot;Ex&quot;</li><li>会触发一个 key 过期事件</li><li>通过在应用程序中监听这个事件进行处理</li></ul></li></ul></li><li>4、使用 MQ 中的延迟队列 <ul><li>计算过期时间，发送消息到延迟队列，过期时间过期，消费者进行消费操作</li></ul></li></ul></li></ul><h4 id="在2g大小的文件中-找出高频-top100的单词" tabindex="-1">在2G大小的文件中 找出高频 top100的单词 <a class="header-anchor" href="#在2g大小的文件中-找出高频-top100的单词" aria-label="Permalink to &quot;在2G大小的文件中 找出高频 top100的单词&quot;">​</a></h4><ul><li>1、把2G的文件进行分割成大小为512KB小文件，总共得到2048个小文件，避兔一次性读入整个文件，造成内存不足</li><li>2、定义一个长度为2048的hash表数组，用来统计每个小文件中单词出现的频率</li><li>3、使用多线程并行遍历2048个小文件，针对每个单词进行hash取模运算分别存储到长度为2048的hash表数组中 <img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240601084552.png" alt="image.png"></li><li>4、接着再遍历这2048个hash表，把频率前 100的单词存入小顶堆中</li><li>5、小顶堆中最终得到的 100个单词，就是top 100 了</li></ul><h4 id="对接第三方接口需要考虑什么" tabindex="-1">对接第三方接口需要考虑什么 <a class="header-anchor" href="#对接第三方接口需要考虑什么" aria-label="Permalink to &quot;对接第三方接口需要考虑什么&quot;">​</a></h4><ul><li>1、安全性问题 <ul><li>通信协议 https</li><li>数据安全，认证签名</li></ul></li><li>2、接口的稳定性和可靠性</li><li>3、接口释放存在访问限制或者费用</li></ul><h4 id="表数据量大的时候-影响查询效率的主要原因有哪些" tabindex="-1">表数据量大的时候，影响查询效率的主要原因有哪些 <a class="header-anchor" href="#表数据量大的时候-影响查询效率的主要原因有哪些" aria-label="Permalink to &quot;表数据量大的时候，影响查询效率的主要原因有哪些&quot;">​</a></h4><ul><li>1、磁盘 IO</li><li>2、索引失效</li><li>3、数据分页</li><li>4、锁竞争</li><li>5、内存使用</li></ul><h4 id="数据量达到多少的时候要开始分库分表" tabindex="-1">数据量达到多少的时候要开始分库分表 <a class="header-anchor" href="#数据量达到多少的时候要开始分库分表" aria-label="Permalink to &quot;数据量达到多少的时候要开始分库分表&quot;">​</a></h4><ul><li>结合具体业务场景和系统架构考虑</li><li></li></ul><h4 id="生产环境-openresty-单接口-502-排查思路" tabindex="-1"><strong>生产环境 OpenResty 单接口 502 排查思路</strong> <a class="header-anchor" href="#生产环境-openresty-单接口-502-排查思路" aria-label="Permalink to &quot;**生产环境 OpenResty 单接口 502 排查思路**&quot;">​</a></h4><blockquote><p>我们在去部署一个站点的时候肯定不会说起了一个Server直接把它暴露出去，正常来讲我们肯定是分布式部署、或者说挂一下负载均衡之类的，那么它肯定是多层的，现在生产环境有一个接口，在调用这个接口的时候出现了502，（只有这么一个接口报502,其他接口都正常)，这个502是OpenResty的默认报错页面，现在就只有这么个信息，如果是你的话你的排查思路会是什么？</p></blockquote><ol><li><p><strong>先看日志，确认是不是“部分请求”出问题</strong></p><ul><li>看该接口的访问日志：是否全部 502，还是部分参数/部分客户端/部分时间段 502；</li><li>重点字段：<code>upstream_addr</code>、<code>upstream_status</code>、<code>request_time</code>、<code>upstream_connect_time</code>、<code>upstream_response_time</code>；</li><li>看 OpenResty <code>error.log</code>：<code>connect() failed</code>、<code>upstream prematurely closed connection</code>、<code>no live upstreams</code>、<code>upstream sent invalid header</code> 等；</li><li>判断是连不上后端、后端提前断开，还是后端返回异常。</li></ul></li><li><p><strong>通过 <code>upstream_addr</code> 定位后端实例 IP，查这台机器</strong></p><ul><li>看 502 是否固定打到某一台/某几台后端；</li><li>如果固定某台：重点查该实例的服务日志、端口、进程、资源、健康检查；</li><li>对比正常实例和异常实例的差异；</li><li>看这台机器最近有没有发布、重启、扩容、配置变更；</li><li>判断是不是“发布到这台机器的服务有问题”。</li></ul></li><li><p><strong>看 trace 链路和最近发布变更，再做灰度验证</strong></p><ul><li>通过 trace 链路看请求在哪个节点失败：OpenResty → 后端服务 → 依赖服务；</li><li>同时查最近发布记录、配置变更、扩缩容、依赖服务变更；</li><li>能在灰度/跳板/内网环境复现的，再做直连后端或抓包验证；</li><li>止损优先：摘除异常实例、回滚最近发布、切流；</li><li>最后补按接口 + 后端实例维度的 5xx、upstream 失败监控。</li></ul></li></ol><p><strong>生产排查以日志和实例定位为主，直连后端只是有条件时的验证手段，不是第一步。</strong></p><h3 id="设计模式" tabindex="-1">设计模式 <a class="header-anchor" href="#设计模式" aria-label="Permalink to &quot;设计模式&quot;">​</a></h3><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240317102553.png" alt="image.png"></p><h4 id="观察者" tabindex="-1">观察者 <a class="header-anchor" href="#观察者" aria-label="Permalink to &quot;观察者&quot;">​</a></h4><p>观察者模式允许对象在状态发生变化时通知其他依赖对象</p><h4 id="装饰器" tabindex="-1">装饰器 <a class="header-anchor" href="#装饰器" aria-label="Permalink to &quot;装饰器&quot;">​</a></h4><p>装饰器模式是指动态地给一个对象增加一些额外的功能，同时又不改变其结构。</p><p>重在功能的加强</p><h3 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux&quot;">​</a></h3><ul><li>ls：列出所有文件及文件夹。</li><li>Pwd：找出当前所在的文件目录。</li><li>ps-ef|grep 名称，找出这个应用进程。</li><li>rm -rf 递归删除，</li><li>cp -rf 递归复制。</li><li>Chmod：给文件改权限。</li><li>lsof -i:端口号 查看端口是否被占用。</li><li>cat 文件名 | grep 关键字，从文件中查找该关键字的记录。</li><li>tail -f 文件名查看文件里面的内容，实时打印。</li><li>vi：编辑文件</li><li>set nu:给文件标识行数。</li><li>Linux 创建文件的几种方式：touch 文件名，vi 和 vim，echo</li></ul><h3 id="回答技巧" tabindex="-1">回答技巧 <a class="header-anchor" href="#回答技巧" aria-label="Permalink to &quot;回答技巧&quot;">​</a></h3><ul><li>1、当时遇到的场景，难点在什么地方，你怎么解决的，相关的技术选型</li><li>2、结合项目场景去回答一些问题</li></ul><h3 id="排序算法" tabindex="-1">排序算法 <a class="header-anchor" href="#排序算法" aria-label="Permalink to &quot;排序算法&quot;">​</a></h3><h4 id="冒泡排序" tabindex="-1">冒泡排序 <a class="header-anchor" href="#冒泡排序" aria-label="Permalink to &quot;冒泡排序&quot;">​</a></h4><p>冒泡排序是一种简单的排序算法。它重复地遍历待排序的序列，一次比较两个元素，如果它们的顺序错误就交换它们。遍历序列的工作重复进行，直到没有需要交换的元素为止。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>public class BubbleSort {</span></span>
<span class="line"><span>    public static void bubbleSort(int[] arr) {</span></span>
<span class="line"><span>        int n = arr.length;</span></span>
<span class="line"><span>        boolean swapped;</span></span>
<span class="line"><span>        for (int i = 0; i &lt; n - 1; i++) {</span></span>
<span class="line"><span>            swapped = false;</span></span>
<span class="line"><span>            for (int j = 0; j &lt; n - 1 - i; j++) {</span></span>
<span class="line"><span>                if (arr[j] &gt; arr[j + 1]) {</span></span>
<span class="line"><span>                    // 交换 arr[j] 和 arr[j+1]</span></span>
<span class="line"><span>                    int temp = arr[j];</span></span>
<span class="line"><span>                    arr[j] = arr[j + 1];</span></span>
<span class="line"><span>                    arr[j + 1] = temp;</span></span>
<span class="line"><span>                    swapped = true;</span></span>
<span class="line"><span>                }</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span>            // 如果没有发生交换，说明数组已经有序</span></span>
<span class="line"><span>            if (!swapped) break;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    public static void main(String[] args) {</span></span>
<span class="line"><span>        int[] arr = {64, 34, 25, 12, 22, 11, 90};</span></span>
<span class="line"><span>        bubbleSort(arr);</span></span>
<span class="line"><span>        System.out.println(&quot;Sorted array:&quot;);</span></span>
<span class="line"><span>        for (int num : arr) {</span></span>
<span class="line"><span>            System.out.print(num + &quot; &quot;);</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><h4 id="快速排序" tabindex="-1">快速排序 <a class="header-anchor" href="#快速排序" aria-label="Permalink to &quot;快速排序&quot;">​</a></h4><p>快速排序是一个高效的排序算法，采用分治法策略。它的基本思想是选择一个“基准”元素，然后将待排序的序列分成两个子序列，一个比基准元素小，一个比基准元素大，然后递归地对这两个子序列进行排序。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>public class QuickSort {</span></span>
<span class="line"><span>    public static void quickSort(int[] arr, int low, int high) {</span></span>
<span class="line"><span>        if (low &lt; high) {</span></span>
<span class="line"><span>            // pi 是分割点索引，arr[pi] 已经在正确的位置</span></span>
<span class="line"><span>            int pi = partition(arr, low, high);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>            // 递归地对左右子数组排序</span></span>
<span class="line"><span>            quickSort(arr, low, pi - 1);</span></span>
<span class="line"><span>            quickSort(arr, pi + 1, high);</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    public static int partition(int[] arr, int low, int high) {</span></span>
<span class="line"><span>        int pivot = arr[high];</span></span>
<span class="line"><span>        int i = (low - 1); // 较小元素的索引</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        for (int j = low; j &lt; high; j++) {</span></span>
<span class="line"><span>            // 如果当前元素小于或等于 pivot</span></span>
<span class="line"><span>            if (arr[j] &lt;= pivot) {</span></span>
<span class="line"><span>                i++;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>                // 交换 arr[i] 和 arr[j]</span></span>
<span class="line"><span>                int temp = arr[i];</span></span>
<span class="line"><span>                arr[i] = arr[j];</span></span>
<span class="line"><span>                arr[j] = temp;</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        // 交换 arr[i+1] 和 arr[high] (或 pivot)</span></span>
<span class="line"><span>        int temp = arr[i + 1];</span></span>
<span class="line"><span>        arr[i + 1] = arr[high];</span></span>
<span class="line"><span>        arr[high] = temp;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        return i + 1;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    public static void main(String[] args) {</span></span>
<span class="line"><span>        int[] arr = {64, 34, 25, 12, 22, 11, 90};</span></span>
<span class="line"><span>        quickSort(arr, 0, arr.length - 1);</span></span>
<span class="line"><span>        System.out.println(&quot;Sorted array:&quot;);</span></span>
<span class="line"><span>        for (int num : arr) {</span></span>
<span class="line"><span>            System.out.print(num + &quot; &quot;);</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><h4 id="二分查找" tabindex="-1">二分查找 <a class="header-anchor" href="#二分查找" aria-label="Permalink to &quot;二分查找&quot;">​</a></h4><p>略</p><h3 id="编程题" tabindex="-1">编程题 <a class="header-anchor" href="#编程题" aria-label="Permalink to &quot;编程题&quot;">​</a></h3><h3 id="hr" tabindex="-1">Hr <a class="header-anchor" href="#hr" aria-label="Permalink to &quot;Hr&quot;">​</a></h3><h4 id="你对我们公司有什么想问的吗" tabindex="-1">你对我们公司有什么想问的吗 <a class="header-anchor" href="#你对我们公司有什么想问的吗" aria-label="Permalink to &quot;你对我们公司有什么想问的吗&quot;">​</a></h4><p>常规回答：谈公司的历史，产品</p><p>想必，绝大多数的求职者，在面试前会做准备功课。而对公司历史、产品的了解，则是必须掌握的 一项内容。如果你真的不知道该如何回答“你对公司有什么想法”这样的问题的话，不妨先说一说你 了解的公司概况，让面试官知道，你是有备而来，而不是来打酱油的</p><h4 id="你有什么优缺点" tabindex="-1">你有什么优缺点 <a class="header-anchor" href="#你有什么优缺点" aria-label="Permalink to &quot;你有什么优缺点&quot;">​</a></h4><p>优点：对工作认真负责，对自己的代码整洁程度和功能性有要求，测试比较充分，对待工作比较认真；</p><p>缺点：有时候会自己会对某个工作想着要做完可能搞的比较晚，自己的作息不是太规律；（尽量说生活的缺点）不太会做饭。</p>`,515))])}const S=t(d,[["render",h]]);export{P as __pageData,S as default};
